          <tr className="bg-slate-200"><td colSpan={2} className="p-2 font-black text-slate-800">ASSETS</td></tr>
          {currentAssets.elements}
          <tr className="h-2"></tr>
          {fixedAssets.elements}
          <tr className="bg-slate-800 text-white font-bold">
            <td className="p-3">TOTAL ASSETS</td>
            <td className="p-3 text-right font-mono text-lg">${totalAssets.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
          </tr>

          <tr className="h-8"></tr>

          {/* LIABILITIES & EQUITY */}
          <tr className="bg-slate-200"><td colSpan={2} className="p-2 font-black text-slate-800">LIABILITIES & EQUITY</td></tr>
          {currentLiabilities.elements}
          <tr className="h-2"></tr>
          {longTermLiabilities.elements}
          <tr className="font-bold bg-white">
            <td className="p-2 italic">Total Liabilities</td>
            <td className="p-2 text-right font-mono border-t-2 border-slate-900">{totalLiabilities.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
          </tr>

          <tr className="h-4"></tr>

          {equityBase.elements}
          <tr className="border-b">
            <td className="p-2 pl-6 text-sm">Current Period Net Income / (Loss)</td>
            <td className={`p-2 text-right text-sm font-mono ${netIncome < 0 ? 'text-red-500' : ''}`}>
              {netIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })}
            </td>
          </tr>
          <tr className="font-bold bg-white">
            <td className="p-2 pl-4 italic">Total Equity</td>
            <td className="p-2 text-right font-mono border-t-2 border-slate-900">{totalEquity.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
          </tr>

          <tr className="h-2"></tr>
