      </table>

      <div className="mt-8 flex justify-end gap-2 text-xs font-bold uppercase italic">
        <span className={Math.abs(totalAssets - (totalLiabilities + totalEquity)) < 0.01 ? 'text-emerald-600' : 'text-red-600'}>
          {Math.abs(totalAssets - (totalLiabilities + totalEquity)) < 0.01 ? '✓ Balanced' : '⚠ Warning: Out of Balance'}
        </span>
      </div>
    </div>
  );
};

