import React from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
}

const IncomeStatement: React.FC<Props> = ({ transactions, accounts }) => {
  const getBalance = (accountId: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = 0;
    transactions.forEach(tx => {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) {
            balance += (l.debit - l.credit);
          } else {
            balance += (l.credit - l.debit);
          }
        }
      });
    });
    return balance;
  };

  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);

  const calculateTotal = (classification: AccountClassification) => {
    return isAccounts
      .filter(a => a.classification === classification)
      .reduce((sum, a) => sum + getBalance(a.id), 0);
  };

  const revenue = calculateTotal(AccountClassification.REVENUE);
  const cogs = calculateTotal(AccountClassification.COGS);
  const grossProfit = revenue - cogs;
  const opExpenses = calculateTotal(AccountClassification.OPERATING_EXPENSE);
  const operatingIncome = grossProfit - opExpenses;
  const otherItems = calculateTotal(AccountClassification.OTHER_INCOME_EXPENSE);
  const netIncome = operatingIncome + otherItems;

  const renderSection = (title: string, classification: AccountClassification) => {
    const filtered = isAccounts.filter(a => a.classification === classification);
    return filtered.map(acc => (
      <tr key={acc.id} className="border-b">
        <td className="p-2 pl-6 text-sm">{acc.name}</td>
        <td className="p-2 text-right text-sm font-mono">{getBalance(acc.id).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
      </tr>
    ));
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold uppercase">Income Statement</h2>
        <p className="text-gray-500 font-medium italic">Vista Shore Products, LLC</p>
        <p className="text-gray-400 text-sm">For the period ended {new Date().toLocaleDateString()}</p>
      </div>

      <table className="w-full border-t-4 border-slate-900">
        <tbody>
          {/* REVENUE */}
          <tr className="bg-slate-50"><td colSpan={2} className="p-2 font-bold text-slate-800">REVENUE</td></tr>
          {renderSection("Revenue", AccountClassification.REVENUE)}
          <tr className="font-bold border-t-2 border-slate-900">
            <td className="p-2">Total Revenue</td>
            <td className="p-2 text-right font-mono">{revenue.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
          </tr>

          <tr className="h-4"></tr>

          {/* COGS */}
          <tr className="bg-slate-50"><td colSpan={2} className="p-2 font-bold text-slate-800">COST OF GOODS SOLD</td></tr>
          {renderSection("COGS", AccountClassification.COGS)}
          <tr className="font-bold border-t-2 border-slate-900">
            <td className="p-2">Total Cost of Goods Sold</td>
            <td className="p-2 text-right font-mono">{cogs.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
          </tr>

          <tr className="bg-slate-200 font-bold border-y-2 border-slate-400">
            <td className="p-2">GROSS PROFIT</td>
            <td className="p-2 text-right font-mono">${grossProfit.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
          </tr>

          <tr className="h-4"></tr>

          {/* OPERATING EXPENSES */}
          <tr className="bg-slate-50"><td colSpan={2} className="p-2 font-bold text-slate-800">OPERATING EXPENSES</td></tr>
          {renderSection("Operating Expenses", AccountClassification.OPERATING_EXPENSE)}
          <tr className="font-bold border-t-2 border-slate-900">
            <td className="p-2">Total Operating Expenses</td>
            <td className="p-2 text-right font-mono">{opExpenses.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
          </tr>

          <tr className="bg-slate-100 font-bold border-y-2 border-slate-300">
            <td className="p-2 pl-4 italic">OPERATING INCOME</td>
            <td className="p-2 text-right font-mono">{operatingIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
          </tr>

          <tr className="h-4"></tr>

          {/* OTHER */}
          <tr className="bg-slate-50"><td colSpan={2} className="p-2 font-bold text-slate-800">OTHER INCOME / (EXPENSE)</td></tr>
          {renderSection("Other Items", AccountClassification.OTHER_INCOME_EXPENSE)}

          <tr className="h-8"></tr>

          <tr className="bg-slate-800 text-white font-bold text-lg">
            <td className="p-3">NET INCOME / (LOSS)</td>
            <td className={`p-3 text-right font-mono ${netIncome < 0 ? 'text-red-300' : 'text-emerald-300'}`}>
              ${netIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })}
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};

