import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [showAccountModal, setShowAccountModal] = useState(false);

  useEffect(() => {
    const savedAccounts = localStorage.getItem('vista_accounts');
    const savedTransactions = localStorage.getItem('vista_transactions');
    if (savedAccounts) setAccounts(JSON.parse(savedAccounts));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
  }, []);

  useEffect(() => {
    localStorage.setItem('vista_accounts', JSON.stringify(accounts));
    localStorage.setItem('vista_transactions', JSON.stringify(transactions));
  }, [accounts, transactions]);

  const addAccount = (newAcc: Account) => {
    setAccounts(prev => [...prev, newAcc]);
  };

  const recordTransaction = (entry: JournalEntry) => {
    setTransactions(prev => [...prev, entry]);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Are you sure you want to delete Transaction #${id}?`)) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const tabs: TabType[] = [
    'Dashboard',
    'Transaction Recorder',
    'Ledgers',
    'General Journal',
    'BS',
    'IS',
    'CF',
    'Trial Balance'
  ];

  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path></svg>
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">VISTA SHORE PRODUCTS, LLC</h1>
            <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-[0.2em]">Enterprise Resource Planning</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={() => setShowAccountModal(true)}
            className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-2 px-6 rounded-lg transition-all text-sm shadow-md"
          >
            + Create Account
          </button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-4 text-sm font-semibold whitespace-nowrap transition-all border-b-4 ${
              activeTab === tab 
                ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' 
                : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
            }`}
          >
            {tab}
          </button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && (
              <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} />
            )}
            {activeTab === 'Transaction Recorder' && (
              <TransactionRecorder 
                accounts={accounts} 
                onRecord={recordTransaction} 
                lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 537}
              />
            )}
            {activeTab === 'General Journal' && (
              <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} />
            )}
            {activeTab === 'Ledgers' && (
              <Ledgers transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'BS' && (
              <BalanceSheet transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'IS' && (
              <IncomeStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'CF' && (
              <CashFlowStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'Trial Balance' && (
              <TrialBalance transactions={transactions} accounts={accounts} />
            )}
          </div>
        </div>
      </main>

      {showAccountModal && (
        <AccountModal 
          onClose={() => setShowAccountModal(false)} 
          onSave={addAccount} 
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification, TabType } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onNavigate: (tab: TabType) => void;
}

const Dashboard: React.FC<Props> = ({ transactions, accounts, onNavigate }) => {
  const getBalance = (accountId: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;
    let balance = 0;
    transactions.forEach(tx => {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
          else balance += (l.credit - l.debit);
        }
      });
    });
    return balance;
  };

  const cash = accounts.filter(a => a.name.toLowerCase().includes('cash')).reduce((sum, a) => sum + getBalance(a.id), 0);
  const ar = accounts.filter(a => a.name.toLowerCase().includes('receivable')).reduce((sum, a) => sum + getBalance(a.id), 0);
  const liabilities = accounts.filter(a => a.classification === AccountClassification.CURRENT_LIABILITY || a.classification === AccountClassification.LONG_TERM_LIABILITY).reduce((sum, a) => sum + getBalance(a.id), 0);

  // Net Income calculation
  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
  let netIncome = 0;
  isAccounts.forEach(acc => {
    const b = getBalance(acc.id);
    if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
       netIncome += b; 
    } else {
       netIncome -= b;
    }
  });

  const stats = [
    { name: 'Cash on Hand', value: cash, color: 'text-emerald-600', bg: 'bg-emerald-50', icon: '💰' },
    { name: 'Accounts Receivable', value: ar, color: 'text-blue-600', bg: 'bg-blue-50', icon: '📥' },
    { name: 'Total Liabilities', value: liabilities, color: 'text-amber-600', bg: 'bg-amber-50', icon: '💳' },
    { name: 'Net Income (MTD)', value: netIncome, color: netIncome >= 0 ? 'text-emerald-600' : 'text-red-600', bg: netIncome >= 0 ? 'bg-emerald-50' : 'bg-red-50', icon: '📈' },
  ];

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-3xl font-extrabold text-slate-900">Financial Overview</h2>
        <p className="text-slate-500">Real-time health of Vista Shore Products, LLC</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat) => (
          <div key={stat.name} className={`${stat.bg} p-6 rounded-2xl border border-white shadow-sm transition-all hover:shadow-md`}>
            <div className="flex justify-between items-start mb-4">
              <span className="text-2xl">{stat.icon}</span>
              <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Live</span>
            </div>
            <p className="text-sm font-semibold text-slate-600 mb-1">{stat.name}</p>
            <p className={`text-2xl font-black font-mono ${stat.color}`}>
              ${stat.value.toLocaleString(undefined, { minimumFractionDigits: 2 })}
            </p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mt-12">
        <div className="bg-slate-50 p-6 rounded-2xl border">
          <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <span className="w-2 h-6 bg-emerald-500 rounded-full"></span>
            Quick Actions
          </h3>
          <div className="grid grid-cols-2 gap-4">
            <button 
              onClick={() => onNavigate('Transaction Recorder')}
              className="bg-white p-4 rounded-xl border hover:border-emerald-500 hover:text-emerald-600 transition-all font-bold text-sm text-left shadow-sm"
            >
              Record New JE
            </button>
            <button 
              onClick={() => onNavigate('BS')}
              className="bg-white p-4 rounded-xl border hover:border-emerald-500 hover:text-emerald-600 transition-all font-bold text-sm text-left shadow-sm"
            >
              View Balance Sheet
            </button>
            <button 
              onClick={() => onNavigate('IS')}
              className="bg-white p-4 rounded-xl border hover:border-emerald-500 hover:text-emerald-600 transition-all font-bold text-sm text-left shadow-sm"
            >
              Income Statement
            </button>
            <button 
              onClick={() => onNavigate('Trial Balance')}
              className="bg-white p-4 rounded-xl border hover:border-emerald-500 hover:text-emerald-600 transition-all font-bold text-sm text-left shadow-sm"
            >
              Trial Balance
            </button>
          </div>
        </div>

        <div className="bg-slate-50 p-6 rounded-2xl border">
          <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <span className="w-2 h-6 bg-blue-500 rounded-full"></span>
            Recent Transactions
          </h3>
          <div className="space-y-3">
            {transactions.slice(-5).reverse().map(t => (
              <div key={t.id} className="bg-white p-3 rounded-lg border shadow-xs flex justify-between items-center text-sm">
                <div>
                  <span className="font-bold text-slate-400 mr-2">#{t.id}</span>
                  <span className="font-medium">{t.date}</span>
                </div>
                <div className="font-mono font-bold text-slate-700">
                  ${t.lines.filter(l => l.debit > 0).reduce((s,l) => s + l.debit, 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </div>
              </div>
            ))}
            {transactions.length === 0 && <p className="text-center text-slate-400 italic py-8">No transactions yet.</p>}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

