import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
}

const IncomeStatement: React.FC<Props> = ({ transactions, accounts }) => {
  // Extract all unique months from transactions for columns
  const periods = useMemo(() => {
    const unique = new Set<string>();
    transactions.forEach(t => {
      const date = new Date(t.date);
      if (!isNaN(date.getTime())) {
        unique.add(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`);
      }
    });
    return Array.from(unique).sort().reverse(); // Show latest first or oldest first? Let's go sort() then reverse for standard flow
  }, [transactions]);

  const getBalance = (accountId: string, period?: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = 0;
    transactions.forEach(tx => {
      // If period filter is applied
      if (period) {
        const txPeriod = `${new Date(tx.date).getFullYear()}-${String(new Date(tx.date).getMonth() + 1).padStart(2, '0')}`;
        if (txPeriod !== period) return;
      }

      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) {
            balance += (l.debit - l.credit);
          } else {
            balance += (l.credit - l.debit);
          }
        }
      });
    });
    return balance;
  };

  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);

  const calculateTotal = (classification: AccountClassification, period?: string) => {
    return isAccounts
      .filter(a => a.classification === classification)
      .reduce((sum, a) => sum + getBalance(a.id, period), 0);
  };

  const renderCells = (id: string | AccountClassification, isClassification: boolean) => {
    return periods.map(p => {
      const val = isClassification 
        ? calculateTotal(id as AccountClassification, p)
        : getBalance(id as string, p);
      return (
        <td key={p} className={`p-2 text-right font-mono text-xs ${val < 0 ? 'text-red-600' : ''}`}>
          {val.toLocaleString(undefined, { minimumFractionDigits: 2 })}
        </td>
      );
    });
  };

  const renderNetIncomeCells = () => {
    return periods.map(p => {
      const rev = calculateTotal(AccountClassification.REVENUE, p);
      const cogs = calculateTotal(AccountClassification.COGS, p);
      const op = calculateTotal(AccountClassification.OPERATING_EXPENSE, p);
      const other = calculateTotal(AccountClassification.OTHER_INCOME_EXPENSE, p);
      const net = (rev - cogs) - op + other;
      return (
        <td key={p} className={`p-2 text-right font-mono font-bold text-sm ${net < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
          {net.toLocaleString(undefined, { minimumFractionDigits: 2 })}
        </td>
      );
    });
  };

  const renderSection = (title: string, classification: AccountClassification) => {
    const filtered = isAccounts.filter(a => a.classification === classification);
    return (
      <>
        <tr className="bg-slate-50"><td colSpan={periods.length + 1} className="p-2 font-bold text-slate-800 uppercase text-[10px] tracking-widest">{title}</td></tr>
        {filtered.map(acc => (
          <tr key={acc.id} className="border-b hover:bg-slate-50">
            <td className="p-2 pl-6 text-xs font-medium text-slate-600">{acc.name}</td>
            {renderCells(acc.id, false)}
          </tr>
        ))}
        <tr className="font-bold border-t border-slate-400">
          <td className="p-2 pl-4 text-xs italic">Total {title}</td>
          {renderCells(classification, true)}
        </tr>
      </>
    );
  };

  return (
    <div className="w-full">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold uppercase">Monthly Comparative Income Statement</h2>
        <p className="text-gray-500 font-medium italic">Vista Shore Products, LLC</p>
      </div>

      <div className="overflow-x-auto border rounded-xl shadow-sm">
        <table className="w-full border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-800 text-white">
              <th className="p-3 text-left w-64 border-r border-slate-700">Accounts</th>
              {periods.map(p => (
                <th key={p} className="p-3 text-right text-xs uppercase tracking-tighter">
                  {new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {renderSection("Revenue", AccountClassification.REVENUE)}
            <tr className="h-4"></tr>
            {renderSection("Cost of Goods Sold", AccountClassification.COGS)}
            <tr className="h-4"></tr>
            {renderSection("Operating Expenses", AccountClassification.OPERATING_EXPENSE)}
            <tr className="h-4"></tr>
            {renderSection("Other Income / (Expenses)", AccountClassification.OTHER_INCOME_EXPENSE)}
            <tr className="h-8"></tr>
            <tr className="bg-slate-900 text-white">
              <td className="p-3 font-black text-xs uppercase tracking-widest">NET INCOME / (LOSS)</td>
              {renderNetIncomeCells()}
            </tr>
          </tbody>
        </table>
      </div>
      {periods.length === 0 && (
        <div className="p-20 text-center text-slate-400 italic">No historical data found. Please record transactions to see monthly breakdown.</div>
      )}
    </div>
  );
};

export default IncomeStatement;

import React, { useRef } from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification } from '../types';

interface Props {
  accounts: Account[];
  onImport: (transactions: JournalEntry[], accounts: Account[]) => void;
}

const DataManager: React.FC<Props> = ({ accounts, onImport }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const downloadTemplate = () => {
    const headers = "Date,Method,Account Name,Debit,Credit,Description,TransactionID\n";
    const example = "2023-10-25,AmEx,Cash,150.00,0,Starting Balance,1001\n2023-10-25,AmEx,Revenue,0,150.00,Sales,1001";
    const blob = new Blob([headers + example], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'vista_import_template.csv';
    a.click();
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const csv = event.target?.result as string;
      parseCSV(csv);
    };
    reader.readAsText(file);
  };

  const parseCSV = (csv: string) => {
    const lines = csv.split('\n');
    const headers = lines[0].split(',').map(h => h.trim());

    // Simple mapping logic
    const txMap: Record<number, JournalEntry> = {};
    const newAccounts: Account[] = [];

    for (let i = 1; i < lines.length; i++) {
      if (!lines[i].trim()) continue;
      const values = lines[i].split(',').map(v => v.trim());

      const date = values[0];
      const method = values[1];
      const accName = values[2];
      const debit = parseFloat(values[3]) || 0;
      const credit = parseFloat(values[4]) || 0;
      const desc = values[5];
      const txId = parseInt(values[6]) || Math.floor(Math.random() * 10000);

      // 1. Find or Prepare Account
      let account = accounts.find(a => a.name.toLowerCase() === accName.toLowerCase());
      if (!account) {
          // Check if we already staged this new account in this batch
          account = newAccounts.find(a => a.name.toLowerCase() === accName.toLowerCase());
          if (!account) {
              const isRevenue = accName.toLowerCase().includes('revenue') || accName.toLowerCase().includes('sales');
              const isExpense = accName.toLowerCase().includes('expense') || accName.toLowerCase().includes('cost');

              account = {
                  id: Math.random().toString(),
                  name: accName,
                  naturalBalance: (isRevenue || accName.toLowerCase().includes('payable')) ? NaturalBalance.CREDIT : NaturalBalance.DEBIT,
                  financialStatement: (isRevenue || isExpense) ? FinancialStatement.INCOME_STATEMENT : FinancialStatement.BALANCE_SHEET,
                  classification: isRevenue ? AccountClassification.REVENUE : (isExpense ? AccountClassification.OPERATING_EXPENSE : AccountClassification.CURRENT_ASSET)
              };
              newAccounts.push(account);
          }
      }

      // 2. Build Transaction
      if (!txMap[txId]) {
        txMap[txId] = {
          id: txId,
          date,
          method,
          lines: []
        };
      }

      txMap[txId].lines.push({
        id: Math.random().toString(),
        accountId: account.id,
        debit,
        credit,
        description: desc
      });
    }

    onImport(Object.values(txMap), newAccounts);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12">
      <div className="bg-emerald-50 border border-emerald-200 p-8 rounded-2xl flex flex-col md:flex-row items-center gap-8 shadow-sm">
        <div className="flex-1 space-y-4">
          <h2 className="text-2xl font-black text-emerald-900">Historical Import</h2>
          <p className="text-emerald-700 leading-relaxed">
            Move your existing Excel data into Vista Shore Accounting. Download our template, 
            copy your columns into it, and upload. Our system will automatically group entries 
            by Transaction ID and generate your chart of accounts.
          </p>
          <div className="flex gap-4">
            <button 
              onClick={downloadTemplate}
              className="bg-white text-emerald-600 border border-emerald-300 px-6 py-2 rounded-lg font-bold hover:bg-emerald-100 transition-colors"
            >
              Download Template
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="bg-emerald-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-emerald-700 shadow-md shadow-emerald-200"
            >
              Upload Completed CSV
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept=".csv"
              onChange={handleFileUpload} 
            />
          </div>
        </div>
        <div className="w-32 h-32 bg-emerald-100 rounded-full flex items-center justify-center text-4xl">
          📥
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="p-6 border rounded-2xl bg-slate-50">
          <h3 className="font-bold text-slate-800 mb-2">CSV Column Mapping</h3>
          <ul className="text-sm space-y-2 text-slate-500">
            <li><span className="font-mono text-emerald-600 font-bold">Date:</span> YYYY-MM-DD format</li>
            <li><span className="font-mono text-emerald-600 font-bold">Method:</span> Payment type or card name</li>
            <li><span className="font-mono text-emerald-600 font-bold">Account Name:</span> Exact match is best</li>
            <li><span className="font-mono text-emerald-600 font-bold">Debit/Credit:</span> Numerical values</li>
            <li><span className="font-mono text-emerald-600 font-bold">TransactionID:</span> Group lines together</li>
          </ul>
        </div>
        <div className="p-6 border rounded-2xl bg-slate-50">
          <h3 className="font-bold text-slate-800 mb-2">Safety Notes</h3>
          <p className="text-sm text-slate-500 leading-relaxed">
            Importing data will not delete existing records. It appends new transactions. 
            If the account name in your CSV doesn't exist, the system will guess its 
            classification based on common keywords (e.g., "Revenue", "Expense").
          </p>
        </div>
      </div>
    </div>
  );
};

