interface Props {
  onClose: () => void;
  onSave: (acc: Account) => void;
}

const AccountModal: React.FC<Props> = ({ onClose, onSave }) => {
  const [name, setName] = useState('');
  const [naturalBal, setNaturalBal] = useState<NaturalBalance>(NaturalBalance.DEBIT);
  const [statement, setStatement] = useState<FinancialStatement>(FinancialStatement.BALANCE_SHEET);
  const [classification, setClassification] = useState<AccountClassification>(AccountClassification.CURRENT_ASSET);
  const [startBalance, setStartBalance] = useState<string>('0');

  // Sync classification when statement changes
  useEffect(() => {
    const validClassifications = STATEMENT_CLASSIFICATION_MAP[statement];
    if (!validClassifications.includes(classification)) {
      setClassification(validClassifications[0]);
    }
  }, [statement]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;

    onSave({
      id: Math.random().toString(),
      name,
      naturalBalance: naturalBal,
      financialStatement: statement,
      classification,
      startingBalance: parseFloat(startBalance) || 0
    });
    onClose();
  };

  const currentClassifications = STATEMENT_CLASSIFICATION_MAP[statement];

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all animate-in fade-in zoom-in duration-200">
        <div className="bg-slate-800 text-white p-4 flex justify-between items-center">
          <h2 className="text-xl font-bold">New Account Creation</h2>
          <button onClick={onClose} className="hover:text-gray-300">✕</button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Account Name</label>
            <input 
              autoFocus
              required
              type="text" 
              value={name} 
              onChange={(e) => setName(e.target.value)}
              className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none"
              placeholder="e.g. Sales Revenue"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">Natural Balance</label>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => setNaturalBal(NaturalBalance.DEBIT)}
                  className={`flex-1 py-2 rounded border text-sm font-bold transition-colors ${naturalBal === NaturalBalance.DEBIT ? 'bg-emerald-100 border-emerald-500 text-emerald-700' : 'bg-gray-50 border-gray-200'}`}
                >
                  DEBIT
                </button>
                <button
                  type="button"
                  onClick={() => setNaturalBal(NaturalBalance.CREDIT)}
                  className={`flex-1 py-2 rounded border text-sm font-bold transition-colors ${naturalBal === NaturalBalance.CREDIT ? 'bg-amber-100 border-amber-500 text-amber-700' : 'bg-gray-50 border-gray-200'}`}
                >
                  CREDIT
                </button>
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">Statement Purpose</label>
              <select 
                value={statement}
                onChange={(e) => setStatement(e.target.value as FinancialStatement)}
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none text-sm"
              >
                {STATEMENTS.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">Classification</label>
              <select 
                value={classification}
                onChange={(e) => setClassification(e.target.value as AccountClassification)}
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none text-sm"
              >
                {currentClassifications.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">Starting Balance</label>
              <input 
                type="number"
                step="0.01"
                value={startBalance}
                onChange={(e) => setStartBalance(e.target.value)}
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none text-sm font-mono"
              />
            </div>
          </div>

          <div className="pt-4 flex gap-3">
            <button 
              type="button"
              onClick={onClose}
              className="flex-1 bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold py-3 rounded-lg transition-colors"
            >
              Cancel
            </button>
            <button 
              type="submit"
              className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 rounded-lg shadow-lg shadow-emerald-200 transition-all active:scale-95"
            >
              Create Account
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AccountModal;

import React, { useState, useEffect } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';
import { STATEMENTS, STATEMENT_CLASSIFICATION_MAP } from '../constants';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onUpdateAccount: (id: string, updatedFields: Partial<Account>) => void;
  onDeleteAccount: (id: string) => void;
  onDeleteTransaction: (id: number) => void;
}

const Ledgers: React.FC<Props> = ({ transactions, accounts = [], onUpdateAccount, onDeleteAccount, onDeleteTransaction }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState<Account | null>(null);

  const sortedAccounts = [...accounts].sort((a, b) => {
    if (a.isArchived && !b.isArchived) return 1;
    if (!a.isArchived && b.isArchived) return -1;
    return a.name.localeCompare(b.name);
  });

  const startEditing = (account: Account) => {
    setEditingId(account.id);
    setEditDraft({ ...account });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const saveEdit = () => {
    if (editingId && editDraft) {
      onUpdateAccount(editingId, {
        name: editDraft.name.trim(),
        classification: editDraft.classification,
        naturalBalance: editDraft.naturalBalance,
        financialStatement: editDraft.financialStatement,
        startingBalance: Number(editDraft.startingBalance) || 0
      });
      cancelEditing();
    }
  };

  const updateDraft = (field: keyof Account, value: any) => {
    if (!editDraft) return;

    const newDraft = { ...editDraft, [field]: value };

    // If financialStatement changed, ensure classification is valid
    if (field === 'financialStatement') {
      const validClassifications = STATEMENT_CLASSIFICATION_MAP[value as FinancialStatement];
      if (!validClassifications.includes(newDraft.classification)) {
        newDraft.classification = validClassifications[0];
      }
    }

    setEditDraft(newDraft);
  };

  return (
    <div className="space-y-10">
      <div className="flex justify-between items-center border-b pb-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Account Ledgers</h2>
          <p className="text-xs text-slate-500 mt-1 font-medium">Manage anchor balances and individual audit trails.</p>
        </div>
        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Historical Verification Mode</div>
      </div>

      {sortedAccounts.map(account => {
        const startBal = Number(account.startingBalance) || 0;

        const accountLines = (transactions || []).flatMap(t => 
          t.lines
            .filter(l => l.accountId === account.id)
            .map(l => ({ ...l, date: t.date, txId: t.id, method: t.method }))
        ).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

        let runningBalance = startBal;
        const isEditing = editingId === account.id;

        return (
          <div key={account.id} className={`border rounded-xl shadow-sm overflow-hidden ${account.isArchived ? 'opacity-50 grayscale' : ''} ${account.financialStatement === FinancialStatement.OFF_STATEMENT ? 'border-amber-100 shadow-amber-50/20' : ''}`}>
            {/* Header / Edit Controls */}
            <div className={`${isEditing ? 'bg-slate-900' : account.financialStatement === FinancialStatement.OFF_STATEMENT ? 'bg-slate-700' : 'bg-slate-800'} text-white p-4 flex flex-wrap items-center justify-between gap-4 transition-colors`}>
              <div className="flex items-center gap-4 group">
                {isEditing && editDraft ? (
                  <div className="flex flex-wrap items-center gap-3">
                    <div className="flex flex-col">
                      <label className="text-[9px] text-emerald-400 font-black uppercase">Account Name</label>
                      <input type="text" value={editDraft.name} onChange={(e) => updateDraft('name', e.target.value)} className="bg-slate-800 text-white px-3 py-1.5 rounded border border-slate-600 text-sm font-bold w-48" />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-[9px] text-emerald-400 font-black uppercase">Natural Balance</label>
                      <div className="flex bg-slate-800 border border-slate-600 rounded overflow-hidden mt-[2px]">
                        <button 
                          onClick={() => updateDraft('naturalBalance', NaturalBalance.DEBIT)}
                          className={`px-3 py-1 text-[10px] font-bold ${editDraft.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-600 text-white' : 'text-slate-400 hover:text-white'}`}
                        >
                          DR
                        </button>
                        <button 
                          onClick={() => updateDraft('naturalBalance', NaturalBalance.CREDIT)}
                          className={`px-3 py-1 text-[10px] font-bold ${editDraft.naturalBalance === NaturalBalance.CREDIT ? 'bg-amber-600 text-white' : 'text-slate-400 hover:text-white'}`}
                        >
                          CR
                        </button>
                      </div>
                    </div>
                    <div className="flex flex-col">
                      <label className="text-[9px] text-emerald-400 font-black uppercase">Report Type</label>
                      <select value={editDraft.financialStatement} onChange={(e) => updateDraft('financialStatement', e.target.value as FinancialStatement)} className="bg-slate-800 text-xs font-bold border border-slate-600 px-2 py-1.5 rounded h-[34px] mt-[2px]">
                        {STATEMENTS.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div className="flex flex-col">
                      <label className="text-[9px] text-emerald-400 font-black uppercase">Classification</label>
                      <select value={editDraft.classification} onChange={(e) => updateDraft('classification', e.target.value as AccountClassification)} className="bg-slate-800 text-xs font-bold border border-slate-600 px-2 py-1.5 rounded h-[34px] mt-[2px]">
                        {STATEMENT_CLASSIFICATION_MAP[editDraft.financialStatement].map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                    <div className="flex flex-col">
                      <label className="text-[9px] text-emerald-400 font-black uppercase">Dictate Start Bal</label>
                      <input type="number" step="0.01" value={editDraft.startingBalance} onChange={(e) => updateDraft('startingBalance', e.target.value)} className="bg-slate-800 text-white px-2 py-1.5 rounded border border-slate-600 text-sm font-mono w-28 focus:ring-1 focus:ring-emerald-500" />
                    </div>
                    <div className="flex gap-2 ml-4 self-end pb-1">
                      <button onClick={saveEdit} className="bg-emerald-600 hover:bg-emerald-500 px-4 py-1.5 rounded text-xs font-bold shadow-lg transition-all">Save</button>
                      <button onClick={cancelEditing} className="bg-slate-700 hover:bg-slate-600 px-4 py-1.5 rounded text-xs font-bold transition-all">Cancel</button>
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="flex flex-col">
                      <h3 className="font-bold text-lg">{account.name}</h3>
                      <div className="flex gap-2 items-center mt-1">
                        {account.financialStatement === FinancialStatement.OFF_STATEMENT && (
                          <span className="text-[9px] font-black uppercase text-amber-400 bg-amber-400/10 px-1 rounded inline-block">Internal / Clearing</span>
                        )}
                        <span className="text-[9px] font-black uppercase text-slate-400 bg-slate-400/10 px-1 rounded inline-block">
                          {account.classification}
                        </span>
                      </div>
                    </div>
                    <button onClick={() => startEditing(account)} className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-white transition-all bg-white/10 p-1.5 rounded-md" title="Edit Account Details">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" strokeWidth="2"></path></svg>
                    </button>
                  </>
                )}
              </div>

              {!isEditing && (
                <div className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-tighter">
                  <div className="flex flex-col items-end">
                    <span className="opacity-50">Opening Balance Forward</span>
                    <span className="text-sm font-mono">${startBal.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
                  </div>
                  <div className={`px-2 py-2 rounded border ${account.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-amber-500/20 text-amber-400 border-amber-500/30'}`}>
                    {account.naturalBalance}
                  </div>
                </div>
              )}
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-xs text-left border-collapse">
                <thead className="bg-slate-100 border-b">
                  <tr>
                    <th className="p-3 border-r w-16 text-slate-500 font-black uppercase text-[9px]">TX ID</th>
                    <th className="p-3 border-r w-24 text-slate-500 font-black uppercase text-[9px]">Date</th>
                    <th className="p-3 border-r text-slate-500 font-black uppercase text-[9px]">Reference</th>
                    <th className="p-3 border-r text-right w-28 text-slate-500 font-black uppercase text-[9px]">Debit</th>
                    <th className="p-3 border-r text-right w-28 text-slate-500 font-black uppercase text-[9px]">Credit</th>
                    <th className="p-3 border-r text-right w-36 text-slate-500 font-black uppercase text-[9px]">Running Balance</th>
                    <th className="p-3 text-slate-500 font-black uppercase text-[9px]">Memo</th>
                    <th className="p-3 w-10"></th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  <tr className="bg-slate-50/50 italic">
                    <td className="p-3 border-r text-slate-300 font-mono">-</td>
                    <td className="p-3 border-r text-slate-400">Opening</td>
                    <td className="p-3 border-r text-slate-400 uppercase text-[9px] font-bold tracking-widest">Account Anchor Point</td>
                    <td className="p-3 border-r text-right font-mono text-slate-300">-</td>
                    <td className="p-3 border-r text-right font-mono text-slate-300">-</td>
                    <td className="p-3 border-r text-right font-mono font-black text-slate-400 bg-slate-100/30">
                      {startBal.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>
                    <td colSpan={2} className="p-3 text-slate-400">Initial Balance Forward (Before system transactions)</td>
                  </tr>

                  {accountLines.length === 0 && (
                    <tr>
                      <td colSpan={8} className="p-6 text-center text-slate-400 italic font-medium">No system transactions recorded. Balance is purely forward-dictated.</td>
                    </tr>
                  )}

                  {accountLines.map((line, idx) => {
                    const netChange = account.naturalBalance === NaturalBalance.DEBIT 
                      ? (line.debit - line.credit) 
                      : (line.credit - line.debit);
                    runningBalance += netChange;

                    return (
                      <tr key={`${line.txId}-${idx}`} className="group hover:bg-slate-50 transition-colors">
                        <td className="p-3 border-r font-mono text-slate-400">{line.txId}</td>
                        <td className="p-3 border-r font-medium text-slate-700">{line.date}</td>
                        <td className="p-3 border-r text-slate-600 truncate max-w-[120px]">{line.method || '-'}</td>
                        <td className="p-3 border-r text-right font-mono font-bold text-emerald-600">
                          {line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                        <td className="p-3 border-r text-right font-mono font-bold text-amber-600">
                          {line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                        <td className={`p-3 border-r text-right font-mono font-black bg-slate-50/50 ${runningBalance < 0 ? 'text-red-500' : 'text-slate-900'}`}>
                          {runningBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                        <td className="p-3 text-slate-500 italic truncate max-w-[200px]">{line.description}</td>
                        <td className="p-3 text-center">
                          <button 
                            onClick={() => {
                              if(window.confirm(`Permanently remove transaction #${line.txId} from this ledger?`)) {
                                onDeleteTransaction(line.txId);
                              }
                            }} 
                            className="opacity-0 group-hover:opacity-100 text-red-300 hover:text-red-600 transition-all text-lg font-bold"
                          >
                            ✕
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            <div className="bg-slate-100/50 p-3 text-[10px] text-right text-slate-500 font-bold uppercase tracking-widest border-t flex justify-end gap-6">
               <span className="opacity-60">Calculated Activity: {(runningBalance - startBal).toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
               <span className="text-slate-900 bg-white px-2 py-0.5 rounded shadow-sm border">Final Adjusted Balance: {runningBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default Ledgers;

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
      } catch (e) {}
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
          accounts: data.accounts,
          transactions: data.transactions,
          closedPeriods: data.closedPeriods || []
        }));
      } else {
        setDoc(userDocRef, { accounts: INITIAL_ACCOUNTS, transactions: [], closedPeriods: [] })
          .catch(err => console.error("Seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      setDataLoading(false);
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = async (newAccs: Account[], newTxs: JournalEntry[], newPeriods: string[]) => {
    if (!user) return;
    localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods
    }));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        accounts: newAccs,
        transactions: newTxs,
        closedPeriods: newPeriods,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Save error:", err);
    }
  };

  const resetSystem = (full: boolean) => {
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(INITIAL_ACCOUNTS, [], []);
    } else {
      // Keep accounts but clear history
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], []);
    }
    setActiveTab('Dashboard');
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      // Just archive it
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods);
    }
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const existingNames = new Set(accounts.map(a => a.name.toLowerCase()));
    const uniqueNew = newAccounts.filter(a => !existingNames.has(a.name.toLowerCase()));
    const updatedAccs = [...accounts, ...uniqueNew];
    const updatedTxs = [...transactions, ...newTransactions];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <h1 className="text-xl font-bold tracking-tighter">VISTA SHORE</h1>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={importData} onReset={resetSystem} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';
import { STATEMENTS, STATEMENT_CLASSIFICATION_MAP } from '../constants';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onUpdateAccount: (id: string, updatedFields: Partial<Account>) => void;
  onDeleteAccount: (id: string) => void;
  onDeleteTransaction: (id: number) => void;
}

const Ledgers: React.FC<Props> = ({ transactions, accounts = [], onUpdateAccount, onDeleteAccount, onDeleteTransaction }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState<Account | null>(null);

  const sortedAccounts = [...accounts].sort((a, b) => {
    if (a.isArchived && !b.isArchived) return 1;
    if (!a.isArchived && b.isArchived) return -1;
    return a.name.localeCompare(b.name);
  });

  const startEditing = (account: Account) => {
    setEditingId(account.id);
    setEditDraft({ ...account });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const saveEdit = () => {
    if (editingId && editDraft) {
      onUpdateAccount(editingId, {
        name: editDraft.name.trim(),
        classification: editDraft.classification,
        naturalBalance: editDraft.naturalBalance,
        financialStatement: editDraft.financialStatement,
        startingBalance: Number(editDraft.startingBalance) || 0
      });
      cancelEditing();
    }
  };

  const updateDraft = (field: keyof Account, value: any) => {
    if (!editDraft) return;

    const newDraft = { ...editDraft, [field]: value };

    if (field === 'financialStatement') {
      const validClassifications = STATEMENT_CLASSIFICATION_MAP[value as FinancialStatement];
      if (!validClassifications.includes(newDraft.classification)) {
        newDraft.classification = validClassifications[0];
      }
    }

    setEditDraft(newDraft);
  };

  const handleDeleteAccount = (account: Account) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === account.id));
    const confirmMsg = hasData 
      ? `This account has transaction history. It will be "Archived" and hidden from new entry pickers, but preserved in ledgers. Proceed?`
      : `Are you sure you want to permanently delete the account "${account.name}"?`;

    if (window.confirm(confirmMsg)) {
      onDeleteAccount(account.id);
    }
  };

  return (
    <div className="space-y-10">
      <div className="flex justify-between items-center border-b pb-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Account Ledgers</h2>
          <p className="text-xs text-slate-500 mt-1 font-medium italic">Manage starting balances and individual audit trails.</p>
        </div>
        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest bg-slate-100 px-3 py-1 rounded-full border">
          Database Integrity Check: Passed
        </div>
      </div>

      {sortedAccounts.map(account => {
        const startBal = Number(account.startingBalance) || 0;
        const accountLines = (transactions || []).flatMap(t => 
          t.lines
            .filter(l => l.accountId === account.id)
            .map(l => ({ ...l, date: t.date, txId: t.id, method: t.method }))
        ).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

        let runningBalance = startBal;
        const isEditing = editingId === account.id;

        return (
          <div key={account.id} className={`border rounded-xl shadow-sm overflow-hidden transition-opacity ${account.isArchived ? 'opacity-40 grayscale hover:grayscale-0 hover:opacity-100' : ''} ${account.financialStatement === FinancialStatement.OFF_STATEMENT ? 'border-amber-100' : 'border-slate-200'}`}>
            <div className={`${isEditing ? 'bg-slate-900' : account.isArchived ? 'bg-slate-400' : account.financialStatement === FinancialStatement.OFF_STATEMENT ? 'bg-slate-700' : 'bg-slate-800'} text-white p-4 flex flex-wrap items-center justify-between gap-4 transition-colors`}>
              <div className="flex items-center gap-4 group">
                {isEditing && editDraft ? (
                  <div className="flex flex-wrap items-center gap-3">
                    <div className="flex flex-col">
                      <label className="text-[9px] text-emerald-400 font-black uppercase">Account Name</label>
                      <input type="text" value={editDraft.name} onChange={(e) => updateDraft('name', e.target.value)} className="bg-slate-800 text-white px-3 py-1.5 rounded border border-slate-600 text-sm font-bold w-48" />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-[9px] text-emerald-400 font-black uppercase">Natural Balance</label>
                      <div className="flex bg-slate-800 border border-slate-600 rounded overflow-hidden mt-[2px]">
                        <button onClick={() => updateDraft('naturalBalance', NaturalBalance.DEBIT)} className={`px-3 py-1 text-[10px] font-bold ${editDraft.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-600 text-white' : 'text-slate-400 hover:text-white'}`}>DR</button>
                        <button onClick={() => updateDraft('naturalBalance', NaturalBalance.CREDIT)} className={`px-3 py-1 text-[10px] font-bold ${editDraft.naturalBalance === NaturalBalance.CREDIT ? 'bg-amber-600 text-white' : 'text-slate-400 hover:text-white'}`}>CR</button>
                      </div>
