  }, [categoryTotals]);

  const totalCogs = (categoryTotals['COGS'] || 0) + (categoryTotals['COGS reversal'] || 0);

  return (
    <div className="space-y-10">
      <div className="flex justify-between items-center border-b pb-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Amazon Analysis</h2>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Operational Audit Tool</p>
        </div>
        <div className="flex gap-4">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
            accept=".csv" 
            className="hidden" 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="bg-emerald-600 text-white px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-emerald-500 shadow-lg shadow-emerald-200 transition-all active:scale-95"
          >
            Upload Amazon CSV
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-slate-900 rounded-3xl p-6 text-white space-y-8">
            <h3 className="text-sm font-black uppercase tracking-widest text-slate-400 border-b border-slate-800 pb-3">Weighted Avg COGS</h3>
            <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2 no-scrollbar">
              {skusInFile.length === 0 ? (
                <p className="text-xs text-slate-500 italic">Upload a file to configure SKU costs.</p>
              ) : (
                skusInFile.map(sku => (
                  <div key={sku} className="space-y-1">
                    <label className="text-[9px] font-black uppercase text-slate-500 block truncate" title={sku}>{sku}</label>
                    <div className="relative">
                      <span className="absolute left-3 top-2 text-xs text-slate-400">$</span>
                      <input 
                        type="number" 
                        step="0.01"
                        value={skuCogs[sku] || ''}
                        onChange={(e) => onUpdateSkuCogs({ ...skuCogs, [sku]: parseFloat(e.target.value) || 0 })}
                        className="w-full bg-slate-800 border border-slate-700 rounded-lg pl-6 pr-3 py-1.5 text-xs font-mono focus:ring-1 focus:ring-emerald-500 outline-none"
                        placeholder="0.00"
                      />
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        <div className="lg:col-span-3 space-y-6">
          <div className="flex bg-slate-100 p-1 rounded-2xl w-fit">
            {(['Summary', 'BySKU', 'Raw'] as const).map(tab => (
              <button
                key={tab}
                onClick={() => setActiveReport(tab)}
                className={`px-8 py-2.5 rounded-xl text-xs font-black uppercase tracking-tighter transition-all ${
                  activeReport === tab ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
                }`}
              >
                {tab}
              </button>
            ))}
          </div>

          {records.length === 0 ? (
            <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl p-20 text-center">
              <p className="text-slate-400 font-bold italic">Upload a Settlement Report to begin analysis.</p>
            </div>
          ) : (
            <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm">
              {activeReport === 'Summary' && (
                <div className="p-10 space-y-12">
                  <div className="text-center">
                    <h3 className="text-2xl font-black uppercase text-slate-900">{companyName}</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mt-1">Amazon Contribution Schedule</p>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100">
                      <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-1">Gross Revenue</p>
                      <p className="text-2xl font-black font-mono text-emerald-900">${(categoryTotals['Revenue'] || 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
                    </div>
                    <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Net Amazon Income</p>
                      <p className="text-2xl font-black font-mono text-slate-900">${netAmazonIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
                    </div>
                    <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100">
                      <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">Inventory Value Sold (COGS)</p>
                      <p className="text-2xl font-black font-mono text-blue-900">${Math.abs(totalCogs).toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
                    </div>
                  </div>

                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b-2 border-slate-900">
                        <th className="text-left py-3 font-black text-[10px] uppercase tracking-widest text-slate-400">Analysis Classification</th>
                        <th className="text-right py-3 font-black text-[10px] uppercase tracking-widest text-slate-400">Processed Total</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {AMAZON_CATEGORIES.map(cat => {
                        const amt = categoryTotals[cat] || 0;
                        if (Math.abs(amt) < 0.01) return null;
                        return (
                          <tr key={cat} className="hover:bg-slate-50 transition-colors">
                            <td className="py-3 font-bold text-slate-700">{cat}</td>
                            <td className={`text-right font-mono font-bold ${amt < 0 ? 'text-red-500' : 'text-slate-900'}`}>
                              {amt.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                            </td>
                          </tr>
                        );
                      })}
                      <tr className="bg-slate-900 text-white font-black">
                        <td className="py-4 pl-4 uppercase tracking-widest text-xs">Total Impact on Cash</td>
                        <td className="text-right py-4 pr-4 font-mono">
                          {/* Explicitly cast Object.values to number[] to fix operator '+' error and toLocaleString argument error */}
                          ${(Object.values(categoryTotals) as number[]).reduce((a, b) => a + b, 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              )}

              {activeReport === 'BySKU' && (
                <div className="overflow-x-auto">
                  <table className="w-full text-xs text-left border-collapse">
                    <thead className="bg-slate-900 text-white">
                      <tr>
                        <th className="p-4 uppercase tracking-widest text-[9px] font-black">Product SKU</th>
                        <th className="p-4 uppercase tracking-widest text-[9px] font-black text-right">Qty Sold</th>
                        <th className="p-4 uppercase tracking-widest text-[9px] font-black text-right">Revenue</th>
                        <th className="p-4 uppercase tracking-widest text-[9px] font-black text-right">Avg Unit Cost</th>
                        <th className="p-4 uppercase tracking-widest text-[9px] font-black text-right">Total COGS</th>
                        <th className="p-4 uppercase tracking-widest text-[9px] font-black text-right">Gross Profit</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {skusInFile.map(sku => {
                        const skuRecs = records.filter(r => r.sku === sku);
                        const rev = skuRecs.filter(r => r.category === 'Revenue').reduce((s,r) => s+r.amount, 0);
                        const qty = skuRecs.filter(r => r.category === 'Revenue').reduce((s,r) => s+r.quantity, 0);
                        const cogs = (skuCogs[sku] || 0) * qty;
                        return (
                          <tr key={sku} className="hover:bg-slate-50 transition-colors">
                            <td className="p-4 font-black text-slate-800">{sku}</td>
                            <td className="p-4 text-right font-bold text-slate-600">{qty}</td>
                            <td className="p-4 text-right font-mono font-bold">${rev.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                            <td className="p-4 text-right font-mono text-slate-400">${(skuCogs[sku] || 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                            <td className="p-4 text-right font-mono text-blue-600">${cogs.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                            <td className="p-4 text-right font-mono font-black text-emerald-600">${(rev - cogs).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}

              {activeReport === 'Raw' && (
                <div className="overflow-x-auto max-h-[600px]">
                  <table className="w-full text-[10px] text-left border-collapse">
                    <thead className="bg-slate-100 sticky top-0 border-b">
                      <tr>
                        <th className="p-2 font-black uppercase text-slate-400">Date</th>
                        <th className="p-2 font-black uppercase text-slate-400">Category</th>
                        <th className="p-2 font-black uppercase text-slate-400">SKU</th>
                        <th className="p-2 font-black uppercase text-slate-400 text-right">Amount</th>
                        <th className="p-2 font-black uppercase text-slate-400">Type / Ref</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {records.map(r => (
                        <tr key={r.id} className="hover:bg-slate-50">
                          <td className="p-2 text-slate-500 whitespace-nowrap">{r.date.split(' ')[0]}</td>
                          <td className="p-2 font-bold text-slate-700">{r.category}</td>
                          <td className="p-2 text-slate-600 truncate max-w-[100px]">{r.sku || '-'}</td>
                          <td className={`p-2 text-right font-mono font-bold ${r.amount < 0 ? 'text-red-500' : 'text-emerald-700'}`}>
                            {r.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                          </td>
                          <td className="p-2 text-slate-400 truncate max-w-[150px]">{r.type} - {r.orderId || r.description}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="bg-amber-50 rounded-3xl border border-amber-200 p-6">
        <p className="text-[10px] font-black text-amber-700 uppercase tracking-widest flex items-center gap-2">
          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"></path></svg>
          Audit Rule: These schedules are for analytical purposes and do not modify your core accounting books.
        </p>
      </div>
    </div>
  );
};

export default AmazonAnalysis;

import React, { useState, useRef, useMemo } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuCogs } from '../types';

interface Props {
  skuCogs: SkuCogs;
  onUpdateSkuCogs: (newCogs: SkuCogs) => void;
  companyName: string;
}

const AMAZON_CATEGORIES: AmazonCategory[] = [
  'Revenue', 'Selling fees', 'FBA fees', 'FBA storage fees', 'AWD fees', 
  'FBA disposal fees', 'Advertising fees', 'Return fees', 'FBA reimbursement', 
  'FBM shipping fees', 'Inbound shipping fees', 'Account subscription', 
  'COGS', 'COGS reversal', 'Transfer', 'Other'
];

const AmazonAnalysis: React.FC<Props> = ({ skuCogs, onUpdateSkuCogs, companyName }) => {
  const [records, setRecords] = useState<AmazonAnalysisRecord[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const processed: AmazonAnalysisRecord[] = [];

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Could not find 'date/time' header. Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line, idx) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku');
      const orderId = getVal('order id');
      const description = getVal('description');
      const qty = parseInt(getVal('quantity')) || 0;

      const parseNum = (val: string) => parseFloat(val.replace(/,/g, '').replace(/\$/g, '')) || 0;

      const productSales = parseNum(getVal('product sales'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const other = parseNum(getVal('other'));
      const total = parseNum(getVal('total'));

      const baseInfo = { date: dateStr, sku, orderId, type, description, quantity: qty };
      const add = (cat: AmazonCategory, amt: number, q: number = 0) => {
        if (Math.abs(amt) > 0.001) {
          processed.push({ id: `${idx}-${cat}-${Math.random()}`, ...baseInfo, category: cat, amount: amt, quantity: q });
        }
      };

      if (type === 'Order') {
        add('Revenue', productSales);
        add('Selling fees', sellingFees);
        add('FBA fees', fbaFees);
        add('FBA fees', otherTrans);
        const unitCost = skuCogs[sku] || 0;
        if (unitCost > 0) add('COGS', unitCost * qty, qty);
      } 
      else if (type === 'Refund') {
        add('Revenue', productSales);
        add('Selling fees', sellingFees);
        add('FBA fees', fbaFees);
        add('Return fees', otherTrans);
        const unitCost = skuCogs[sku] || 0;
        if (unitCost > 0) add('COGS reversal', -(unitCost * Math.abs(qty)), qty);
      }
      else if (type === 'Adjustment') {
        if (description.toLowerCase().includes('reimbursement')) add('FBA reimbursement', total);
        else add('Other', total);
      }
      else if (type === 'Service Fee') {
        if (description.toLowerCase().includes('subscription')) add('Account subscription', total);
        else if (description.toLowerCase().includes('advertising')) add('Advertising fees', total);
        else add('Other', total);
      }
      else if (type === 'FBA Transaction fees') {
        if (description.toLowerCase().includes('storage')) add('FBA storage fees', total);
        else if (description.toLowerCase().includes('awd')) add('AWD fees', total);
        else if (description.toLowerCase().includes('disposal')) add('FBA disposal fees', total);
        else add('FBA fees', total);
      }
      else if (type === 'Transfer') add('Transfer', total);
      else if (type === 'Shipping Services') add('FBM shipping fees', total);
      else add('Other', total);
    });

    setRecords(processed);
  };

  // PIVOT LOGIC: Period Generation
  const periods = useMemo(() => {
    const pSet = new Set<string>();
    records.forEach(r => {
      const d = new Date(r.date);
      if (!isNaN(d.getTime())) {
        const key = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;
        pSet.add(key);
      }
    });
    return Array.from(pSet); // Amazon usually exports sequential data
  }, [records]);

  const getMonthTotal = (category: AmazonCategory, period: string, sku?: string, typeFilter?: string) => {
    return records.filter(r => {
      const d = new Date(r.date);
      const key = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;
      const matchesPeriod = key === period;
      const matchesCat = r.category === category;
      const matchesSku = sku ? r.sku === sku : true;
      const matchesType = typeFilter ? r.type === typeFilter : true;
      return matchesPeriod && matchesCat && matchesSku && matchesType;
    }).reduce((sum, r) => sum + r.amount, 0);
  };

  const sortedSkus = useMemo(() => {
    const totals: Record<string, number> = {};
    records.forEach(r => { if (r.sku && r.category === 'Revenue') totals[r.sku] = (totals[r.sku] || 0) + r.amount; });
    return Object.entries(totals).sort((a, b) => b[1] - a[1]);
  }, [records]);

  const top15Skus = sortedSkus.slice(0, 15);
  const otherSkus = sortedSkus.slice(15);

  return (
    <div className="space-y-12">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mt-2">Amazon Operational Performance & Recon</p>
        </div>
        <div className="flex gap-4">
          <input type="file" ref={fileInputRef} onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-800 shadow-xl transition-all active:scale-95">
            Upload Settlement
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1">
          <div className="bg-slate-50 border rounded-3xl p-6 sticky top-24">
            <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-6">SKU Unit Costs (W.A. COGS)</h3>
            <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2 no-scrollbar">
              {Array.from(new Set(records.map(r => r.sku))).filter(Boolean).sort().map(sku => (
                <div key={sku}>
                  <label className="text-[9px] font-bold text-slate-500 block truncate" title={sku}>{sku}</label>
                  <div className="relative mt-1">
                    <span className="absolute left-3 top-2 text-[10px] text-slate-400">$</span>
                    <input 
                      type="number" step="0.01" value={skuCogs[sku] || ''} 
                      onChange={(e) => onUpdateSkuCogs({ ...skuCogs, [sku]: parseFloat(e.target.value) || 0 })}
                      className="w-full bg-white border border-slate-200 rounded-xl pl-6 pr-3 py-2 text-xs font-mono font-bold focus:ring-2 focus:ring-slate-900 outline-none"
                    />
                  </div>
                </div>
              ))}
              {records.length === 0 && <p className="text-xs text-slate-400 italic">No data detected</p>}
            </div>
          </div>
        </div>

        <div className="lg:col-span-3 space-y-16">
          {records.length === 0 ? (
            <div className="bg-slate-100 rounded-3xl p-20 text-center border-2 border-dashed border-slate-200">
              <span className="text-4xl mb-4 block">📊</span>
              <p className="text-slate-400 font-bold italic">Upload your monthly settlement CSV to generate reporting schedules.</p>
            </div>
          ) : (
            <>
              {/* SCHEDULE: REVENUE BY PRODUCT */}
              <section className="space-y-6">
                <h4 className="text-xs font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by Product</h4>
                <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm">
                  <table className="w-full text-[11px] text-left border-collapse bg-white">
                    <thead>
                      <tr className="bg-slate-50 border-b">
                        <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description (SKU)</th>
                        {periods.map(p => <th key={p} className="p-4 font-black uppercase text-slate-900 text-right">{p}</th>)}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {top15Skus.map(([sku]) => (
                        <tr key={sku} className="hover:bg-slate-50 transition-colors">
                          <td className="p-4 font-medium text-slate-600 truncate max-w-xs">{sku}</td>
                          {periods.map(p => (
                            <td key={p} className="p-4 text-right font-mono text-slate-900">
                              {getMonthTotal('Revenue', p, sku).toLocaleString(undefined, { minimumFractionDigits: 0 })}
                            </td>
                          ))}
                        </tr>
                      ))}
                      {otherSkus.length > 0 && (
                        <tr className="bg-slate-50 italic">
                          <td className="p-4 text-slate-400">Others ({otherSkus.length})</td>
                          {periods.map(p => {
                            const sum = otherSkus.reduce((s, [sku]) => s + getMonthTotal('Revenue', p, sku), 0);
                            return <td key={p} className="p-4 text-right font-mono text-slate-400">{sum.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                          })}
                        </tr>
                      )}
                      <tr className="bg-slate-900 text-white font-black">
                        <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                        {periods.map(p => (
                          <td key={p} className="p-4 text-right font-mono">
                            ${getMonthTotal('Revenue', p).toLocaleString(undefined, { minimumFractionDigits: 0 })}
                          </td>
                        ))}
                      </tr>
                    </tbody>
                  </table>
                </div>
              </section>

              {/* SCHEDULE: GROSS TO NET REVENUE RECON */}
              <section className="space-y-6">
                <h4 className="text-xs font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to Net Revenue Recon</h4>
                <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm">
                  <table className="w-full text-xs text-left border-collapse bg-white">
                    <thead>
                      <tr className="bg-slate-50 border-b">
                        <th className="p-4 font-black uppercase text-slate-400">$</th>
                        {periods.map(p => <th key={p} className="p-4 font-black uppercase text-slate-900 text-right">{p}</th>)}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      <tr>
                        <td className="p-4 font-bold text-slate-700">Revenue (Gross Orders)</td>
                        {periods.map(p => <td key={p} className="p-4 text-right font-mono">{getMonthTotal('Revenue', p, undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                      </tr>
                      <tr>
                        <td className="p-4 font-bold text-slate-700">Refunds</td>
                        {periods.map(p => <td key={p} className="p-4 text-right font-mono text-red-500">({Math.abs(getMonthTotal('Revenue', p, undefined, 'Refund')).toLocaleString(undefined, { minimumFractionDigits: 0 })})</td>)}
                      </tr>
                      <tr className="bg-slate-900 text-emerald-400 font-black border-t-2 border-slate-950">
                        <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, Net</td>
                        {periods.map(p => <td key={p} className="p-4 text-right font-mono">${getMonthTotal('Revenue', p).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                      </tr>
                    </tbody>
                  </table>
                </div>
              </section>

              {/* SCHEDULE: AMAZON FEES */}
              <section className="space-y-6">
