                           const netCogs = getMonthTotal('COGS', p) + getMonthTotal('COGS reversal', p);
                           return <td key={p} className="p-4 text-right font-mono font-black text-slate-900">${(cashImpact - Math.abs(netCogs)).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
