                      <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                        <td className="p-4 uppercase tracking-widest text-[10px]">Total Amazon Fees</td>
                        {periods.map(p => {
                          const feeSum = ['Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees', 'FBA storage fees', 'AWD fees', 'Inbound shipping fees', 'Account subscription', 'Return fees', 'FBA disposal fees', 'Other'].reduce((s,f)=> s + getMonthTotal(f as AmazonCategory, p), 0);
                          return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
