                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className={`p-4 text-right font-mono text-slate-900 ${clearingPeriods.has(p) ? 'opacity-30' : ''}`}>
