const safeStringify = (obj: any) => {
  const cache = new WeakSet();
  return JSON.stringify(obj, (key, value) => {
    if (typeof value === 'object' && value !== null) {
      if (cache.has(value)) return;
      cache.add(value);
    }
    return value;
  });
};

// --- STANDARDIZED KEY LOGIC (SOURCE OF TRUTH) ---
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force US English to ensure "Oct" matches "Oct" across all environments
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([{ name: 'JE', accountId: '' }]);
  const [companyName, setCompanyName] = useState('Vista Shore Products, LLC');
  const [amazonRecords, setAmazonRecords] = useState<AmazonAnalysisRecord[]>([]);
  const [skuData, setSkuData] = useState<SkuDataMap>({});
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  const isUpdatingRef = useRef(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    // Load initial local data
    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
        if (parsed.paymentMethods) setPaymentMethods(parsed.paymentMethods);
        if (parsed.companyName) setCompanyName(parsed.companyName);
        if (parsed.amazonRecords) setAmazonRecords(parsed.amazonRecords);
        if (parsed.skuData) setSkuData(parsed.skuData);
      } catch (e) {}
    }

    const userDocRef = doc(db, 'users', user.uid);
    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      // MASTER LOCK: Ignore cloud updates if we are in the middle of a local write
      if (isUpdatingRef.current) {
        console.debug("Snapshot Filter: Sync lock active, ignoring cloud update.");
        return;
      }

      // KILL-SWITCH: Ignore snapshots that contain our own pending writes (local echos)
      if (docSnap.metadata.hasPendingWrites) {
        console.debug("Snapshot Filter: Ignoring local write echo.");
        return;
      }

      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        if (data.paymentMethods) setPaymentMethods(data.paymentMethods);
        if (data.companyName) setCompanyName(data.companyName);
        if (data.amazonRecords) setAmazonRecords(data.amazonRecords);
        if (data.skuData) setSkuData(data.skuData);

        localStorage.setItem(`vista_data_${user.uid}`, safeStringify(data));
      }
    }, (error) => {
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = useCallback(async (
    newAccs: Account[], 
    newTxs: JournalEntry[], 
    newPeriods: string[], 
    newMethods: PaymentMethod[], 
    newName: string,
    newAmazon: AmazonAnalysisRecord[],
    newSku: SkuDataMap,
    lockTime: number = 1500 
  ) => {
    if (!user) return;

    isUpdatingRef.current = true;
    setIsSyncing(true);

    const packet = {
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods,
      paymentMethods: newMethods,
      companyName: newName,
      amazonRecords: newAmazon,
      skuData: newSku
    };

    localStorage.setItem(`vista_data_${user.uid}`, safeStringify(packet));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        ...packet,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Save error:", err);
      setCloudError("Failed to save to cloud.");
    } finally {
      setTimeout(() => { 
        isUpdatingRef.current = false; 
        setIsSyncing(false);
      }, lockTime);
    }
  }, [user]);

  // --- REWRITTEN NUCLEAR REMOVE FUNCTION ---
  const removeAmazonPeriod = async (periodKey: string) => {
    if (!user) return;

    console.log("Initiating Force Delete for:", periodKey);

    // 1. LOCK THE SYNC
    isUpdatingRef.current = true;
    setIsSyncing(true);

    try {
      let finalFiltered: AmazonAnalysisRecord[] = [];

      // 2. FUNCTIONAL STATE UPDATE (Truth from Memory)
      setAmazonRecords(prev => {
        // Fix for Error: Cannot find name 'idx'. Adding index parameter to filter callback.
        const updated = prev.filter((r, idx) => {
          const recordKey = getStandardKey(r.date);
          // TRUTH LOGS: Debug comparison
          if (idx < 5) console.debug("Comparing:", recordKey, "against target:", periodKey);
          return recordKey !== periodKey;
        });

        finalFiltered = updated; 

        console.log(`Filter Report | Target: ${periodKey} | Before: ${prev.length} | After: ${updated.length} | Deleted: ${prev.length - updated.length}`);

        // 3. FORCE LOCAL STORAGE SYNC
        const currentLocal = localStorage.getItem(`vista_data_${user.uid}`);
        let packet = currentLocal ? JSON.parse(currentLocal) : {};
        packet.amazonRecords = updated;
        localStorage.setItem(`vista_data_${user.uid}`, safeStringify(packet));

        return updated;
      });

      // 4. PUSH TO FIRESTORE
      const userDocRef = doc(db, 'users', user.uid);
      await setDoc(userDocRef, { 
        amazonRecords: finalFiltered,
        lastUpdated: new Date().toISOString() 
      }, { merge: true });

      console.log("Cloud update confirmed for force delete of:", periodKey);

    } catch (err) {
      console.error("Critical Failure in removeAmazonPeriod:", err);
      alert("Error deleting data. Check console.");
    } finally {
      // 5. HOLD THE LOCK (Prevent Snapshot Ghosting)
      console.log("Holding sync lock for 3 seconds...");
      setTimeout(() => {
        isUpdatingRef.current = false;
        setIsSyncing(false);
        console.log("Sync lock released.");
      }, 3000);
    }
  };

  const updateAmazonRecords = useCallback((recs: AmazonAnalysisRecord[]) => {
    setAmazonRecords(recs);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, recs, skuData);
  }, [accounts, transactions, closedPeriods, paymentMethods, companyName, skuData, saveToFirestore]);

  const updateCompanyName = (name: string) => {
    setCompanyName(name);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, name, amazonRecords, skuData);
  };

  const updateSkuData = (data: SkuDataMap) => {
    setSkuData(data);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, data);
  };

  const resetSystem = (full: boolean) => {
    const defaultMethods = [{ name: 'JE', accountId: '' }];
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      setPaymentMethods(defaultMethods);
      setCompanyName('Vista Shore Products, LLC');
      setAmazonRecords([]);
      setSkuData({});
      saveToFirestore(INITIAL_ACCOUNTS, [], [], defaultMethods, 'Vista Shore Products, LLC', [], {}, 3000);
    } else {
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], [], paymentMethods, companyName, amazonRecords, skuData, 2000);
    }
    setActiveTab('Dashboard');
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const addPaymentMethod = (method: string, accountId: string) => {
    const updated = [...paymentMethods, { name: method, accountId }];
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const removePaymentMethod = (methodName: string) => {
    const updated = paymentMethods.filter(m => m.name !== methodName);
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const updatedAccs = [...accounts, ...newAccounts];
    const updatedTxs = [...transactions, ...newTransactions];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Amazon Analysis', 'COGS Manager', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}
      {isSyncing && (
        <div className="fixed bottom-6 right-6 z-[999] bg-slate-900 text-white px-5 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4">
          <div className="w-2 h-2 rounded-full animate-ping bg-emerald-500"></div>
          <span className="text-[10px] font-black uppercase tracking-widest">Processing Data Update...</span>
        </div>
      )}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-50 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <div className="flex flex-col">
            <h1 className="text-xl font-bold tracking-tighter text-white">VISTA SHORE</h1>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors text-white">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} paymentMethods={paymentMethods} companyName={companyName} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} paymentMethods={paymentMethods} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Amazon Analysis' && <AmazonAnalysis skuData={skuData} records={amazonRecords} onUpdateRecords={updateAmazonRecords} onRemovePeriod={removeAmazonPeriod} companyName={companyName} isSyncing={isSyncing} />}
            {activeTab === 'COGS Manager' && <CogsManager skuData={skuData} onUpdateSkuData={updateSkuData} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={importData} onReset={resetSystem} paymentMethods={paymentMethods} onAddMethod={addPaymentMethod} onRemoveMethod={removePaymentMethod} companyName={companyName} onUpdateCompanyName={updateCompanyName} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force 'en-US' locale for consistent keys across browsers
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {

  const handleClearPeriod = (p: string) => {
    console.log("UI: Requesting removal of month key:", p);
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description');
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => parseFloat(val.replace(/,/g, '').replace(/\$/g, '')) || 0;

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;

        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);

        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      if (type === 'Order') {
        addToSummary('Revenue', productSales);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (description.toLowerCase().includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (type === 'Refund') {
        addToSummary('Revenue', productSales);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (type === 'Adjustment') {
        if (description.toLowerCase().includes('reimbursement')) addToSummary('FBA reimbursement', total);
        else addToSummary('Other', total);
      }
      else if (type === 'Service Fee') {
        if (description.toLowerCase().includes('subscription')) addToSummary('Account subscription', total);
        else if (description.toLowerCase().includes('advertising')) addToSummary('Advertising fees', total);
        else addToSummary('Other', total);
      }
      else if (type === 'FBA Transaction fees') {
        if (description.toLowerCase().includes('storage')) addToSummary('FBA storage fees', total);
        else if (description.toLowerCase().includes('awd')) addToSummary('AWD fees', total);
        else if (description.toLowerCase().includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (description.toLowerCase().includes('inbound') || description.toLowerCase().includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (type === 'Transfer') addToSummary('Transfer', total);
      else if (type === 'Shipping Services') addToSummary('FBM shipping fees', total);
      else addToSummary('Other', total);
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const qtyMap: any = {};

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;

      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!qtyMap[pk]) qtyMap[pk] = {};
      if (!qtyMap[pk][r.sku]) qtyMap[pk][r.sku] = {};
      if (!qtyMap[pk][r.sku][r.type]) qtyMap[pk][r.sku][r.type] = 0;
      qtyMap[pk][r.sku][r.type] += r.quantity;
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const parse = (s: string) => {
        const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
        const m = s.slice(0, 3);
        const y = parseInt(s.slice(3));
        return new Date(2000 + y, months[m]).getTime();
      };
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, qtyMap };
  }, [records]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;

    // Case 1: Grand total for category (Neither SKU nor Type specified)
    if (!sku && !type) return p[cat]._total;

    // Case 2: Total for that Type across all SKUs (Type specified, no SKU)
    if (!sku && type) {
      let sum = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) sum += p[cat][sKey][type];
      });
      return sum;
    }

    // Case 3: Total for specific SKU (SKU specified, no Type)
    if (sku && !type) {
      if (!p[cat][sku]) return 0;
      return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    }

    // Case 4: Both specified
    return p[cat][sku]?.[type] || 0;
  };

  const getQty = (period: string, sku: string, type: string) => {
    return pivotData.qtyMap[period]?.[sku]?.[type] || 0;
  };

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => {
                      return (
                        <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                          <div className="flex flex-col items-end">
                            <span className="mb-1">{p}</span>
                            <button 
                              disabled={isSyncing}
                              onClick={() => handleClearPeriod(p)}
                              className="text-[8px] font-black uppercase tracking-widest transition-opacity text-red-500 opacity-0 group-hover/th:opacity-100 hover:underline cursor-pointer disabled:opacity-30"
                            >
                              Clear Month
                            </button>
                          </div>
                        </th>
                      );
                    })}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {pivotData.skus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue (Gross Orders)</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {FEE_LIST.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isCredit = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isCredit && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>{val !== 0 ? Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-slate-900 pl-3">Net Amazon Settlement & Inventory Drain</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white border-b">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Consolidated Impact Item</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black uppercase text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-800">Net Amazon Calculated (Revenue - Fees)</td>
                    {pivotData.periods.map(p => {
                       const netRev = getAmt(p, 'Revenue');
                       const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                       const calc = netRev + feeSum;
                       return <td key={p} className="p-4 text-right font-mono font-bold text-slate-900">${calc.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-800 italic">Net Amazon Transfer (Actual)</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       return <td key={p} className="p-4 text-right font-mono font-black text-emerald-600">${transfer.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-red-50 text-red-800">
                    <td className="p-4 font-black uppercase text-[10px]">Difference / Reconciling Factor</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       const netRev = getAmt(p, 'Revenue');
                       const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                       const diff = transfer - (netRev + feeSum);
                       return <td key={p} className={`p-4 text-right font-mono font-black ${Math.abs(diff) > 1 ? 'text-red-600' : 'text-slate-400'}`}>${diff.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">Total COGS (Inventory Drain)</td>
                    {pivotData.periods.map(p => {
                      const cogs = pivotData.skus.reduce((s, sku) => s + (getQty(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-700">${cogs.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">COGS Reversal (Returned Value)</td>
                    {pivotData.periods.map(p => {
                      const rev = pivotData.skus.reduce((s, sku) => s + (Math.abs(getQty(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-400">${rev.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-50 border-t-2 border-slate-200">
                    <td className="p-4 font-black text-slate-900">Final Amazon Net Margin Contribution</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       const cogs = pivotData.skus.reduce((s, sku) => s + (getQty(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                       const rev = pivotData.skus.reduce((s, sku) => s + (Math.abs(getQty(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                       return <td key={p} className="p-4 text-right font-mono font-black text-slate-900">${(transfer - cogs + rev).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useMemo } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force 'en-US' locale for consistent keys across browsers
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {

  const handleClearPeriod = (p: string) => {
    console.log("UI: Requesting removal of month key:", p);
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description');
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => parseFloat(val.replace(/,/g, '').replace(/\$/g, '')) || 0;

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;

        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);

        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      if (type === 'Order') {
        addToSummary('Revenue', productSales);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (description.toLowerCase().includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (type === 'Refund') {
        addToSummary('Revenue', productSales);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (type === 'Adjustment') {
        if (description.toLowerCase().includes('reimbursement')) addToSummary('FBA reimbursement', total);
        else addToSummary('Other', total);
      }
      else if (type === 'Service Fee') {
        if (description.toLowerCase().includes('subscription')) addToSummary('Account subscription', total);
        else if (description.toLowerCase().includes('advertising')) addToSummary('Advertising fees', total);
        else addToSummary('Other', total);
      }
      else if (type === 'FBA Transaction fees') {
        if (description.toLowerCase().includes('storage')) addToSummary('FBA storage fees', total);
        else if (description.toLowerCase().includes('awd')) addToSummary('AWD fees', total);
        else if (description.toLowerCase().includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (description.toLowerCase().includes('inbound') || description.toLowerCase().includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (type === 'Transfer') addToSummary('Transfer', total);
      else if (type === 'Shipping Services') addToSummary('FBM shipping fees', total);
      else addToSummary('Other', total);
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const qtyMap: any = {};

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;

      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!qtyMap[pk]) qtyMap[pk] = {};
      if (!qtyMap[pk][r.sku]) qtyMap[pk][r.sku] = {};
      if (!qtyMap[pk][r.sku][r.type]) qtyMap[pk][r.sku][r.type] = 0;
      qtyMap[pk][r.sku][r.type] += r.quantity;
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const parse = (s: string) => {
        const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
        const m = s.slice(0, 3);
        const y = parseInt(s.slice(3));
        return new Date(2000 + y, months[m]).getTime();
      };
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, qtyMap };
  }, [records]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;

    // Fixed logic to handle Type filtering without an explicit SKU
    if (!sku) {
      if (!type) return p[cat]._total;

      // Calculate total for specific type across all SKUs in this category
      let typeTotal = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) typeTotal += p[cat][sKey][type];
      });
      return typeTotal;
    }

    if (!p[cat][sku]) return 0;
    if (!type) {
      return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    }
    return p[cat][sku][type] || 0;
  };

  const getQty = (period: string, sku: string, type: string) => {
    return pivotData.qtyMap[period]?.[sku]?.[type] || 0;
  };

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => {
                      return (
                        <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                          <div className="flex flex-col items-end">
                            <span className="mb-1">{p}</span>
                            <button 
                              disabled={isSyncing}
                              onClick={() => handleClearPeriod(p)}
                              className="text-[8px] font-black uppercase tracking-widest transition-opacity text-red-500 opacity-0 group-hover/th:opacity-100 hover:underline cursor-pointer disabled:opacity-30"
                            >
                              Clear Month
                            </button>
                          </div>
                        </th>
                      );
                    })}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {pivotData.skus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue (Gross Orders)</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {FEE_LIST.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isCredit = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isCredit && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>{val !== 0 ? Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-slate-900 pl-3">Net Amazon Settlement & Inventory Drain</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white border-b">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Consolidated Impact Item</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black uppercase text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-800">Net Amazon Calculated (Revenue - Fees)</td>
                    {pivotData.periods.map(p => {
                       const netRev = getAmt(p, 'Revenue');
                       const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                       const calc = netRev + feeSum;
                       return <td key={p} className="p-4 text-right font-mono font-bold text-slate-900">${calc.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-800 italic">Net Amazon Transfer (Actual)</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       return <td key={p} className="p-4 text-right font-mono font-black text-emerald-600">${transfer.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-red-50 text-red-800">
                    <td className="p-4 font-black uppercase text-[10px]">Difference / Reconciling Factor</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       const netRev = getAmt(p, 'Revenue');
                       const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                       const diff = transfer - (netRev + feeSum);
                       return <td key={p} className={`p-4 text-right font-mono font-black ${Math.abs(diff) > 1 ? 'text-red-600' : 'text-slate-400'}`}>${diff.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">Total COGS (Inventory Drain)</td>
                    {pivotData.periods.map(p => {
                      const cogs = pivotData.skus.reduce((s, sku) => s + (getQty(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-700">${cogs.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">COGS Reversal (Returned Value)</td>
                    {pivotData.periods.map(p => {
                      const rev = pivotData.skus.reduce((s, sku) => s + (Math.abs(getQty(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-400">${rev.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-50 border-t-2 border-slate-200">
                    <td className="p-4 font-black text-slate-900">Final Amazon Net Margin Contribution</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       const cogs = pivotData.skus.reduce((s, sku) => s + (getQty(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                       const rev = pivotData.skus.reduce((s, sku) => s + (Math.abs(getQty(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                       return <td key={p} className="p-4 text-right font-mono font-black text-slate-900">${(transfer - cogs + rev).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>
        </div>
      )}
    </div>
  );
};

