              {sortedPeriods.map(p => <td key={p} className="p-4 text-right font-mono text-base border-r border-slate-700 shadow-inner">${periodData[p].endCash.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>)}
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
