                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue (Gross Orders)</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {FEE_LIST.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isCredit = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isCredit && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>{val !== 0 ? Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-indigo-600 pl-3">Profitability & Margin Analysis</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Performance Metric</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 text-right font-black uppercase text-[10px] tracking-widest">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Revenue (Net)</td>
                    {pivotData.periods.map(p => (
                      <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">
                        ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-500">
                          (${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 2 })})
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-50">
                    <td className="p-4 font-black text-slate-900 italic">Net Amazon Transfer (Cash Out)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-emerald-700">
                          ${transfer.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">Est. Cost of Goods (Orders)</td>
                    {pivotData.periods.map(p => {
                      const val = pivotData.cogsMap[p]?.orderCogs || 0;
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-600">
                          {val !== 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : '-'}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">COGS Reversal (Returns)</td>
                    {pivotData.periods.map(p => {
                      const val = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-emerald-600">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-white font-black border-t-2 border-slate-700">
                    <td className="p-4 text-xs uppercase tracking-[0.2em]">Gross Profit (Cash Basis)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs + returnCogs;
                      return (
                        <td key={p} className={`p-4 text-right font-mono text-base ${profit < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                          ${profit.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-indigo-50 border-t-2 border-indigo-100">
                    <td className="p-4 font-black text-indigo-900 uppercase tracking-widest text-[10px]">Gross Margin %</td>
                    {pivotData.periods.map(p => {
                      const revenue = getAmt(p, 'Revenue');
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs + returnCogs;
                      const margin = revenue !== 0 ? (profit / revenue) * 100 : 0;
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-indigo-800 text-base">
                          {margin.toFixed(1)}%
                        </td>
                      );
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] font-bold text-slate-400 italic px-4">
              Note: Gross Profit (Cash Basis) = Amazon Transfer - Order COGS + Returned Inventory Value. 
              This represents the actual cash profit generated after accounting for product drain.
            </p>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useRef, useState } from 'react';
import { SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  onUpdateSkuData: (data: SkuDataMap) => void;
}

interface CogsScheduleItem {
  period: string;
  orderCogs: number;
  refundCogs: number;
}

// SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const CogsManager: React.FC<Props> = ({ skuData, onUpdateSkuData }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const transInputRef = useRef<HTMLInputElement>(null);
  const [cogsSchedule, setCogsSchedule] = useState<CogsScheduleItem[]>([]);

  const downloadTemplate = () => {
    const csv = "sku,item_name,unit_cogs\nSKU-123,Product Example,5.50\n";
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = "cogs_template.csv";
    a.click();
  };

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const csv = ev.target?.result as string;
      const lines = csv.split('\n');
      const newData: SkuDataMap = { ...skuData };

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const [sku, name, cost] = line.split(',').map(v => v.replace(/"/g, '').trim());
        if (sku) {
          const parsedCost = parseFloat(cost) || 0;
          newData[sku] = { name: name || sku, cost: Math.round(parsedCost * 100) / 100 };
        }
      }
      onUpdateSkuData(newData);
      if (fileInputRef.current) fileInputRef.current.value = '';
      alert("SKU data updated successfully!");
    };
    reader.readAsText(file);
  };

  const processTransactionReport = (csv: string) => {
    const lines = csv.split('\n');
    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      const l = lines[i].toLowerCase();
      if (l.includes('date/time') && l.includes('type') && l.includes('sku')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Could not find headers. Ensure this is an Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);
    const scheduleMap = new Map<string, { orderCogs: number, refundCogs: number }>();
    const warnedSkus = new Set<string>();

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku');
      const qty = parseInt(getVal('quantity')) || 0;

      const period = getStandardKey(dateStr);
      if (period === "INVALID" || !sku) return;

      if (!scheduleMap.has(period)) {
        scheduleMap.set(period, { orderCogs: 0, refundCogs: 0 });
      }

      const totals = scheduleMap.get(period)!;
      const unitCost = skuData[sku]?.cost || 0;

      if (unitCost === 0 && (type === 'Order' || type === 'Refund')) {
        if (!warnedSkus.has(sku)) {
          console.warn(`[COGS Calc] Missing cost for SKU: ${sku}`);
          warnedSkus.add(sku);
        }
      }

      if (type === 'Order') {
        totals.orderCogs += (qty * unitCost);
      } else if (type === 'Refund') {
        // Refund quantities are negative (e.g. -1). Treat as positive "reversal".
        totals.refundCogs += (Math.abs(qty) * unitCost);
      }
    });

    const sorted = Array.from(scheduleMap.entries()).map(([period, data]) => ({
      period,
      ...data
    })).sort((a, b) => {
      const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
      const m1 = a.period.slice(0, 3);
      const y1 = parseInt(a.period.slice(3));
      const m2 = b.period.slice(0, 3);
      const y2 = parseInt(b.period.slice(3));
      return (y1 * 100 + months[m1]) - (y2 * 100 + months[m2]);
    });

    setCogsSchedule(sorted);
    if (transInputRef.current) transInputRef.current.value = '';
  };

  const sortedSkus = Object.keys(skuData).sort();

  return (
    <div className="space-y-12">
      {/* SECTION 1: Weighted Average Costs */}
      <section className="space-y-8">
        <div className="flex justify-between items-end border-b pb-6">
          <div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tight">COGS Manager</h2>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Weighted Average Product Costs</p>
          </div>
          <div className="flex gap-3">
            <button onClick={downloadTemplate} className="bg-slate-100 text-slate-600 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-200 transition-all border border-slate-200">
              Get Template
            </button>
            <input type="file" ref={fileInputRef} onChange={handleUpload} accept=".csv" className="hidden" />
            <button onClick={() => fileInputRef.current?.click()} className="bg-slate-900 text-white px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-slate-800 shadow-lg shadow-slate-200 transition-all active:scale-95">
              Upload SKU Costs
            </button>
          </div>
        </div>

        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-sm border-collapse">
            <thead className="bg-slate-50 border-b">
              <tr>
                <th className="p-4 text-left font-black uppercase text-[10px] text-slate-400 w-1/4">SKU Code</th>
                <th className="p-4 text-left font-black uppercase text-[10px] text-slate-400">Item Name</th>
                <th className="p-4 text-right font-black uppercase text-[10px] text-slate-400 w-32">Unit Cost</th>
                <th className="p-4 w-16"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {sortedSkus.length === 0 && (
                <tr>
                  <td colSpan={4} className="p-12 text-center text-slate-400 italic">No SKU data configured. Upload a CSV to get started.</td>
                </tr>
              )}
              {sortedSkus.map(sku => (
                <tr key={sku} className="group hover:bg-slate-50 transition-colors">
                  <td className="p-4 font-mono font-bold text-slate-900">{sku}</td>
                  <td className="p-4">
                    <input 
                      type="text" value={skuData[sku].name} 
                      onChange={(e) => onUpdateSkuData({ ...skuData, [sku]: { ...skuData[sku], name: e.target.value } })}
                      className="w-full bg-transparent border-b border-transparent group-hover:border-slate-200 focus:border-emerald-500 focus:ring-0 outline-none font-medium"
                    />
                  </td>
                  <td className="p-4 text-right">
                    <div className="relative inline-block">
                      <span className="absolute left-2 top-2 text-xs text-slate-400">$</span>
                      <input 
                        type="number" 
                        step="0.01"
                        value={skuData[sku].cost ?? ''} 
                        onChange={(e) => {
                          const val = e.target.value === '' ? 0 : parseFloat(e.target.value);
                          onUpdateSkuData({ ...skuData, [sku]: { ...skuData[sku], cost: isNaN(val) ? 0 : val } });
                        }}
                        onBlur={(e) => {
                          const val = parseFloat(e.target.value) || 0;
                          const rounded = Math.round(val * 100) / 100;
                          onUpdateSkuData({ ...skuData, [sku]: { ...skuData[sku], cost: rounded } });
                        }}
                        className="w-24 bg-transparent border-b border-transparent group-hover:border-slate-200 focus:border-emerald-500 focus:ring-0 outline-none text-right font-mono font-bold appearance-none"
                      />
                    </div>
                  </td>
                  <td className="p-4 text-right">
                    <button 
                      onClick={() => {
                        const next = { ...skuData };
                        delete next[sku];
                        onUpdateSkuData(next);
                      }}
                      className="text-red-300 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-all font-bold"
                    >✕</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      <div className="h-[2px] bg-slate-100 mx-4"></div>

      {/* SECTION 2: Monthly COGS Schedule */}
      <section className="space-y-8">
        <div className="flex justify-between items-end">
          <div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tight">Monthly COGS Schedule</h2>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Calculated Inventory Drain by Month</p>
          </div>
          <div>
            <input type="file" ref={transInputRef} onChange={(e) => {
              const file = e.target.files?.[0];
              if (!file) return;
              const reader = new FileReader();
              reader.onload = (ev) => processTransactionReport(ev.target?.result as string);
              reader.readAsText(file);
            }} accept=".csv" className="hidden" />
            <button onClick={() => transInputRef.current?.click()} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-500 shadow-xl shadow-emerald-100 transition-all active:scale-95">
              Upload Amazon Transactions for COGS Calc
            </button>
          </div>
        </div>

        {cogsSchedule.length === 0 ? (
          <div className="bg-slate-50 rounded-3xl p-16 text-center border-2 border-dashed border-slate-200">
            <span className="text-4xl mb-4 block opacity-30">📊</span>
            <p className="text-slate-400 font-bold italic">Upload an Amazon Settlement report to view the monthly COGS breakdown.</p>
          </div>
        ) : (
          <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
            <table className="w-full text-sm border-collapse">
              <thead className="bg-slate-900 text-white">
                <tr>
                  <th className="p-4 text-left font-black uppercase tracking-widest text-[10px]">Period</th>
                  <th className="p-4 text-right font-black uppercase tracking-widest text-[10px]">COGS (Orders)</th>
                  <th className="p-4 text-right font-black uppercase tracking-widest text-[10px]">COGS Reversal (Returns)</th>
                  <th className="p-4 text-right font-black uppercase tracking-widest text-[10px]">Net Inventory COGS</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {cogsSchedule.map(row => {
                  const netCogs = row.orderCogs - row.refundCogs;
                  return (
                    <tr key={row.period} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-black text-slate-900 uppercase tracking-tighter">{row.period}</td>
                      <td className="p-4 text-right font-mono text-slate-600">
                        ${row.orderCogs.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                      <td className="p-4 text-right font-mono text-emerald-600">
                        ${row.refundCogs.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                      <td className="p-4 text-right font-mono font-black text-slate-900 bg-slate-50/50">
                        ${netCogs.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot className="bg-slate-100 border-t-2 border-slate-200">
                <tr className="font-black text-slate-900">
                  <td className="p-4 uppercase tracking-widest text-[10px]">Total for Selected Range</td>
                  <td className="p-4 text-right font-mono">
                    ${cogsSchedule.reduce((s, r) => s + r.orderCogs, 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                  <td className="p-4 text-right font-mono text-emerald-700">
                    ${cogsSchedule.reduce((s, r) => s + r.refundCogs, 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                  <td className="p-4 text-right font-mono text-lg underline decoration-double">
                    ${cogsSchedule.reduce((s, r) => s + (r.orderCogs - r.refundCogs), 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                </tr>
              </tfoot>
            </table>
          </div>
        )}
      </section>
    </div>
  );
};

export default CogsManager;

import React, { useMemo } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force 'en-US' locale for consistent keys across browsers
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {

  const handleClearPeriod = (p: string) => {
    console.log("UI: Requesting removal of month key:", p);
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description');
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => parseFloat(val.replace(/,/g, '').replace(/\$/g, '')) || 0;

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;

        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);

        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      if (type === 'Order') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (description.toLowerCase().includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (type === 'Refund') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (type === 'Adjustment') {
        if (description.toLowerCase().includes('reimbursement')) addToSummary('FBA reimbursement', total);
        else addToSummary('Other', total);
      }
      else if (type === 'Service Fee') {
        if (description.toLowerCase().includes('subscription')) addToSummary('Account subscription', total);
        else if (description.toLowerCase().includes('advertising')) addToSummary('Advertising fees', total);
        else addToSummary('Other', total);
      }
      else if (type === 'FBA Transaction fees') {
        if (description.toLowerCase().includes('storage')) addToSummary('FBA storage fees', total);
        else if (description.toLowerCase().includes('awd')) addToSummary('AWD fees', total);
        else if (description.toLowerCase().includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (description.toLowerCase().includes('inbound') || description.toLowerCase().includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (type === 'Transfer') addToSummary('Transfer', total);
      else if (type === 'Shipping Services') addToSummary('FBM shipping fees', total);
      else addToSummary('Other', total);
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    // 1. TRUTH LOG: Checking received SKU costs
    console.log("COGS DEBUG: Loaded SKU Costs:", Object.keys(skuData).length, skuData);

    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const qtyMap: any = {};
    const cogsMap: Record<string, { orderCogs: number, refundCogs: number }> = {};
    const warnedSkus = new Set<string>();

    const cleanSku = (s: string) => s?.trim() || '';

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;

      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!qtyMap[pk]) qtyMap[pk] = {};
      if (!qtyMap[pk][r.sku]) qtyMap[pk][r.sku] = {};
      if (!qtyMap[pk][r.sku][r.type]) qtyMap[pk][r.sku][r.type] = 0;
      qtyMap[pk][r.sku][r.type] += r.quantity;

      // --- COGS CALCULATION LOGIC ---
      if (!cogsMap[pk]) cogsMap[pk] = { orderCogs: 0, refundCogs: 0 };

      const cleanedSku = cleanSku(r.sku);
      const unitCost = skuData[cleanedSku]?.cost || 0;

      // Truth Log for SKU matching
      if (r.sku && r.sku !== 'NON-SKU' && (r.type === 'Order' || r.type === 'Refund')) {
        console.log(`COGS Match: SKU "${r.sku}" -> Cleaned: "${cleanedSku}" | Cost found: ${unitCost} | Qty: ${r.quantity}`);
      }

      if (r.sku && r.sku !== 'NON-SKU' && unitCost === 0 && (r.type === 'Order' || r.type === 'Refund')) {
        if (!warnedSkus.has(cleanedSku)) {
          console.warn(`[COGS Warning] SKU "${cleanedSku}" has a unit cost of $0.00. Update COGS Manager.`);
          warnedSkus.add(cleanedSku);
        }
      }

      if (r.type === 'Order') {
        cogsMap[pk].orderCogs += (r.quantity * unitCost);
      } else if (r.type === 'Refund') {
        // Refund quantities are usually negative (e.g. -1).
        // Multiply by cost results in negative COGS (a credit).
        cogsMap[pk].refundCogs += (r.quantity * unitCost);
      }
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const parse = (s: string) => {
        const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
        const m = s.slice(0, 3);
        const y = parseInt(s.slice(3));
        return new Date(2000 + y, months[m]).getTime();
      };
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, qtyMap, cogsMap };
  }, [records, skuData]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;

    if (!sku) {
      if (!type) return p[cat]._total;
      let typeTotal = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) typeTotal += p[cat][sKey][type];
      });
      return typeTotal;
    }

    if (!p[cat][sku]) return 0;
    if (!type) {
      return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    }
    return p[cat][sku][type] || 0;
  };

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => {
                      return (
                        <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                          <div className="flex flex-col items-end">
                            <span className="mb-1">{p}</span>
                            <button 
                              disabled={isSyncing}
                              onClick={() => handleClearPeriod(p)}
                              className="text-[8px] font-black uppercase tracking-widest transition-opacity text-red-500 opacity-0 group-hover/th:opacity-100 hover:underline cursor-pointer disabled:opacity-30"
                            >
                              Clear Month
                            </button>
                          </div>
                        </th>
                      );
                    })}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {pivotData.skus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue (Gross Orders)</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {FEE_LIST.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isCredit = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isCredit && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>{val !== 0 ? Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-indigo-600 pl-3">Profitability & Margin Analysis</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Performance Metric</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 text-right font-black uppercase text-[10px] tracking-widest">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Revenue (Net)</td>
                    {pivotData.periods.map(p => (
                      <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">
                        ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-500">
                          (${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 2 })})
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-50">
                    <td className="p-4 font-black text-slate-900 italic">Net Amazon Transfer (Cash Out)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-emerald-700">
                          ${transfer.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">Est. Cost of Goods (Orders)</td>
                    {pivotData.periods.map(p => {
                      const val = pivotData.cogsMap[p]?.orderCogs || 0;
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-600">
                          {val !== 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : '-'}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">COGS Reversal (Returns)</td>
                    {pivotData.periods.map(p => {
                      const val = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-emerald-600">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-white font-black border-t-2 border-slate-700">
                    <td className="p-4 text-xs uppercase tracking-[0.2em]">Gross Profit (Cash Basis)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs + returnCogs;
                      return (
                        <td key={p} className={`p-4 text-right font-mono text-base ${profit < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                          ${profit.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-indigo-50 border-t-2 border-indigo-100">
                    <td className="p-4 font-black text-indigo-900 uppercase tracking-widest text-[10px]">Gross Margin %</td>
                    {pivotData.periods.map(p => {
                      const revenue = getAmt(p, 'Revenue');
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs + returnCogs;
                      const margin = revenue !== 0 ? (profit / revenue) * 100 : 0;
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-indigo-800 text-base">
                          {margin.toFixed(1)}%
                        </td>
                      );
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] font-bold text-slate-400 italic px-4">
              Note: Gross Profit (Cash Basis) = Amazon Transfer - Order COGS + Returned Inventory Value. 
              This represents the actual cash profit generated after accounting for product drain.
            </p>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useMemo } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force 'en-US' locale for consistent keys across browsers
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {

  const handleClearPeriod = (p: string) => {
    console.log("UI: Requesting removal of month key:", p);
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description');
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => {
        const cleaned = val.replace(/[(),]/g, (match) => match === '(' || match === ')' ? '' : '').replace(/\$/g, '').trim();
        const num = parseFloat(cleaned) || 0;
        return val.includes('(') ? -Math.abs(num) : num;
      };

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;

        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);

        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      if (type === 'Order') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (description.toLowerCase().includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (type === 'Refund') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (type === 'Adjustment') {
        // Critical Fix: Pass Qty for adjustments (lost/damaged units) to ensure accurate COGS drain
        if (description.toLowerCase().includes('reimbursement')) addToSummary('FBA reimbursement', total, qty);
        else addToSummary('Other', total, qty);
      }
      else if (type === 'Service Fee') {
        if (description.toLowerCase().includes('subscription')) addToSummary('Account subscription', total);
        else if (description.toLowerCase().includes('advertising')) addToSummary('Advertising fees', total);
        else addToSummary('Other', total);
      }
      else if (type === 'FBA Transaction fees') {
        if (description.toLowerCase().includes('storage')) addToSummary('FBA storage fees', total);
        else if (description.toLowerCase().includes('awd')) addToSummary('AWD fees', total);
        else if (description.toLowerCase().includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (description.toLowerCase().includes('inbound') || description.toLowerCase().includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (type === 'Transfer') addToSummary('Transfer', total);
      else if (type === 'Shipping Services') addToSummary('FBM shipping fees', total);
      else addToSummary('Other', total);
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const qtyMap: any = {};
    const cogsMap: Record<string, { orderCogs: number, refundCogs: number, adjustmentCogs: number }> = {};

    const normalize = (s: string) => s?.trim().toUpperCase() || '';

    // Create a normalized SKU lookup map for matching
    const normalizedSkuData: SkuDataMap = {};
    Object.keys(skuData).forEach(k => {
      normalizedSkuData[normalize(k)] = skuData[k];
    });

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;

      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!qtyMap[pk]) qtyMap[pk] = {};
      if (!qtyMap[pk][r.sku]) qtyMap[pk][r.sku] = {};
      if (!qtyMap[pk][r.sku][r.type]) qtyMap[pk][r.sku][r.type] = 0;
      qtyMap[pk][r.sku][r.type] += r.quantity;

      // --- ADVANCED COGS CALCULATION ---
      if (!cogsMap[pk]) cogsMap[pk] = { orderCogs: 0, refundCogs: 0, adjustmentCogs: 0 };

      const normalizedSku = normalize(r.sku);
      const unitCost = normalizedSkuData[normalizedSku]?.cost || 0;

      if (r.type === 'Order') {
        cogsMap[pk].orderCogs += (r.quantity * unitCost);
      } else if (r.type === 'Refund') {
        // Amazon refunds have negative quantities. Multiply by cost = negative COGS (credit).
        cogsMap[pk].refundCogs += (r.quantity * unitCost);
      } else if (r.type === 'Adjustment') {
        // Handle inventory drain from lost/damaged reimbursements
        cogsMap[pk].adjustmentCogs += (r.quantity * unitCost);
      }
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const parse = (s: string) => {
        const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
        const m = s.slice(0, 3);
        const y = parseInt(s.slice(3));
        return new Date(2000 + y, months[m]).getTime();
      };
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, qtyMap, cogsMap };
  }, [records, skuData]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;

    if (!sku) {
      if (!type) return p[cat]._total;
      let typeTotal = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) typeTotal += p[cat][sKey][type];
      });
      return typeTotal;
    }

    if (!p[cat][sku]) return 0;
    if (!type) {
      return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    }
    return p[cat][sku][type] || 0;
  };

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => {
                      return (
                        <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                          <div className="flex flex-col items-end">
                            <span className="mb-1">{p}</span>
                            <button 
                              disabled={isSyncing}
                              onClick={() => handleClearPeriod(p)}
                              className="text-[8px] font-black uppercase tracking-widest transition-opacity text-red-500 opacity-0 group-hover/th:opacity-100 hover:underline cursor-pointer disabled:opacity-30"
                            >
                              Clear Month
                            </button>
                          </div>
                        </th>
                      );
                    })}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {pivotData.skus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-indigo-600 pl-3">Profitability & Margin Analysis</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Performance Metric</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 text-right font-black uppercase text-[10px] tracking-widest">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Revenue (Net)</td>
                    {pivotData.periods.map(p => (
                      <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">
                        ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-500">
                          (${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 2 })})
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-50">
                    <td className="p-4 font-black text-slate-900 italic">Net Amazon Transfer (Cash Out)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-emerald-700">
                          ${transfer.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">Est. Cost of Goods (Orders)</td>
                    {pivotData.periods.map(p => {
                      const val = (pivotData.cogsMap[p]?.orderCogs || 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-600 font-bold">
                          {val !== 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : '-'}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600 italic">COGS Adjustments (Reimbursements/Lost)</td>
                    {pivotData.periods.map(p => {
                      const val = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      return (
                        <td key={p} className={`p-4 text-right font-mono ${val > 0 ? 'text-red-500' : 'text-emerald-500'}`}>
                          {val !== 0 ? (val > 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : val.toLocaleString(undefined, { minimumFractionDigits: 2 })) : '-'}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">COGS Reversal (Returns)</td>
                    {pivotData.periods.map(p => {
                      // Returns are negative qty in CSV. Multiply by cost = negative COGS. Math.abs to show as positive recovery.
                      const val = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-white font-black border-t-2 border-slate-700">
                    <td className="p-4 text-xs uppercase tracking-[0.2em]">Gross Profit (Cash Basis)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      return (
                        <td key={p} className={`p-4 text-right font-mono text-base ${profit < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                          ${profit.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-indigo-50 border-t-2 border-indigo-100">
                    <td className="p-4 font-black text-indigo-900 uppercase tracking-widest text-[10px]">Gross Margin %</td>
                    {pivotData.periods.map(p => {
                      const revenue = getAmt(p, 'Revenue');
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      const margin = revenue !== 0 ? (profit / revenue) * 100 : 0;
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-indigo-800 text-base">
                          {margin.toFixed(1)}%
                        </td>
                      );
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] font-bold text-slate-400 italic px-4">
              Note: Gross Profit (Cash Basis) = Amazon Transfer - (Order COGS + Adjustment COGS) + Returned Inventory Value. 
              Adjustment COGS includes product drain from lost/damaged items found in reimbursements.
            </p>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useRef } from 'react';
import { SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  onUpdateSkuData: (data: SkuDataMap) => void;
}

const CogsManager: React.FC<Props> = ({ skuData, onUpdateSkuData }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const downloadTemplate = () => {
    const csv = "sku,item_name,unit_cogs\nSKU-123,Product Example,5.50\n";
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = "cogs_template.csv";
    a.click();
  };

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const csv = ev.target?.result as string;
      const lines = csv.split('\n');
      const newData: SkuDataMap = { ...skuData };

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const [sku, name, cost] = line.split(',').map(v => v.replace(/"/g, '').trim());
        if (sku) {
          const parsedCost = parseFloat(cost) || 0;
          newData[sku] = { name: name || sku, cost: Math.round(parsedCost * 100) / 100 };
        }
      }
      onUpdateSkuData(newData);
      if (fileInputRef.current) fileInputRef.current.value = '';
      alert("SKU data updated successfully!");
    };
    reader.readAsText(file);
  };

  const sortedSkus = Object.keys(skuData).sort();

  return (
    <div className="space-y-12">
      {/* SECTION: Weighted Average Costs */}
      <section className="space-y-8">
        <div className="flex justify-between items-end border-b pb-6">
          <div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tight">COGS Manager</h2>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Weighted Average Product Costs</p>
          </div>
          <div className="flex gap-3">
            <button onClick={downloadTemplate} className="bg-slate-100 text-slate-600 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-200 transition-all border border-slate-200">
              Get Template
            </button>
            <input type="file" ref={fileInputRef} onChange={handleUpload} accept=".csv" className="hidden" />
            <button onClick={() => fileInputRef.current?.click()} className="bg-slate-900 text-white px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-slate-800 shadow-lg shadow-slate-200 transition-all active:scale-95">
              Upload SKU Costs
            </button>
          </div>
        </div>

        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-sm border-collapse">
            <thead className="bg-slate-50 border-b">
              <tr>
                <th className="p-4 text-left font-black uppercase text-[10px] text-slate-400 w-1/4">SKU Code</th>
                <th className="p-4 text-left font-black uppercase text-[10px] text-slate-400">Item Name</th>
                <th className="p-4 text-right font-black uppercase text-[10px] text-slate-400 w-32">Unit Cost</th>
                <th className="p-4 w-16"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {sortedSkus.length === 0 && (
                <tr>
                  <td colSpan={4} className="p-12 text-center text-slate-400 italic">No SKU data configured. Upload a CSV to get started.</td>
                </tr>
              )}
              {sortedSkus.map(sku => (
                <tr key={sku} className="group hover:bg-slate-50 transition-colors">
                  <td className="p-4 font-mono font-bold text-slate-900">{sku}</td>
                  <td className="p-4">
                    <input 
                      type="text" value={skuData[sku].name} 
                      onChange={(e) => onUpdateSkuData({ ...skuData, [sku]: { ...skuData[sku], name: e.target.value } })}
                      className="w-full bg-transparent border-b border-transparent group-hover:border-slate-200 focus:border-emerald-500 focus:ring-0 outline-none font-medium"
                    />
                  </td>
                  <td className="p-4 text-right">
                    <div className="relative inline-block">
                      <span className="absolute left-2 top-2 text-xs text-slate-400">$</span>
                      <input 
                        type="text" 
                        value={Number(skuData[sku].cost || 0).toFixed(2)} 
                        onChange={(e) => {
                          const rawVal = e.target.value.replace(/[^0-9.]/g, '');
                          const val = rawVal === '' ? 0 : parseFloat(rawVal);
                          onUpdateSkuData({ ...skuData, [sku]: { ...skuData[sku], cost: isNaN(val) ? 0 : val } });
                        }}
                        onBlur={(e) => {
                          const val = parseFloat(e.target.value) || 0;
                          const rounded = Math.round(val * 100) / 100;
                          onUpdateSkuData({ ...skuData, [sku]: { ...skuData[sku], cost: rounded } });
                        }}
                        className="w-24 bg-transparent border-b border-transparent group-hover:border-slate-200 focus:border-emerald-500 focus:ring-0 outline-none text-right font-mono font-bold"
                      />
                    </div>
                  </td>
                  <td className="p-4 text-right">
                    <button 
                      onClick={() => {
                        const next = { ...skuData };
                        delete next[sku];
                        onUpdateSkuData(next);
                      }}
                      className="text-red-300 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-all font-bold"
                    >✕</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
};

export default CogsManager;

import React, { useMemo, useState } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {
  const [sortMonth, setSortMonth] = useState<string | null>(null);

  const handleClearPeriod = (p: string) => {
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description');
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => {
        const cleaned = val.replace(/[(),]/g, (match) => match === '(' || match === ')' ? '' : '').replace(/\$/g, '').trim();
        const num = parseFloat(cleaned) || 0;
        return val.includes('(') ? -Math.abs(num) : num;
      };

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;
        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);
        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      if (type === 'Order') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (description.toLowerCase().includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);
        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (type === 'Refund') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (type === 'Adjustment') {
        if (description.toLowerCase().includes('reimbursement')) addToSummary('FBA reimbursement', total, qty);
        else addToSummary('Other', total, qty);
      }
      else if (type === 'Service Fee') {
        if (description.toLowerCase().includes('subscription')) addToSummary('Account subscription', total);
        else if (description.toLowerCase().includes('advertising')) addToSummary('Advertising fees', total);
        else addToSummary('Other', total);
      }
      else if (type === 'FBA Transaction fees') {
        if (description.toLowerCase().includes('storage')) addToSummary('FBA storage fees', total);
        else if (description.toLowerCase().includes('awd')) addToSummary('AWD fees', total);
        else if (description.toLowerCase().includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (description.toLowerCase().includes('inbound') || description.toLowerCase().includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (type === 'Transfer') addToSummary('Transfer', total);
      else if (type === 'Shipping Services') addToSummary('FBM shipping fees', total);
      else addToSummary('Other', total);
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const cogsMap: Record<string, { orderCogs: number, refundCogs: number, adjustmentCogs: number }> = {};
    const normalize = (s: string) => s?.trim().toUpperCase() || '';
    const normalizedSkuData: SkuDataMap = {};
    Object.keys(skuData).forEach(k => { normalizedSkuData[normalize(k)] = skuData[k]; });

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;
      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!cogsMap[pk]) cogsMap[pk] = { orderCogs: 0, refundCogs: 0, adjustmentCogs: 0 };
      const normalizedSku = normalize(r.sku);
      const unitCost = normalizedSkuData[normalizedSku]?.cost || 0;

      if (r.type === 'Order') cogsMap[pk].orderCogs += (r.quantity * unitCost);
      else if (r.type === 'Refund') cogsMap[pk].refundCogs += (r.quantity * unitCost);
      else if (r.type === 'Adjustment') cogsMap[pk].adjustmentCogs += (r.quantity * unitCost);
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
      const parse = (s: string) => new Date(2000 + parseInt(s.slice(3)), months[s.slice(0, 3)]).getTime();
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, cogsMap };
  }, [records, skuData]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;
    if (!sku) {
      if (!type) return p[cat]._total;
      let typeTotal = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) typeTotal += p[cat][sKey][type];
      });
      return typeTotal;
    }
    if (!p[cat][sku]) return 0;
    if (!type) return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    return p[cat][sku][type] || 0;
  };

  const sortedSkus = useMemo(() => {
    if (!sortMonth) return pivotData.skus;
    return [...pivotData.skus].sort((a, b) => {
      const valA = getAmt(sortMonth, 'Revenue', a);
      const valB = getAmt(sortMonth, 'Revenue', b);
      return valB - valA;
    });
  }, [pivotData.skus, sortMonth, pivotData.amountMap]);

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
              {sortMonth && (
                <button onClick={() => setSortMonth(null)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors">Reset Sort</button>
              )}
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => (
                      <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                        <div className="flex flex-col items-end">
                          <span className="mb-1">{p}</span>
                          <div className="flex gap-2 opacity-0 group-hover/th:opacity-100 transition-opacity">
                            <button onClick={() => setSortMonth(p)} className="text-[8px] font-black uppercase tracking-widest text-blue-500 hover:underline">Sort</button>
                            <button onClick={() => handleClearPeriod(p)} className="text-[8px] font-black uppercase tracking-widest text-red-500 hover:underline">Clear</button>
                          </div>
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sortedSkus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>)}
                  </tr>
                  <tr className="bg-slate-50/50">
                    <td className="p-4 font-bold text-slate-700 italic">Gross Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 2 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {FEE_LIST.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isReimbursement = fee === 'FBA reimbursement';
                        // Matches visual style of the screenshot: Reimbursements are bracketed credits
                        return <td key={p} className={`p-4 text-right font-mono ${isReimbursement && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>
                          {val === 0 ? '-' : (val > 0 && isReimbursement ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 0 })})` : Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }))}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-indigo-600 pl-3">Profitability & Margin Analysis</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Performance Metric</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 text-right font-black uppercase text-[10px] tracking-widest">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Revenue (Net)</td>
                    {pivotData.periods.map(p => (
                      <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">
                        ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-500">
                          (${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 2 })})
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-50">
                    <td className="p-4 font-black text-slate-900 italic">Net Amazon Transfer (Cash Out)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-emerald-700">
                          ${transfer.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">Est. Cost of Goods (Orders)</td>
                    {pivotData.periods.map(p => {
                      const val = (pivotData.cogsMap[p]?.orderCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-red-600 font-bold">{val !== 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600 italic">COGS Adjustments (Reimbursements/Lost)</td>
                    {pivotData.periods.map(p => {
                      const val = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      return <td key={p} className={`p-4 text-right font-mono ${val > 0 ? 'text-red-500' : 'text-emerald-500'}`}>
                        {val !== 0 ? (val > 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : val.toLocaleString(undefined, { minimumFractionDigits: 2 })) : '-'}
                      </td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">COGS Reversal (Returns)</td>
                    {pivotData.periods.map(p => {
                      const val = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">{val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-white font-black border-t-2 border-slate-700">
                    <td className="p-4 text-xs uppercase tracking-[0.2em]">Gross Profit (Cash Basis)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      return <td key={p} className={`p-4 text-right font-mono text-base ${profit < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                        ${profit.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    })}
                  </tr>
                  <tr className="bg-indigo-50 border-t-2 border-indigo-100">
                    <td className="p-4 font-black text-indigo-900 uppercase tracking-widest text-[10px]">Gross Margin %</td>
                    {pivotData.periods.map(p => {
                      const revenue = getAmt(p, 'Revenue');
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      const margin = revenue !== 0 ? (profit / revenue) * 100 : 0;
                      return <td key={p} className="p-4 text-right font-mono font-black text-indigo-800 text-base">{margin.toFixed(1)}%</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] font-bold text-slate-400 italic px-4">Note: Gross Profit (Cash Basis) = Amazon Transfer - (Order COGS + Adjustment COGS) + Returned Inventory Value.</p>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useMemo, useState } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force 'en-US' locale for consistent keys across browsers
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {
  const [sortMonth, setSortMonth] = useState<string | null>(null);

  const handleClearPeriod = (p: string) => {
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description') || '';
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => {
        const cleaned = val.replace(/[(),]/g, (match) => match === '(' || match === ')' ? '' : '').replace(/\$/g, '').trim();
        const num = parseFloat(cleaned) || 0;
        return val.includes('(') ? -Math.abs(num) : num;
      };

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;
        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);
        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      const lType = type.toLowerCase();
      const lDesc = description.toLowerCase();

      // CATEGORIZATION DIGGING LOGIC
      if (lType === 'order') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (lDesc.includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (lType === 'refund') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (lType === 'adjustment') {
        if (lDesc.includes('reimbursement')) addToSummary('FBA reimbursement', total, qty);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total, qty);
        else addToSummary('Other', total, qty);
      }
      else if (lType === 'service fee') {
        if (lDesc.includes('subscription')) addToSummary('Account subscription', total);
        else if (lDesc.includes('advertising') || lDesc.includes('cost per click')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('placement')) addToSummary('Inbound shipping fees', total);
        else addToSummary('Other', total);
      }
      else if (lType === 'fba transaction fees' || lType === 'fba inventory fee') {
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('awd')) addToSummary('AWD fees', total);
        else if (lDesc.includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (lDesc.includes('return')) addToSummary('Return fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (lType === 'transfer') addToSummary('Transfer', total);
      else if (lType === 'shipping services') addToSummary('FBM shipping fees', total);
      else {
        // Deep diving into anything else falling through
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('advertising')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('referral') || lDesc.includes('selling fee')) addToSummary('Selling fees', total);
        else if (lDesc.includes('fulfillment')) addToSummary('FBA fees', total);
        else addToSummary('Other', total);
      }
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const cogsMap: Record<string, { orderCogs: number, refundCogs: number, adjustmentCogs: number }> = {};

    const normalize = (s: string) => s?.trim().toUpperCase() || '';
    const normalizedSkuData: SkuDataMap = {};
    Object.keys(skuData).forEach(k => { normalizedSkuData[normalize(k)] = skuData[k]; });

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;
      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!cogsMap[pk]) cogsMap[pk] = { orderCogs: 0, refundCogs: 0, adjustmentCogs: 0 };
      const normalizedSku = normalize(r.sku);
      const unitCost = normalizedSkuData[normalizedSku]?.cost || 0;

      if (r.type === 'Order') cogsMap[pk].orderCogs += (r.quantity * unitCost);
      else if (r.type === 'Refund') cogsMap[pk].refundCogs += (r.quantity * unitCost);
      else if (r.type === 'Adjustment' || r.category === 'FBA reimbursement') cogsMap[pk].adjustmentCogs += (r.quantity * unitCost);
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
      const parse = (s: string) => new Date(2000 + parseInt(s.slice(3)), months[s.slice(0, 3)]).getTime();
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, cogsMap };
  }, [records, skuData]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;
    if (!sku) {
      if (!type) return p[cat]._total;
      let typeTotal = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) typeTotal += p[cat][sKey][type];
      });
      return typeTotal;
    }
    if (!p[cat][sku]) return 0;
    if (!type) return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    return p[cat][sku][type] || 0;
  };

  const sortedSkus = useMemo(() => {
    if (!sortMonth) return pivotData.skus;
    return [...pivotData.skus].sort((a, b) => {
      const valA = getAmt(sortMonth, 'Revenue', a);
      const valB = getAmt(sortMonth, 'Revenue', b);
      return valB - valA;
    });
  }, [pivotData.skus, sortMonth, pivotData.amountMap]);

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
              {sortMonth && (
                <button onClick={() => setSortMonth(null)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors">Reset Sort</button>
              )}
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => (
                      <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                        <div className="flex flex-col items-end">
                          <span className="mb-1">{p}</span>
                          <div className="flex gap-2 opacity-0 group-hover/th:opacity-100 transition-opacity">
                            <button onClick={() => setSortMonth(p)} className="text-[8px] font-black uppercase tracking-widest text-blue-500 hover:underline">Sort</button>
                            <button onClick={() => handleClearPeriod(p)} className="text-[8px] font-black uppercase tracking-widest text-red-500 hover:underline">Clear</button>
                          </div>
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sortedSkus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr className="bg-slate-50/50">
                    <td className="p-4 font-bold text-slate-700 italic">Gross Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {FEE_LIST.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isReimbursement = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isReimbursement && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>
                          {val === 0 ? '-' : (val > 0 && isReimbursement ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 0 })})` : Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }))}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-indigo-600 pl-3">Profitability & Margin Analysis</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Performance Metric</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 text-right font-black uppercase text-[10px] tracking-widest">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Revenue (Net)</td>
                    {pivotData.periods.map(p => (
                      <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">
                        ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-500">
                          (${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 2 })})
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-50">
                    <td className="p-4 font-black text-slate-900 italic">Net Amazon Transfer (Cash Out)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-emerald-700">
                          ${transfer.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">Est. Cost of Goods (Orders)</td>
                    {pivotData.periods.map(p => {
                      const val = (pivotData.cogsMap[p]?.orderCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-red-600 font-bold">{val !== 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600 italic">COGS Adjustments (Reimbursements/Lost)</td>
                    {pivotData.periods.map(p => {
                      const val = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      return <td key={p} className={`p-4 text-right font-mono ${val > 0 ? 'text-red-500' : 'text-emerald-500'}`}>
                        {val !== 0 ? (val > 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : val.toLocaleString(undefined, { minimumFractionDigits: 2 })) : '-'}
                      </td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">COGS Reversal (Returns)</td>
                    {pivotData.periods.map(p => {
                      const val = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">{val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-white font-black border-t-2 border-slate-700">
                    <td className="p-4 text-xs uppercase tracking-[0.2em]">Gross Profit (Cash Basis)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      return <td key={p} className={`p-4 text-right font-mono text-base ${profit < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                        ${profit.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    })}
                  </tr>
                  <tr className="bg-indigo-50 border-t-2 border-indigo-100">
                    <td className="p-4 font-black text-indigo-900 uppercase tracking-widest text-[10px]">Gross Margin %</td>
                    {pivotData.periods.map(p => {
                      const revenue = getAmt(p, 'Revenue');
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      const margin = revenue !== 0 ? (profit / revenue) * 100 : 0;
                      return <td key={p} className="p-4 text-right font-mono font-black text-indigo-800 text-base">{margin.toFixed(1)}%</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] font-bold text-slate-400 italic px-4">Note: Gross Profit (Cash Basis) = Amazon Transfer - (Order COGS + Adjustment COGS) + Returned Inventory Value.</p>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useMemo, useState } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force 'en-US' locale for consistent keys across browsers
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {
  const [sortMonth, setSortMonth] = useState<string | null>(null);
  const [feeSortMonth, setFeeSortMonth] = useState<string | null>(null);

  const handleClearPeriod = (p: string) => {
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description') || '';
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => {
        const cleaned = val.replace(/[(),]/g, (match) => match === '(' || match === ')' ? '' : '').replace(/\$/g, '').trim();
        const num = parseFloat(cleaned) || 0;
        return val.includes('(') ? -Math.abs(num) : num;
      };

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;
        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);
        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      const lType = type.toLowerCase();
      const lDesc = description.toLowerCase();

      // CATEGORIZATION DIGGING LOGIC
      if (lType === 'order') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (lDesc.includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (lType === 'refund') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (lType === 'adjustment') {
        if (lDesc.includes('reimbursement')) addToSummary('FBA reimbursement', total, qty);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total, qty);
        else addToSummary('Other', total, qty);
      }
      else if (lType === 'service fee') {
        if (lDesc.includes('subscription')) addToSummary('Account subscription', total);
        else if (lDesc.includes('advertising') || lDesc.includes('cost per click')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('placement')) addToSummary('Inbound shipping fees', total);
        else addToSummary('Other', total);
      }
      else if (lType === 'fba transaction fees' || lType === 'fba inventory fee') {
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('awd')) addToSummary('AWD fees', total);
        else if (lDesc.includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (lDesc.includes('return')) addToSummary('Return fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (lType === 'transfer') addToSummary('Transfer', total);
      else if (lType === 'shipping services') addToSummary('FBM shipping fees', total);
      else {
        // Deep diving into anything else falling through
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('advertising')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('referral') || lDesc.includes('selling fee')) addToSummary('Selling fees', total);
        else if (lDesc.includes('fulfillment')) addToSummary('FBA fees', total);
        else addToSummary('Other', total);
      }
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const cogsMap: Record<string, { orderCogs: number, refundCogs: number, adjustmentCogs: number }> = {};

    const normalize = (s: string) => s?.trim().toUpperCase() || '';
    const normalizedSkuData: SkuDataMap = {};
    Object.keys(skuData).forEach(k => { normalizedSkuData[normalize(k)] = skuData[k]; });

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;
      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!cogsMap[pk]) cogsMap[pk] = { orderCogs: 0, refundCogs: 0, adjustmentCogs: 0 };
      const normalizedSku = normalize(r.sku);
      const unitCost = normalizedSkuData[normalizedSku]?.cost || 0;

      if (r.type === 'Order') cogsMap[pk].orderCogs += (r.quantity * unitCost);
      else if (r.type === 'Refund') cogsMap[pk].refundCogs += (r.quantity * unitCost);
      else if (r.type === 'Adjustment' || r.category === 'FBA reimbursement') cogsMap[pk].adjustmentCogs += (r.quantity * unitCost);
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
      const parse = (s: string) => new Date(2000 + parseInt(s.slice(3)), months[s.slice(0, 3)]).getTime();
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, cogsMap };
  }, [records, skuData]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;
    if (!sku) {
      if (!type) return p[cat]._total;
      let typeTotal = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) typeTotal += p[cat][sKey][type];
      });
      return typeTotal;
    }
    if (!p[cat][sku]) return 0;
    if (!type) return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    return p[cat][sku][type] || 0;
  };

  const sortedSkus = useMemo(() => {
    if (!sortMonth) return pivotData.skus;
    return [...pivotData.skus].sort((a, b) => {
      const valA = getAmt(sortMonth, 'Revenue', a);
      const valB = getAmt(sortMonth, 'Revenue', b);
      return valB - valA;
    });
  }, [pivotData.skus, sortMonth, pivotData.amountMap]);

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  const sortedFeeList = useMemo(() => {
    if (!feeSortMonth) return FEE_LIST;
    return [...FEE_LIST].sort((a, b) => {
      const valA = Math.abs(getAmt(feeSortMonth, a));
      const valB = Math.abs(getAmt(feeSortMonth, b));
      return valB - valA;
    });
  }, [feeSortMonth, pivotData.amountMap]);

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
              {sortMonth && (
                <button onClick={() => setSortMonth(null)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors">Reset Sort</button>
              )}
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => (
                      <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                        <div className="flex flex-col items-end">
                          <span className="mb-1">{p}</span>
                          <div className="flex gap-2 opacity-0 group-hover/th:opacity-100 transition-opacity">
                            <button onClick={() => setSortMonth(p)} className="text-[8px] font-black uppercase tracking-widest text-blue-500 hover:underline">Sort</button>
                            <button onClick={() => handleClearPeriod(p)} className="text-[8px] font-black uppercase tracking-widest text-red-500 hover:underline">Clear</button>
                          </div>
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sortedSkus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr className="bg-slate-50/50">
                    <td className="p-4 font-bold text-slate-700 italic">Gross Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
              {feeSortMonth && (
                <button onClick={() => setFeeSortMonth(null)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors">Reset Sort</button>
              )}
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => (
                      <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                        <div className="flex flex-col items-end">
                          <span className="mb-1">{p}</span>
                          <div className="flex gap-2 opacity-0 group-hover/th:opacity-100 transition-opacity">
                            <button onClick={() => setFeeSortMonth(p)} className="text-[8px] font-black uppercase tracking-widest text-amber-600 hover:underline">Sort</button>
                          </div>
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sortedFeeList.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isReimbursement = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isReimbursement && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>
                          {val === 0 ? '-' : (val > 0 && isReimbursement ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 0 })})` : Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }))}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-indigo-600 pl-3">Profitability & Margin Analysis</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Performance Metric</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 text-right font-black uppercase text-[10px] tracking-widest">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Revenue (Net)</td>
                    {pivotData.periods.map(p => (
                      <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">
                        ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-500">
                          (${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 2 })})
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-50">
                    <td className="p-4 font-black text-slate-900 italic">Net Amazon Transfer (Cash Out)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-emerald-700">
                          ${transfer.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">Est. Cost of Goods (Orders)</td>
                    {pivotData.periods.map(p => {
                      const val = (pivotData.cogsMap[p]?.orderCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-red-600 font-bold">{val !== 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600 italic">COGS Adjustments (Reimbursements/Lost)</td>
                    {pivotData.periods.map(p => {
                      const val = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      return <td key={p} className={`p-4 text-right font-mono ${val > 0 ? 'text-red-500' : 'text-emerald-500'}`}>
                        {val !== 0 ? (val > 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : val.toLocaleString(undefined, { minimumFractionDigits: 2 })) : '-'}
                      </td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">COGS Reversal (Returns)</td>
                    {pivotData.periods.map(p => {
                      const val = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">{val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-white font-black border-t-2 border-slate-700">
                    <td className="p-4 text-xs uppercase tracking-[0.2em]">Gross Profit (Cash Basis)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      return <td key={p} className={`p-4 text-right font-mono text-base ${profit < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                        ${profit.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    })}
                  </tr>
                  <tr className="bg-indigo-50 border-t-2 border-indigo-100">
                    <td className="p-4 font-black text-indigo-900 uppercase tracking-widest text-[10px]">Gross Margin %</td>
                    {pivotData.periods.map(p => {
                      const revenue = getAmt(p, 'Revenue');
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      const margin = revenue !== 0 ? (profit / revenue) * 100 : 0;
                      return <td key={p} className="p-4 text-right font-mono font-black text-indigo-800 text-base">{margin.toFixed(1)}%</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] font-bold text-slate-400 italic px-4">Note: Gross Profit (Cash Basis) = Amazon Transfer - (Order COGS + Adjustment COGS) + Returned Inventory Value.</p>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useMemo, useState } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force 'en-US' locale for consistent keys across browsers
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {
  const [sortMonth, setSortMonth] = useState<string | null>(null);
  const [feeSortMonth, setFeeSortMonth] = useState<string | null>(null);

  const handleClearPeriod = (p: string) => {
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description') || '';
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => {
        const cleaned = val.replace(/[(),]/g, (match) => match === '(' || match === ')' ? '' : '').replace(/\$/g, '').trim();
        const num = parseFloat(cleaned) || 0;
        return val.includes('(') ? -Math.abs(num) : num;
      };

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;
        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);
        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      const lType = type.toLowerCase();
      const lDesc = description.toLowerCase();

      // CATEGORIZATION DIGGING LOGIC
      if (lType === 'order') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (lDesc.includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (lType === 'refund') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (lType === 'adjustment') {
        if (lDesc.includes('reimbursement')) addToSummary('FBA reimbursement', total, qty);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total, qty);
        else addToSummary('Other', total, qty);
      }
      else if (lType === 'service fee') {
        if (lDesc.includes('subscription')) addToSummary('Account subscription', total);
        else if (lDesc.includes('advertising') || lDesc.includes('cost per click')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('placement')) addToSummary('Inbound shipping fees', total);
        else addToSummary('Other', total);
      }
      else if (lType === 'fba transaction fees' || lType === 'fba inventory fee') {
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('awd')) addToSummary('AWD fees', total);
        else if (lDesc.includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (lDesc.includes('return')) addToSummary('Return fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (lType === 'transfer') addToSummary('Transfer', total);
      else if (lType === 'shipping services') addToSummary('FBM shipping fees', total);
      else {
        // Deep diving into anything else falling through
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('advertising')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('referral') || lDesc.includes('selling fee')) addToSummary('Selling fees', total);
        else if (lDesc.includes('fulfillment')) addToSummary('FBA fees', total);
        else addToSummary('Other', total);
      }
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const cogsMap: Record<string, { orderCogs: number, refundCogs: number, adjustmentCogs: number }> = {};

    const normalize = (s: string) => s?.trim().toUpperCase() || '';
    const normalizedSkuData: SkuDataMap = {};
    Object.keys(skuData).forEach(k => { normalizedSkuData[normalize(k)] = skuData[k]; });

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;
      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!cogsMap[pk]) cogsMap[pk] = { orderCogs: 0, refundCogs: 0, adjustmentCogs: 0 };
      const normalizedSku = normalize(r.sku);
      const unitCost = normalizedSkuData[normalizedSku]?.cost || 0;

      if (r.type === 'Order') cogsMap[pk].orderCogs += (r.quantity * unitCost);
      else if (r.type === 'Refund') cogsMap[pk].refundCogs += (r.quantity * unitCost);
      else if (r.type === 'Adjustment' || r.category === 'FBA reimbursement') cogsMap[pk].adjustmentCogs += (r.quantity * unitCost);
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
      const parse = (s: string) => new Date(2000 + parseInt(s.slice(3)), months[s.slice(0, 3)]).getTime();
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, cogsMap };
  }, [records, skuData]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;
    if (!sku) {
      if (!type) return p[cat]._total;
      let typeTotal = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) typeTotal += p[cat][sKey][type];
      });
      return typeTotal;
    }
    if (!p[cat][sku]) return 0;
    if (!type) return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    return p[cat][sku][type] || 0;
  };

  const sortedSkus = useMemo(() => {
    if (!sortMonth) return pivotData.skus;
    return [...pivotData.skus].sort((a, b) => {
      const valA = getAmt(sortMonth, 'Revenue', a);
      const valB = getAmt(sortMonth, 'Revenue', b);
      return valB - valA;
    });
  }, [pivotData.skus, sortMonth, pivotData.amountMap]);

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  const sortedFeeList = useMemo(() => {
    if (!feeSortMonth) return FEE_LIST;
    return [...FEE_LIST].sort((a, b) => {
      const valA = Math.abs(getAmt(feeSortMonth, a));
      const valB = Math.abs(getAmt(feeSortMonth, b));
      return valB - valA;
    });
  }, [feeSortMonth, pivotData.amountMap]);

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
              {sortMonth && (
                <button onClick={() => setSortMonth(null)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors">Reset Sort</button>
              )}
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => (
                      <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                        <div className="flex flex-col items-end">
                          <span className="mb-1">{p}</span>
                          <div className="flex gap-2 opacity-0 group-hover/th:opacity-100 transition-opacity">
                            <button onClick={() => setSortMonth(p)} className="text-[8px] font-black uppercase tracking-widest text-blue-500 hover:underline">Sort</button>
                            <button onClick={() => handleClearPeriod(p)} className="text-[8px] font-black uppercase tracking-widest text-red-500 hover:underline">Clear</button>
                          </div>
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sortedSkus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
              {feeSortMonth && (
                <button onClick={() => setFeeSortMonth(null)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors">Reset Sort</button>
              )}
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => (
                      <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                        <div className="flex flex-col items-end">
                          <span className="mb-1">{p}</span>
                          <div className="flex gap-2 opacity-0 group-hover/th:opacity-100 transition-opacity">
                            <button onClick={() => setFeeSortMonth(p)} className="text-[8px] font-black uppercase tracking-widest text-amber-600 hover:underline">Sort</button>
                          </div>
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sortedFeeList.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isReimbursement = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isReimbursement && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>
                          {val === 0 ? '-' : (val > 0 && isReimbursement ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 0 })})` : Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }))}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-indigo-600 pl-3">Profitability & Margin Analysis</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Performance Metric</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 text-right font-black uppercase text-[10px] tracking-widest">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Revenue (Net)</td>
                    {pivotData.periods.map(p => (
                      <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">
                        ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-500">
                          (${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 2 })})
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-50">
                    <td className="p-4 font-black text-slate-900 italic">Net Amazon Transfer (Cash Out)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-emerald-700">
                          ${transfer.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">Est. Cost of Goods (Orders)</td>
                    {pivotData.periods.map(p => {
                      const val = (pivotData.cogsMap[p]?.orderCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-red-600 font-bold">{val !== 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600 italic">COGS Adjustments (Reimbursements/Lost)</td>
                    {pivotData.periods.map(p => {
                      const val = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      return <td key={p} className={`p-4 text-right font-mono ${val > 0 ? 'text-red-500' : 'text-emerald-500'}`}>
                        {val !== 0 ? (val > 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2 })})` : val.toLocaleString(undefined, { minimumFractionDigits: 2 })) : '-'}
                      </td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">COGS Reversal (Returns)</td>
                    {pivotData.periods.map(p => {
                      const val = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">{val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-white font-black border-t-2 border-slate-700">
                    <td className="p-4 text-xs uppercase tracking-[0.2em]">Gross Profit (Cash Basis)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      return <td key={p} className={`p-4 text-right font-mono text-base ${profit < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                        ${profit.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    })}
                  </tr>
                  <tr className="bg-indigo-50 border-t-2 border-indigo-100">
                    <td className="p-4 font-black text-indigo-900 uppercase tracking-widest text-[10px]">Gross Margin %</td>
                    {pivotData.periods.map(p => {
                      const revenue = getAmt(p, 'Revenue');
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      const margin = revenue !== 0 ? (profit / revenue) * 100 : 0;
                      return <td key={p} className="p-4 text-right font-mono font-black text-indigo-800 text-base">{margin.toFixed(1)}%</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] font-bold text-slate-400 italic px-4">Note: Gross Profit (Cash Basis) = Amazon Transfer - (Order COGS + Adjustment COGS) + Returned Inventory Value.</p>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useMemo, useState } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force 'en-US' locale for consistent keys across browsers
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {
  const [sortMonth, setSortMonth] = useState<string | null>(null);
  const [feeSortMonth, setFeeSortMonth] = useState<string | null>(null);

  const handleClearPeriod = (p: string) => {
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description') || '';
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => {
        const cleaned = val.replace(/[(),]/g, (match) => match === '(' || match === ')' ? '' : '').replace(/\$/g, '').trim();
        const num = parseFloat(cleaned) || 0;
        return val.includes('(') ? -Math.abs(num) : num;
      };

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;
        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);
        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      const lType = type.toLowerCase();
      const lDesc = description.toLowerCase();

      // CATEGORIZATION DIGGING LOGIC
      if (lType === 'order') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (lDesc.includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (lType === 'refund') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (lType === 'adjustment') {
        if (lDesc.includes('reimbursement')) addToSummary('FBA reimbursement', total, qty);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total, qty);
        else addToSummary('Other', total, qty);
      }
      else if (lType === 'service fee') {
        if (lDesc.includes('subscription')) addToSummary('Account subscription', total);
        else if (lDesc.includes('advertising') || lDesc.includes('cost per click')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('placement')) addToSummary('Inbound shipping fees', total);
        else addToSummary('Other', total);
      }
      else if (lType === 'fba transaction fees' || lType === 'fba inventory fee') {
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('awd')) addToSummary('AWD fees', total);
        else if (lDesc.includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (lDesc.includes('return')) addToSummary('Return fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (lType === 'transfer') addToSummary('Transfer', total);
      else if (lType === 'shipping services') addToSummary('FBM shipping fees', total);
      else {
        // Deep diving into anything else falling through
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('advertising')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('referral') || lDesc.includes('selling fee')) addToSummary('Selling fees', total);
        else if (lDesc.includes('fulfillment')) addToSummary('FBA fees', total);
        else addToSummary('Other', total);
      }
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const cogsMap: Record<string, { orderCogs: number, refundCogs: number, adjustmentCogs: number }> = {};

    const normalize = (s: string) => s?.trim().toUpperCase() || '';
    const normalizedSkuData: SkuDataMap = {};
    Object.keys(skuData).forEach(k => { normalizedSkuData[normalize(k)] = skuData[k]; });

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;
      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!cogsMap[pk]) cogsMap[pk] = { orderCogs: 0, refundCogs: 0, adjustmentCogs: 0 };
      const normalizedSku = normalize(r.sku);
      const unitCost = normalizedSkuData[normalizedSku]?.cost || 0;

      if (r.type === 'Order') cogsMap[pk].orderCogs += (r.quantity * unitCost);
      else if (r.type === 'Refund') cogsMap[pk].refundCogs += (r.quantity * unitCost);
      else if (r.type === 'Adjustment' || r.category === 'FBA reimbursement') cogsMap[pk].adjustmentCogs += (r.quantity * unitCost);
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
      const parse = (s: string) => new Date(2000 + parseInt(s.slice(3)), months[s.slice(0, 3)]).getTime();
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, cogsMap };
  }, [records, skuData]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;
    if (!sku) {
      if (!type) return p[cat]._total;
      let typeTotal = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) typeTotal += p[cat][sKey][type];
      });
      return typeTotal;
    }
    if (!p[cat][sku]) return 0;
    if (!type) return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    return p[cat][sku][type] || 0;
  };

  const sortedSkus = useMemo(() => {
    if (!sortMonth) return pivotData.skus;
    return [...pivotData.skus].sort((a, b) => {
      const valA = getAmt(sortMonth, 'Revenue', a);
      const valB = getAmt(sortMonth, 'Revenue', b);
      return valB - valA;
    });
  }, [pivotData.skus, sortMonth, pivotData.amountMap]);

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  const sortedFeeList = useMemo(() => {
    if (!feeSortMonth) return FEE_LIST;
    return [...FEE_LIST].sort((a, b) => {
      const valA = Math.abs(getAmt(feeSortMonth, a));
      const valB = Math.abs(getAmt(feeSortMonth, b));
      return valB - valA;
    });
  }, [feeSortMonth, pivotData.amountMap]);

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
              {sortMonth && (
                <button onClick={() => setSortMonth(null)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors">Reset Sort</button>
              )}
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => (
                      <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                        <div className="flex flex-col items-end">
                          <span className="mb-1">{p}</span>
                          <div className="flex gap-2 opacity-0 group-hover/th:opacity-100 transition-opacity">
                            <button onClick={() => setSortMonth(p)} className="text-[8px] font-black uppercase tracking-widest text-blue-500 hover:underline">Sort</button>
                            <button onClick={() => handleClearPeriod(p)} className="text-[8px] font-black uppercase tracking-widest text-red-500 hover:underline">Clear</button>
                          </div>
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sortedSkus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">
                          {val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '-'}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">
                      ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
              {feeSortMonth && (
                <button onClick={() => setFeeSortMonth(null)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors">Reset Sort</button>
              )}
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => (
                      <th key={p} className="p-4 font-black text-slate-900 text-right group/th relative transition-opacity">
                        <div className="flex flex-col items-end">
                          <span className="mb-1">{p}</span>
                          <div className="flex gap-2 opacity-0 group-hover/th:opacity-100 transition-opacity">
                            <button onClick={() => setFeeSortMonth(p)} className="text-[8px] font-black uppercase tracking-widest text-amber-600 hover:underline">Sort</button>
                          </div>
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sortedFeeList.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isReimbursement = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isReimbursement && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>
                          {val === 0 ? '-' : (val > 0 && isReimbursement ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })})` : Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }))}
                        </td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-indigo-600 pl-3">Profitability & Margin Analysis</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Performance Metric</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 text-right font-black uppercase text-[10px] tracking-widest">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Revenue (Net)</td>
                    {pivotData.periods.map(p => (
                      <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">
                        ${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return (
                        <td key={p} className="p-4 text-right font-mono text-red-500">
                          (${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })})
                        </td>
                      );
                    })}
                  </tr>
                  <tr className="bg-slate-50">
                    <td className="p-4 font-black text-slate-900 italic">Net Amazon Transfer (Cash Out)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      return (
                        <td key={p} className="p-4 text-right font-mono font-black text-emerald-700">
                          ${transfer.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                        </td>
                      );
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">Est. Cost of Goods (Orders)</td>
                    {pivotData.periods.map(p => {
                      const val = (pivotData.cogsMap[p]?.orderCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-red-600 font-bold">{val !== 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600 italic">COGS Adjustments (Reimbursements/Lost)</td>
                    {pivotData.periods.map(p => {
                      const val = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      return <td key={p} className={`p-4 text-right font-mono ${val > 0 ? 'text-red-500' : 'text-emerald-500'}`}>
                        {val !== 0 ? (val > 0 ? `(${val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })})` : val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })) : '-'}
                      </td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-medium text-slate-600">COGS Reversal (Returns)</td>
                    {pivotData.periods.map(p => {
                      const val = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      return <td key={p} className="p-4 text-right font-mono text-emerald-600 font-bold">{val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-white font-black border-t-2 border-slate-700">
                    <td className="p-4 text-xs uppercase tracking-[0.2em]">Gross Profit (Cash Basis)</td>
                    {pivotData.periods.map(p => {
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      return <td key={p} className={`p-4 text-right font-mono text-base ${profit < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                        ${profit.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                      </td>
                    })}
                  </tr>
                  <tr className="bg-indigo-50 border-t-2 border-indigo-100">
                    <td className="p-4 font-black text-indigo-900 uppercase tracking-widest text-[10px]">Gross Margin %</td>
                    {pivotData.periods.map(p => {
                      const revenue = getAmt(p, 'Revenue');
                      const transfer = Math.abs(getAmt(p, 'Transfer'));
                      const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
                      const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
                      const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
                      const profit = transfer - orderCogs - adjCogs + returnCogs;
                      const margin = revenue !== 0 ? (profit / revenue) * 100 : 0;
                      return <td key={p} className="p-4 text-right font-mono font-black text-indigo-800 text-base">{margin.toFixed(1)}%</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] font-bold text-slate-400 italic px-4">Note: Gross Profit (Cash Basis) = Amazon Transfer - (Order COGS + Adjustment COGS) + Returned Inventory Value.</p>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useMemo, useState } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';
import * as XLSX from 'xlsx';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  onRemovePeriod: (period: string) => void;
  companyName: string;
  isSyncing?: boolean;
}

// SHARED SOURCE OF TRUTH HELPER
const getStandardKey = (dateStr: string) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return "INVALID";
  // Force 'en-US' locale for consistent keys across browsers
  const month = d.toLocaleString('en-US', { month: 'short' });
  const year = String(d.getFullYear()).slice(-2);
  return `${month}${year}`;
};

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, onRemovePeriod, companyName, isSyncing }) => {
  const [sortMonth, setSortMonth] = useState<string | null>(null);
  const [feeSortMonth, setFeeSortMonth] = useState<string | null>(null);

  const handleClearPeriod = (p: string) => {
    onRemovePeriod(p);
  };

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description') || '';
      const qty = parseInt(getVal('quantity')) || 0;

      const periodKey = getStandardKey(dateStr);
      if (periodKey === "INVALID") return;

      const parseNum = (val: string) => {
        const cleaned = val.replace(/[(),]/g, (match) => match === '(' || match === ')' ? '' : '').replace(/\$/g, '').trim();
        const num = parseFloat(cleaned) || 0;
        return val.includes('(') ? -Math.abs(num) : num;
      };

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;
        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);
        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      const lType = type.toLowerCase();
      const lDesc = description.toLowerCase();

      // CATEGORIZATION DIGGING LOGIC
      if (lType === 'order') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (lDesc.includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (lType === 'refund') {
        addToSummary('Revenue', productSales, qty);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (lType === 'adjustment') {
        if (lDesc.includes('reimbursement')) addToSummary('FBA reimbursement', total, qty);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total, qty);
        else addToSummary('Other', total, qty);
      }
      else if (lType === 'service fee') {
        if (lDesc.includes('subscription')) addToSummary('Account subscription', total);
        else if (lDesc.includes('advertising') || lDesc.includes('cost per click')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('placement')) addToSummary('Inbound shipping fees', total);
        else addToSummary('Other', total);
      }
      else if (lType === 'fba transaction fees' || lType === 'fba inventory fee') {
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('awd')) addToSummary('AWD fees', total);
        else if (lDesc.includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (lDesc.includes('return')) addToSummary('Return fees', total);
        else if (lDesc.includes('inbound') || lDesc.includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (lType === 'transfer') addToSummary('Transfer', total);
      else if (lType === 'shipping services') addToSummary('FBM shipping fees', total);
      else {
        // Deep diving into anything else falling through
        if (lDesc.includes('storage')) addToSummary('FBA storage fees', total);
        else if (lDesc.includes('advertising')) addToSummary('Advertising fees', total);
        else if (lDesc.includes('referral') || lDesc.includes('selling fee')) addToSummary('Selling fees', total);
        else if (lDesc.includes('fulfillment')) addToSummary('FBA fees', total);
        else addToSummary('Other', total);
      }
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const pk = getStandardKey(r.date);
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const cogsMap: Record<string, { orderCogs: number, refundCogs: number, adjustmentCogs: number }> = {};

    const normalize = (s: string) => s?.trim().toUpperCase() || '';
    const normalizedSkuData: SkuDataMap = {};
    Object.keys(skuData).forEach(k => { normalizedSkuData[normalize(k)] = skuData[k]; });

    records.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;
      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!cogsMap[pk]) cogsMap[pk] = { orderCogs: 0, refundCogs: 0, adjustmentCogs: 0 };
      const normalizedSku = normalize(r.sku);
      const unitCost = normalizedSkuData[normalizedSku]?.cost || 0;

      if (r.type === 'Order') cogsMap[pk].orderCogs += (r.quantity * unitCost);
      else if (r.type === 'Refund') cogsMap[pk].refundCogs += (r.quantity * unitCost);
      else if (r.type === 'Adjustment' || r.category === 'FBA reimbursement') cogsMap[pk].adjustmentCogs += (r.quantity * unitCost);
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
      const parse = (s: string) => new Date(2000 + parseInt(s.slice(3)), months[s.slice(0, 3)]).getTime();
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, cogsMap };
  }, [records, skuData]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;
    if (!sku) {
      if (!type) return p[cat]._total;
      let typeTotal = 0;
      Object.keys(p[cat]).forEach(sKey => {
        if (sKey === '_total') return;
        if (p[cat][sKey][type]) typeTotal += p[cat][sKey][type];
      });
      return typeTotal;
    }
    if (!p[cat][sku]) return 0;
    if (!type) return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    return p[cat][sku][type] || 0;
  };

  const sortedSkus = useMemo(() => {
    if (!sortMonth) return pivotData.skus;
    return [...pivotData.skus].sort((a, b) => {
      const valA = getAmt(sortMonth, 'Revenue', a);
      const valB = getAmt(sortMonth, 'Revenue', b);
      return valB - valA;
    });
  }, [pivotData.skus, sortMonth, pivotData.amountMap]);

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  const sortedFeeList = useMemo(() => {
    if (!feeSortMonth) return FEE_LIST;
    return [...FEE_LIST].sort((a, b) => {
      const valA = Math.abs(getAmt(feeSortMonth, a));
      const valB = Math.abs(getAmt(feeSortMonth, b));
      return valB - valA;
    });
  }, [feeSortMonth, pivotData.amountMap]);

  const handleExport = () => {
    if (records.length === 0) return;

    // 1. REVENUE SHEET
    const revHeader = ["Product Description", ...pivotData.periods];
    const revRows = sortedSkus.map(sku => [
      skuData[sku]?.name || sku,
      ...pivotData.periods.map(p => getAmt(p, 'Revenue', sku))
    ]);
    const revTotals = ["Total Revenue", ...pivotData.periods.map(p => getAmt(p, 'Revenue'))];
    const revSheetData = [revHeader, ...revRows, revTotals];

    // 2. FEES SHEET
    const feeHeader = ["Fee Category", ...pivotData.periods];
    const feeRows = sortedFeeList.map(fee => [
      fee,
      ...pivotData.periods.map(p => {
        const val = getAmt(p, fee as AmazonCategory);
        const isReimbursement = fee === 'FBA reimbursement';
        // In the UI we show absolute values for costs. For Excel, we'll keep costs as positive 
        // and reimbursements as negative for clarity in the sums.
        return isReimbursement && val > 0 ? -val : Math.abs(val);
      })
    ]);
    const feeTotals = ["Total Fees", ...pivotData.periods.map(p => 
      Math.abs(FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0))
    )];
    const feeSheetData = [feeHeader, ...feeRows, feeTotals];

    // 3. PROFITABILITY SHEET
    const profHeader = ["Performance Metric", ...pivotData.periods];
    const metrics = [
      { name: "Total Revenue (Net)", calc: (p: string) => getAmt(p, 'Revenue') },
      { name: "Total Amazon Fees", calc: (p: string) => -Math.abs(FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0)) },
      { name: "Net Amazon Transfer", calc: (p: string) => Math.abs(getAmt(p, 'Transfer')) },
      { name: "Est. Cost of Goods (Orders)", calc: (p: string) => -(pivotData.cogsMap[p]?.orderCogs || 0) },
      { name: "COGS Adjustments (Lost/Reimb)", calc: (p: string) => -(pivotData.cogsMap[p]?.adjustmentCogs || 0) },
      { name: "COGS Reversal (Returns)", calc: (p: string) => Math.abs(pivotData.cogsMap[p]?.refundCogs || 0) },
      { name: "Gross Profit (Cash Basis)", calc: (p: string) => {
          const transfer = Math.abs(getAmt(p, 'Transfer'));
          const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
          const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
          const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
          return transfer - orderCogs - adjCogs + returnCogs;
      }},
      { name: "Gross Margin %", calc: (p: string) => {
          const revenue = getAmt(p, 'Revenue');
          const transfer = Math.abs(getAmt(p, 'Transfer'));
          const orderCogs = pivotData.cogsMap[p]?.orderCogs || 0;
          const adjCogs = pivotData.cogsMap[p]?.adjustmentCogs || 0;
          const returnCogs = Math.abs(pivotData.cogsMap[p]?.refundCogs || 0);
          const profit = transfer - orderCogs - adjCogs + returnCogs;
          return revenue !== 0 ? ((profit / revenue) * 100).toFixed(2) + "%" : "0.00%";
      }}
    ];
    const profRows = metrics.map(m => [m.name, ...pivotData.periods.map(p => m.calc(p))]);
    const profSheetData = [profHeader, ...profRows];

    // GENERATE WORKBOOK
    const wb = XLSX.utils.book_new();
    const s1 = XLSX.utils.aoa_to_sheet(revSheetData);
    const s2 = XLSX.utils.aoa_to_sheet(feeSheetData);
    const s3 = XLSX.utils.aoa_to_sheet(profSheetData);

    XLSX.utils.book_append_sheet(wb, s1, "Revenue & Sales");
    XLSX.utils.book_append_sheet(wb, s2, "Amazon Fees");
    XLSX.utils.book_append_sheet(wb, s3, "Profitability & COGS");

    XLSX.writeFile(wb, `${companyName}_Amazon_Analysis_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div className="flex flex-col">
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <div className="flex items-center gap-2 mt-2">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Aggregated Amazon Reconciliation</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
          <button 
            onClick={handleExport}
            disabled={records.length === 0 || isSyncing}
            className={`bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${records.length === 0 || isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-emerald-500 cursor-pointer active:scale-95'}`}
          >
            Export Report (.xlsx)
          </button>
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" disabled={isSyncing} />
          <label htmlFor="amz-upload" className={`bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center ${isSyncing ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 cursor-pointer active:scale-95'}`}>
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
              {sortMonth && (
                <button onClick={() => setSortMonth(null)} className="text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900 transition-colors">Reset Sort</button>
              )}
            </div>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => (
