import React, { useState, useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification, JournalEntryLine } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  closedPeriods: string[];
  onClosePeriod: (periodKey: string, closingEntry: JournalEntry) => void;
}

const getStandardKey = (dateStr: string) => {
  if (!dateStr) return "INVALID";
  const match = dateStr.match(/([a-zA-Z]+)\s+\d{1,2},\s+(\d{4})/);
  if (match) {
    const month = match[1];
    const year = match[2].slice(-2);
    const formattedMonth = month.charAt(0).toUpperCase() + month.slice(1).toLowerCase().substring(0, 3);
    return `${formattedMonth}${year}`;
  }
  const isoMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    const d = new Date(dateStr);
    const month = d.toLocaleString('en-US', { month: 'short' });
    const year = String(d.getFullYear()).slice(-2);
    return `${month}${year}`;
  }
  return "INVALID";
};

const ClosingManager: React.FC<Props> = ({ transactions, accounts, closedPeriods, onClosePeriod }) => {
  const [selectedPeriod, setSelectedPeriod] = useState<string>('');
  const [equityAllocations, setEquityAllocations] = useState<Record<string, number>>({});

  const availablePeriods = useMemo(() => {
    const periods = new Set<string>();
    transactions.forEach(t => {
      const key = getStandardKey(t.date);
      if (key !== "INVALID" && !closedPeriods.includes(key)) periods.add(key);
    });
    return Array.from(periods).sort();
  }, [transactions, closedPeriods]);

  const periodSummary = useMemo(() => {
    if (!selectedPeriod) return null;
    let netIncome = 0;
    const accountBalances: Record<string, number> = {};

    transactions.forEach(t => {
      if (getStandardKey(t.date) === selectedPeriod && !t.isClosingEntry) {
        t.lines.forEach(l => {
          const acc = accounts.find(a => a.id === l.accountId);
          if (acc) {
            const amount = acc.naturalBalance === NaturalBalance.DEBIT ? (l.debit - l.credit) : (l.credit - l.debit);
            accountBalances[acc.id] = (accountBalances[acc.id] || 0) + amount;
            if (acc.financialStatement === FinancialStatement.INCOME_STATEMENT) {
               if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
                  netIncome += amount;
               } else {
                  netIncome -= amount;
               }
            }
          }
        });
      }
    });

    return { netIncome, accountBalances };
  }, [selectedPeriod, transactions, accounts]);

  const equityAccounts = accounts.filter(a => a.classification === AccountClassification.EQUITY && !a.isArchived);

  const handleClose = () => {
    if (!selectedPeriod || !periodSummary) return;

    const totalAllocated = Object.values(equityAllocations).reduce((s, v) => s + v, 0);
    if (Math.abs(totalAllocated - periodSummary.netIncome) > 0.01) {
      alert(`Equity allocations ($${totalAllocated.toFixed(2)}) must equal Net Income ($${periodSummary.netIncome.toFixed(2)})!`);
      return;
    }

    if (!window.confirm(`Close books for ${selectedPeriod}? All revenue/expense accounts will be zeroed and historical entries will be locked.`)) return;

    const closingLines: JournalEntryLine[] = [];

    // Zero out IS accounts
    accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT).forEach(acc => {
      const balance = periodSummary.accountBalances[acc.id] || 0;
      if (Math.abs(balance) < 0.01) return;

      if (acc.naturalBalance === NaturalBalance.DEBIT) {
        // To zero a debit balance, credit it
        closingLines.push({ id: Math.random().toString(), accountId: acc.id, debit: 0, credit: balance, description: `Closing ${selectedPeriod}` });
      } else {
        // To zero a credit balance, debit it
        closingLines.push({ id: Math.random().toString(), accountId: acc.id, debit: balance, credit: 0, description: `Closing ${selectedPeriod}` });
      }
    });

    // Allocate to Equity
    Object.entries(equityAllocations).forEach(([accId, amount]) => {
      if (Math.abs(amount) < 0.01) return;
      const acc = accounts.find(a => a.id === accId);
      if (!acc) return;

      if (acc.naturalBalance === NaturalBalance.CREDIT) {
        if (amount > 0) closingLines.push({ id: Math.random().toString(), accountId: accId, debit: 0, credit: amount, description: `Profit Allocation ${selectedPeriod}` });
        else closingLines.push({ id: Math.random().toString(), accountId: accId, debit: Math.abs(amount), credit: 0, description: `Loss Allocation ${selectedPeriod}` });
      } else {
        if (amount > 0) closingLines.push({ id: Math.random().toString(), accountId: accId, debit: amount, credit: 0, description: `Profit Allocation ${selectedPeriod}` });
        else closingLines.push({ id: Math.random().toString(), accountId: accId, debit: 0, credit: Math.abs(amount), description: `Loss Allocation ${selectedPeriod}` });
      }
    });

    const maxId = transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0;
    const closingEntry: JournalEntry = {
      id: maxId + 1,
      date: new Date().toISOString().split('T')[0], // User might want last day of period, but this works
      method: 'CLOSE',
      isClosingEntry: true,
      lines: closingLines
    };

    onClosePeriod(selectedPeriod, closingEntry);
    setSelectedPeriod('');
    setEquityAllocations({});
  };

  return (
    <div className="space-y-10 max-w-4xl mx-auto">
      <div className="border-b-2 border-slate-900 pb-6">
        <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Close the Books</h2>
        <p className="text-sm font-bold text-slate-400 mt-2 italic uppercase">Zero out performance accounts and lock historical periods.</p>
      </div>

      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Select Period to Close</label>
          <select 
            value={selectedPeriod} 
            onChange={(e) => setSelectedPeriod(e.target.value)}
            className="w-full border rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-emerald-500 font-bold bg-slate-50"
          >
            <option value="">Choose Period...</option>
            {availablePeriods.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>

        {selectedPeriod && periodSummary && (
          <div className="animate-in fade-in slide-in-from-top-4 duration-300 space-y-8">
            <div className="bg-slate-900 text-white p-6 rounded-2xl flex justify-between items-center">
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Net Income for {selectedPeriod}</p>
                <p className="text-3xl font-black font-mono mt-1">${periodSummary.netIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
              </div>
              <div className="text-right">
                <span className={`text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest ${periodSummary.netIncome >= 0 ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
                  {periodSummary.netIncome >= 0 ? 'Profit' : 'Loss'}
                </span>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="text-sm font-black uppercase tracking-widest text-slate-700">Equity Allocation</h3>
              <div className="grid grid-cols-1 gap-4">
                {equityAccounts.map(acc => (
                  <div key={acc.id} className="flex items-center gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <span className="flex-1 font-bold text-slate-700">{acc.name}</span>
                    <input 
                      type="number"
                      step="0.01"
                      placeholder="Amount"
                      value={equityAllocations[acc.id] || ''}
                      onChange={(e) => setEquityAllocations({...equityAllocations, [acc.id]: parseFloat(e.target.value) || 0})}
                      className="w-32 border rounded-lg px-3 py-2 text-right font-mono text-sm"
                    />
                  </div>
                ))}
              </div>
            </div>

            <div className="pt-6 border-t flex justify-between items-center">
              <div className="text-xs font-bold">
                <span className="text-slate-400 uppercase tracking-widest mr-2">Total Allocated:</span>
                <span className={`font-mono ${Math.abs((Object.values(equityAllocations).reduce((s,v) => s + v, 0)) - periodSummary.netIncome) < 0.01 ? 'text-emerald-600' : 'text-red-500'}`}>
                  ${Object.values(equityAllocations).reduce((s,v) => s + v, 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </span>
              </div>
              <button 
                onClick={handleClose}
                className="bg-emerald-600 text-white px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-500 transition-all"
              >
                Execute Closing Entry
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ClosingManager;

import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  companyName: string;
}

const IncomeStatement: React.FC<Props> = ({ transactions = [], accounts = [], companyName }) => {
  const sortedPeriods = useMemo(() => {
    const periods = new Set<string>();
    transactions.forEach(tx => {
      const date = new Date(tx.date);
      if (!isNaN(date.getTime())) {
        periods.add(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`);
      }
    });
    return Array.from(periods).sort((a, b) => a.localeCompare(b));
  }, [transactions]);

  const getMonthlyActivity = (accountId: string, period: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let activity = 0;
    const [year, month] = period.split('-').map(Number);

    // EXCLUDE CLOSING ENTRIES
    transactions.filter(tx => !tx.isClosingEntry).forEach(tx => {
      const txDate = new Date(tx.date);
      if (txDate.getFullYear() === year && (txDate.getMonth() + 1) === month) {
        tx.lines.forEach(l => {
          if (l.accountId === accountId) {
            if (account.naturalBalance === NaturalBalance.DEBIT) activity += (l.debit - l.credit);
            else activity += (l.credit - l.debit);
          }
        });
      }
    });
    return activity;
  };

  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);

  const calculateMonthlyNet = (period: string) => {
    let rev = 0;
    let exp = 0;
    isAccounts.forEach(acc => {
      const act = getMonthlyActivity(acc.id, period);
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
        rev += act;
      } else {
        exp += act;
      }
    });
    return rev - exp;
  };

  if (sortedPeriods.length === 0) {
    return (
      <div className="p-20 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed border-slate-200">
        <p className="text-lg font-bold mb-2 text-slate-700 tracking-tight">Report Ready</p>
        <p className="text-sm">Record transactions to see monthly revenue and expense performance columns.</p>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-900">{companyName}</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Income Statement (Closed Entries Excluded)</p>
      </div>

      <div className="overflow-x-auto border rounded-2xl shadow-xl bg-white">
        <table className="w-full border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-900 text-white">
              <th className="p-4 text-left w-72 border-r border-slate-800 text-[10px] font-black uppercase tracking-widest">Income Category</th>
              {sortedPeriods.map(p => (
                <th key={p} className="p-4 text-right text-[10px] uppercase font-black tracking-widest border-r border-slate-800">
                  {new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {[
              { title: "Revenue", type: AccountClassification.REVENUE, color: "text-emerald-700" },
              { title: "Cost of Goods Sold", type: AccountClassification.COGS, color: "text-amber-700" },
              { title: "Operating Expenses", type: AccountClassification.OPERATING_EXPENSE, color: "text-slate-700" },
              { title: "Other Income / (Exp)", type: AccountClassification.OTHER_INCOME_EXPENSE, color: "text-indigo-700" }
            ].map(section => (
              <React.Fragment key={section.title}>
                <tr className="bg-slate-50 border-t border-slate-100">
                  <td className="p-2.5 font-black text-slate-900 text-[9px] tracking-widest uppercase">{section.title}</td>
                  {sortedPeriods.map(p => <td key={p} className="p-2 border-r border-slate-100"></td>)}
                </tr>
                {isAccounts.filter(a => a.classification === section.type).map(acc => (
                  <tr key={acc.id} className="border-b hover:bg-slate-50/50 transition-colors">
                    <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                    {sortedPeriods.map(p => (
                      <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                        {getMonthlyActivity(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                ))}
              </React.Fragment>
            ))}

            <tr className="h-10"></tr>
            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900 shadow-inner">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">NET PERIOD INCOME</td>
              {sortedPeriods.map(p => {
                const net = calculateMonthlyNet(p);
                return (
                  <td key={p} className={`p-4 text-right font-mono text-sm border-r border-slate-700 ${net < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                    ${net.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                );
              })}
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default IncomeStatement;

import React, { useState, useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';
import { STATEMENTS, STATEMENT_CLASSIFICATION_MAP } from '../constants';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onUpdateAccount: (id: string, updatedFields: Partial<Account>) => void;
  onDeleteAccount: (id: string) => void;
  onDeleteTransaction: (id: number) => void;
}

type LedgerSubTab = FinancialStatement;

const Ledgers: React.FC<Props> = ({ transactions, accounts = [], onUpdateAccount, onDeleteAccount, onDeleteTransaction }) => {
  const [activeSubTab, setActiveSubTab] = useState<LedgerSubTab>(FinancialStatement.BALANCE_SHEET);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState<Account | null>(null);

  const categorizedAccounts = useMemo(() => {
    const filtered = accounts.filter(acc => acc.financialStatement === activeSubTab);

    const classificationOrder: Record<string, number> = {
      [AccountClassification.CURRENT_ASSET]: 1,
      [AccountClassification.LONG_TERM_ASSET]: 2,
      [AccountClassification.CURRENT_LIABILITY]: 3,
      [AccountClassification.LONG_TERM_LIABILITY]: 4,
      [AccountClassification.EQUITY]: 5,
      [AccountClassification.REVENUE]: 6,
      [AccountClassification.COGS]: 7,
      [AccountClassification.OPERATING_EXPENSE]: 8,
      [AccountClassification.OTHER_INCOME_EXPENSE]: 9,
      [AccountClassification.CLEARING_ACCOUNT]: 10,
      [AccountClassification.TEMPORARY_ACCOUNT]: 11,
    };

    const grouped: Record<string, Account[]> = {};
    filtered.forEach(acc => {
      if (!grouped[acc.classification]) grouped[acc.classification] = [];
      grouped[acc.classification].push(acc);
    });

    return Object.entries(grouped).sort((a, b) => 
      (classificationOrder[a[0]] || 99) - (classificationOrder[b[0]] || 99)
    );
  }, [accounts, activeSubTab]);

  const startEditing = (account: Account) => {
    setEditingId(account.id);
    setEditDraft({ ...account });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const saveEdit = () => {
    if (editingId && editDraft) {
      onUpdateAccount(editingId, {
        name: editDraft.name.trim(),
        classification: editDraft.classification,
        naturalBalance: editDraft.naturalBalance,
        financialStatement: editDraft.financialStatement,
        startingBalance: Number(editDraft.startingBalance) || 0
      });
      cancelEditing();
    }
  };

  const updateDraft = (field: keyof Account, value: any) => {
    if (!editDraft) return;
    const newDraft = { ...editDraft, [field]: value };
    if (field === 'financialStatement') {
      const validClassifications = STATEMENT_CLASSIFICATION_MAP[value as FinancialStatement];
      if (!validClassifications.includes(newDraft.classification)) {
        newDraft.classification = validClassifications[0];
      }
    }
    setEditDraft(newDraft);
  };

  const handleDeleteAccount = (account: Account) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === account.id));
    const confirmMsg = hasData 
      ? `This account has transaction history. It will be "Archived" and hidden from new entry pickers, but preserved in ledgers. Proceed?`
      : `Are you sure you want to permanently delete the account "${account.name}"?`;

    if (window.confirm(confirmMsg)) {
      onDeleteAccount(account.id);
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b pb-6">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Account Ledgers</h2>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200 shadow-sm">
          {STATEMENTS.map(statement => (
            <button
              key={statement}
              onClick={() => {
                setActiveSubTab(statement);
                cancelEditing();
              }}
              className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-tighter transition-all ${
                activeSubTab === statement 
                  ? 'bg-white text-emerald-600 shadow-sm border border-slate-200' 
                  : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {statement}
            </button>
          ))}
        </div>
      </div>

      {categorizedAccounts.length === 0 ? (
        <div className="py-20 text-center bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
          <p className="text-slate-400 font-bold italic">No accounts configured for this category yet.</p>
        </div>
