export default TransactionRecorder;

import React, { useState, useMemo } from 'react';
import { JournalEntry, Account, JournalEntryLine } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onDelete: (id: number) => void;
  onUpdate: (entry: JournalEntry) => void;
  closedPeriods: string[];
}

const getStandardKey = (dateStr: string) => {
  if (!dateStr) return "INVALID";
  const match = dateStr.match(/([a-zA-Z]+)\s+\d{1,2},\s+(\d{4})/);
  if (match) {
    const month = match[1];
    const year = match[2].slice(-2);
    const formattedMonth = month.charAt(0).toUpperCase() + month.slice(1).toLowerCase().substring(0, 3);
    return `${formattedMonth}${year}`;
  }
  const isoMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    const d = new Date(dateStr);
    const month = d.toLocaleString('en-US', { month: 'short' });
    const year = String(d.getFullYear()).slice(-2);
    return `${month}${year}`;
  }
  return "INVALID";
};

type SortField = 'id' | 'date';
type SortDirection = 'asc' | 'desc';

const GeneralJournal: React.FC<Props> = ({ transactions, accounts, onDelete, onUpdate, closedPeriods }) => {
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editDraft, setEditDraft] = useState<JournalEntry | null>(null);

  const [sortField, setSortField] = useState<SortField>('id');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  const accountMap = new Map<string, Account>(accounts.map(a => [a.id, a]));
  const activeAccounts = accounts.filter(a => !a.isArchived).sort((a,b) => a.name.localeCompare(b.name));

  const sortedTransactions = useMemo(() => {
    return [...transactions].sort((a, b) => {
      let comparison = 0;
      if (sortField === 'id') {
        comparison = a.id - b.id;
      } else {
        comparison = new Date(a.date).getTime() - new Date(b.date).getTime();
      }
      return sortDirection === 'asc' ? comparison : -comparison;
    });
  }, [transactions, sortField, sortDirection]);

  const startEditing = (entry: JournalEntry) => {
    if (entry.isClosingEntry) {
      alert("Closing entries cannot be manually edited.");
      return;
    }
    if (closedPeriods.includes(getStandardKey(entry.date))) {
      alert("Cannot edit transactions in a closed period.");
      return;
    }
    setEditingId(entry.id);
    setEditDraft({
      ...entry,
      lines: entry.lines.map(line => ({ ...line }))
    });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const updateDraftLine = (lineId: string, field: keyof JournalEntryLine, value: any) => {
    if (!editDraft) return;
    const updatedLines = editDraft.lines.map(l => l.id === lineId ? { ...l, [field]: value } : l);
    setEditDraft({ ...editDraft, lines: updatedLines });
  };

  const handleSave = () => {
    if (!editDraft) return;

    const totalDr = editDraft.lines.reduce((sum, l) => sum + (Number(l.debit) || 0), 0);
    const totalCr = editDraft.lines.reduce((sum, l) => sum + (Number(l.credit) || 0), 0);

    if (Math.abs(totalDr - totalCr) > 0.01) {
      alert(`Entry must be balanced! Difference: $${Math.abs(totalDr - totalCr).toFixed(2)}`);
      return;
    }

    onUpdate(editDraft);
    cancelEditing();
  };

  const toggleDirection = () => {
    setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc');
  };

  return (
    <div>
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8 border-b pb-6">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">General Journal</h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
            {transactions.length} Total Chronological Entries
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3 bg-slate-50 p-2 rounded-2xl border border-slate-200">
          <div className="flex items-center gap-2 px-3">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sort By:</span>
            <div className="flex bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm">
              <button 
                onClick={() => setSortField('id')}
                className={`px-4 py-1.5 text-[10px] font-black uppercase transition-all ${sortField === 'id' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-600'}`}
              >
                ID
              </button>
              <button 
                onClick={() => setSortField('date')}
                className={`px-4 py-1.5 text-[10px] font-black uppercase transition-all ${sortField === 'date' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-600'}`}
              >
                Date
              </button>
            </div>
          </div>

          <button 
            onClick={toggleDirection}
            className="flex items-center gap-2 px-4 py-1.5 bg-white border border-slate-200 rounded-xl shadow-sm hover:border-slate-300 transition-all text-slate-600 font-black text-[10px] uppercase tracking-widest"
          >
            {sortDirection === 'asc' ? 'Ascending' : 'Descending'}
            <svg className={`w-3 h-3 transition-transform ${sortDirection === 'desc' ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 15l7-7 7 7"></path>
            </svg>
          </button>
        </div>
      </div>

      <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white overflow-hidden">
        <table className="w-full text-sm border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b">
              <th className="p-4 text-left font-black text-slate-400 uppercase tracking-[0.2em] text-[9px] w-16">ID</th>
              <th className="p-4 text-left font-black text-slate-400 uppercase tracking-[0.2em] text-[9px] w-32">Date</th>
              <th className="p-4 text-left font-black text-slate-400 uppercase tracking-[0.2em] text-[9px]">Account</th>
              <th className="p-4 text-right font-black text-slate-400 uppercase tracking-[0.2em] text-[9px] w-32">Debit</th>
              <th className="p-4 text-right font-black text-slate-400 uppercase tracking-[0.2em] text-[9px] w-32">Credit</th>
              <th className="p-4 text-left font-black text-slate-400 uppercase tracking-[0.2em] text-[9px]">Memo / Ref</th>
              <th className="p-4 w-24"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedTransactions.length === 0 && (
              <tr>
                <td colSpan={7} className="p-20 text-center text-slate-400 italic font-medium">No recorded journal entries found.</td>
              </tr>
            )}
            {sortedTransactions.map((entry) => {
              const isEditing = editingId === entry.id;
              const displayEntry = isEditing && editDraft ? editDraft : entry;
              const isLocked = closedPeriods.includes(getStandardKey(entry.date)) || entry.isClosingEntry;

              return (
                <React.Fragment key={entry.id}>
                  {displayEntry.lines.map((line, idx) => {
                    const account = accountMap.get(line.accountId);
                    return (
                      <tr key={line.id} className={`group ${idx === 0 ? 'bg-slate-50/40' : 'bg-white'} ${isEditing ? 'bg-emerald-50/30' : 'hover:bg-emerald-50/20'} transition-colors ${entry.isClosingEntry ? 'border-l-4 border-l-indigo-600' : ''}`}>
                        <td className="p-4 align-top font-mono text-xs text-slate-400 font-bold">
                          {idx === 0 ? entry.id : ''}
                        </td>
                        <td className="p-4 align-top text-slate-600 font-bold whitespace-nowrap text-xs">
                          {idx === 0 ? (
                            isEditing ? (
                              <input 
                                type="date" 
                                value={displayEntry.date} 
                                onChange={(e) => setEditDraft({...editDraft!, date: e.target.value})}
                                className="border rounded-lg px-2 py-1 text-xs w-full bg-white outline-none focus:ring-2 focus:ring-emerald-500/20 border-slate-200"
                              />
                            ) : entry.date
                          ) : ''}
                        </td>
                        <td className={`p-4 font-black text-xs ${line.credit > 0 ? 'pl-12 text-slate-600' : 'text-slate-900'}`}>
                          {isEditing ? (
                            <select
                              value={line.accountId}
                              onChange={(e) => updateDraftLine(line.id, 'accountId', e.target.value)}
