                              value={line.credit || ''} 
                              onChange={(e) => updateDraftLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                              className="border rounded-lg px-2 py-1 text-xs w-full text-right bg-white outline-none focus:ring-2 focus:ring-emerald-500/20 border-slate-200"
                            />
                          ) : (
                            line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '-'
                          )}
                        </td>
                        <td className="p-4 text-slate-500 italic text-xs max-w-xs truncate font-medium">
                          {isEditing ? (
                            <input 
                              type="text" 
                              value={line.description} 
                              onChange={(e) => updateDraftLine(line.id, 'description', e.target.value)}
                              className="border rounded-lg px-2 py-1 text-xs w-full bg-white outline-none focus:ring-2 focus:ring-emerald-500/20 border-slate-200"
                              placeholder="Memo..."
                            />
                          ) : (
                            line.description
                          )}
                          {idx === 0 && entry.method && !isEditing && (
                            <span className={`not-italic text-[9px] px-2 py-0.5 rounded-full ml-2 font-black uppercase tracking-widest border ${entry.isClosingEntry ? 'bg-indigo-600 text-white border-indigo-700' : 'bg-slate-100 text-slate-500 border-slate-200'}`}>
                              {entry.isClosingEntry ? 'CLOSING' : entry.method}
                            </span>
                          )}
                        </td>
                        <td className="p-4 text-right">
                          {idx === 0 && (
                            <div className="flex justify-end gap-2">
                              {isEditing ? (
                                <>
                                  <button onClick={handleSave} className="text-emerald-600 hover:text-emerald-700 transition-all font-black text-[10px] uppercase tracking-widest bg-emerald-50 px-3 py-1.5 rounded-xl border border-emerald-100 shadow-sm">Save</button>
                                  <button onClick={cancelEditing} className="text-slate-400 hover:text-slate-600 transition-all font-black text-[10px] uppercase tracking-widest px-3 py-1.5">Cancel</button>
                                </>
                              ) : !isLocked ? (
                                <>
                                  <button 
                                    onClick={() => startEditing(entry)}
                                    className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-slate-600 transition-all p-1.5 rounded-lg hover:bg-slate-100"
                                    title="Edit Transaction"
                                  >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                                  </button>
