const safeStringify = (obj: any) => {
  const cache = new WeakSet();
  return JSON.stringify(obj, (key, value) => {
    if (typeof value === 'object' && value !== null) {
      if (cache.has(value)) return;
      cache.add(value);
    }
    return value;
  });
};

/**
 * Timezone-independent Period Key generator.
 * Converts "2025-01-31" or "Dec 1, 2025" to "Jan25".
 */
const getStandardKey = (dateStr: string) => {
  if (!dateStr) return "INVALID";

  // Format: "Dec 1, 2025" (Amazon / Human readable)
  const match = dateStr.match(/([a-zA-Z]+)\s+\d{1,2},\s+(\d{4})/);
  if (match) {
    const month = match[1].charAt(0).toUpperCase() + match[1].slice(1).toLowerCase().substring(0, 3);
    const year = match[2].slice(-2);
    return `${month}${year}`;
  }

  // Format: "2025-01-31" (ISO / Input Date)
  const isoMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    const year = isoMatch[1].slice(-2);
    const monthIdx = parseInt(isoMatch[2]) - 1;
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${months[monthIdx]}${year}`;
  }

  return "INVALID";
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([{ name: 'JE', accountId: '' }]);
  const [companyName, setCompanyName] = useState('Vista Shore Products, LLC');
  const [amazonRecords, setAmazonRecords] = useState<AmazonAnalysisRecord[]>([]);
  const [skuData, setSkuData] = useState<SkuDataMap>({});
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  const isUpdatingRef = useRef(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
        if (parsed.paymentMethods) setPaymentMethods(parsed.paymentMethods);
        if (parsed.companyName) setCompanyName(parsed.companyName);
        if (parsed.amazonRecords) setAmazonRecords(parsed.amazonRecords);
        if (parsed.skuData) setSkuData(parsed.skuData);
      } catch (e) {}
    }

    const userDocRef = doc(db, 'users', user.uid);
    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      if (isUpdatingRef.current) return;
      if (docSnap.metadata.hasPendingWrites) return;

      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        if (data.paymentMethods) setPaymentMethods(data.paymentMethods);
        if (data.companyName) setCompanyName(data.companyName);
        if (data.amazonRecords) setAmazonRecords(data.amazonRecords);
        if (data.skuData) setSkuData(data.skuData);

        localStorage.setItem(`vista_data_${user.uid}`, safeStringify(data));
      }
    }, (error) => {
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = useCallback(async (
    newAccs: Account[], 
    newTxs: JournalEntry[], 
    newPeriods: string[], 
    newMethods: PaymentMethod[], 
    newName: string,
    newAmazon: AmazonAnalysisRecord[],
    newSku: SkuDataMap,
    lockTime: number = 1500 
  ) => {
    if (!user) return;
    isUpdatingRef.current = true;
    setIsSyncing(true);

    const packet = {
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods,
      paymentMethods: newMethods,
      companyName: newName,
      amazonRecords: newAmazon,
      skuData: newSku
    };

    localStorage.setItem(`vista_data_${user.uid}`, safeStringify(packet));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        ...packet,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      setCloudError("Failed to save to cloud.");
    } finally {
      setTimeout(() => { 
        isUpdatingRef.current = false; 
        setIsSyncing(false);
      }, lockTime);
    }
  }, [user]);

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteTransaction = useCallback((id: number) => {
    setTransactions(prev => {
      const tx = prev.find(t => t.id === id);
      if (!tx) return prev;

      const periodKey = getStandardKey(tx.date);
      if (closedPeriods.includes(periodKey)) {
        alert(`Cannot delete Transaction #${id}. The period ${periodKey} is closed.`);
        return prev;
      }

      if (tx.isClosingEntry) {
        alert(`Cannot delete Transaction #${id}. Closing entries must be removed via the Closing Manager or Data Manager.`);
        return prev;
      }

      if (window.confirm(`Permanently delete Transaction #${id}?`)) {
        const updated = prev.filter(t => t.id !== id);
        saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
        return updated;
      }
      return prev;
    });
  }, [accounts, closedPeriods, paymentMethods, companyName, amazonRecords, skuData, saveToFirestore]);

  const onClosePeriod = (periodKey: string, closingEntry: JournalEntry) => {
    if (closedPeriods.includes(periodKey)) {
      alert(`Period ${periodKey} is already closed.`);
      return;
    }
    const newTxs = [...transactions, closingEntry];
    const newPeriods = [...closedPeriods, periodKey];
    setTransactions(newTxs);
    setClosedPeriods(newPeriods);
    saveToFirestore(accounts, newTxs, newPeriods, paymentMethods, companyName, amazonRecords, skuData);
    alert(`Success! The books for ${periodKey} have been closed.`);
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const updateAmazonRecords = (recs: AmazonAnalysisRecord[]) => {
    setAmazonRecords(recs);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, recs, skuData);
  };

  const removeAmazonPeriod = (periodKey: string) => {
    const updated = amazonRecords.filter(r => getStandardKey(r.date) !== periodKey);
    setAmazonRecords(updated);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, updated, skuData);
  };

  const updateSkuData = (data: SkuDataMap) => {
    setSkuData(data);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, data);
  };

  const updateCompanyName = (name: string) => {
    setCompanyName(name);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, name, amazonRecords, skuData);
  };

  const handleImport = (newTxs: JournalEntry[], newAccs: Account[]) => {
    const updatedAccs = [...accounts];
    newAccs.forEach(na => {
      if (!updatedAccs.find(a => a.name.toLowerCase() === na.name.toLowerCase())) {
        updatedAccs.push(na);
      }
    });
    const updatedTxs = [...transactions, ...newTxs];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const handleReset = (full: boolean) => {
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      setAmazonRecords([]);
      setSkuData({});
      saveToFirestore(INITIAL_ACCOUNTS, [], [], paymentMethods, companyName, [], {});
    } else {
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], [], paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const addPaymentMethod = (name: string, accountId: string) => {
    const updated = [...paymentMethods, { name, accountId }];
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const removePaymentMethod = (name: string) => {
    const updated = paymentMethods.filter(m => m.name !== name);
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Amazon Analysis', 'COGS Manager', 'Closing Manager', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}
      {isSyncing && (
        <div className="fixed bottom-6 right-6 z-[999] bg-slate-900 text-white px-5 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4">
          <div className="w-2 h-2 rounded-full animate-ping bg-emerald-500"></div>
          <span className="text-[10px] font-black uppercase tracking-widest">Processing Data Update...</span>
        </div>
      )}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-50 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <div className="flex flex-col">
            <h1 className="text-xl font-bold tracking-tighter text-white uppercase">VISTA SHORE</h1>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors text-white">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} paymentMethods={paymentMethods} companyName={companyName} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} paymentMethods={paymentMethods} closedPeriods={closedPeriods} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} closedPeriods={closedPeriods} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Amazon Analysis' && <AmazonAnalysis skuData={skuData} records={amazonRecords} onUpdateRecords={updateAmazonRecords} onRemovePeriod={removeAmazonPeriod} companyName={companyName} isSyncing={isSyncing} />}
            {activeTab === 'COGS Manager' && <CogsManager skuData={skuData} onUpdateSkuData={updateSkuData} />}
            {activeTab === 'Closing Manager' && <ClosingManager transactions={transactions} accounts={accounts} closedPeriods={closedPeriods} onClosePeriod={onClosePeriod} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={handleImport} onReset={handleReset} paymentMethods={paymentMethods} onAddMethod={addPaymentMethod} onRemoveMethod={removePaymentMethod} companyName={companyName} onUpdateCompanyName={updateCompanyName} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { JournalEntry, Account, JournalEntryLine } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onDelete: (id: number) => void;
  onUpdate: (entry: JournalEntry) => void;
  closedPeriods: string[];
}

const getStandardKey = (dateStr: string) => {
  if (!dateStr) return "INVALID";

  const match = dateStr.match(/([a-zA-Z]+)\s+\d{1,2},\s+(\d{4})/);
  if (match) {
    const month = match[1].charAt(0).toUpperCase() + match[1].slice(1).toLowerCase().substring(0, 3);
    const year = match[2].slice(-2);
    return `${month}${year}`;
  }

  const isoMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    const year = isoMatch[1].slice(-2);
    const monthIdx = parseInt(isoMatch[2]) - 1;
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${months[monthIdx]}${year}`;
  }

  return "INVALID";
};

type SortField = 'id' | 'date';
type SortDirection = 'asc' | 'desc';

const GeneralJournal: React.FC<Props> = ({ transactions, accounts, onDelete, onUpdate, closedPeriods }) => {
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editDraft, setEditDraft] = useState<JournalEntry | null>(null);

  const [sortField, setSortField] = useState<SortField>('id');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  const accountMap = new Map<string, Account>(accounts.map(a => [a.id, a]));
  const activeAccounts = accounts.filter(a => !a.isArchived).sort((a,b) => a.name.localeCompare(b.name));

  const sortedTransactions = useMemo(() => {
    return [...transactions].sort((a, b) => {
      let comparison = 0;
      if (sortField === 'id') {
        comparison = a.id - b.id;
      } else {
        comparison = new Date(a.date).getTime() - new Date(b.date).getTime();
      }
      return sortDirection === 'asc' ? comparison : -comparison;
    });
  }, [transactions, sortField, sortDirection]);

  const startEditing = (entry: JournalEntry) => {
    if (entry.isClosingEntry) {
      alert("Closing entries cannot be manually edited.");
      return;
    }
    if (closedPeriods.includes(getStandardKey(entry.date))) {
      alert("Cannot edit transactions in a closed period.");
      return;
    }
    setEditingId(entry.id);
    setEditDraft({
      ...entry,
      lines: entry.lines.map(line => ({ ...line }))
    });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const updateDraftLine = (lineId: string, field: keyof JournalEntryLine, value: any) => {
    if (!editDraft) return;
    const updatedLines = editDraft.lines.map(l => l.id === lineId ? { ...l, [field]: value } : l);
    setEditDraft({ ...editDraft, lines: updatedLines });
  };

  const handleSave = () => {
    if (!editDraft) return;

    const totalDr = editDraft.lines.reduce((sum, l) => sum + (Number(l.debit) || 0), 0);
    const totalCr = editDraft.lines.reduce((sum, l) => sum + (Number(l.credit) || 0), 0);

    if (Math.abs(totalDr - totalCr) > 0.01) {
      alert(`Entry must be balanced! Difference: $${Math.abs(totalDr - totalCr).toFixed(2)}`);
      return;
    }

    onUpdate(editDraft);
    cancelEditing();
  };

  return (
    <div>
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8 border-b pb-6">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">General Journal</h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
            {transactions.length} Total Chronological Entries
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3 bg-slate-50 p-2 rounded-2xl border border-slate-200">
          <div className="flex items-center gap-2 px-3">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sort:</span>
            <div className="flex bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm">
              <button 
                onClick={() => setSortField('id')}
                className={`px-3 py-1.5 text-[10px] font-black uppercase transition-all ${sortField === 'id' ? 'bg-slate-900 text-white' : 'text-slate-400'}`}
              >
                ID
              </button>
              <button 
                onClick={() => setSortField('date')}
                className={`px-3 py-1.5 text-[10px] font-black uppercase transition-all ${sortField === 'date' ? 'bg-slate-900 text-white' : 'text-slate-400'}`}
              >
                Date
              </button>
            </div>
          </div>

          <button 
            onClick={() => setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc')}
            className="px-4 py-1.5 bg-white border border-slate-200 rounded-xl shadow-sm text-slate-600 font-black text-[10px] uppercase tracking-widest hover:bg-slate-50 transition-all"
          >
            {sortDirection === 'asc' ? 'Ascending' : 'Descending'}
          </button>
        </div>
      </div>

      <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white overflow-hidden">
        <table className="w-full text-sm border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b">
              <th className="p-4 text-left font-black text-slate-400 uppercase tracking-widest text-[9px] w-16">ID</th>
              <th className="p-4 text-left font-black text-slate-400 uppercase tracking-widest text-[9px] w-32">Date</th>
              <th className="p-4 text-left font-black text-slate-400 uppercase tracking-widest text-[9px]">Account</th>
              <th className="p-4 text-right font-black text-slate-400 uppercase tracking-widest text-[9px] w-32">Debit</th>
              <th className="p-4 text-right font-black text-slate-400 uppercase tracking-widest text-[9px] w-32">Credit</th>
              <th className="p-4 text-left font-black text-slate-400 uppercase tracking-widest text-[9px]">Memo / Ref</th>
              <th className="p-4 w-28"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedTransactions.length === 0 && (
              <tr>
                <td colSpan={7} className="p-20 text-center text-slate-400 italic font-medium">No recorded journal entries found.</td>
              </tr>
            )}
            {sortedTransactions.map((entry) => {
              const isEditing = editingId === entry.id;
              const displayEntry = isEditing && editDraft ? editDraft : entry;
              const isLocked = closedPeriods.includes(getStandardKey(entry.date)) || entry.isClosingEntry;

              return (
                <React.Fragment key={entry.id}>
                  {displayEntry.lines.map((line, idx) => {
                    const account = accountMap.get(line.accountId);
                    return (
                      <tr key={line.id} className={`group ${idx === 0 ? 'bg-slate-50/40' : 'bg-white'} hover:bg-emerald-50/10 transition-colors`}>
                        <td className="p-4 align-top font-mono text-xs text-slate-400 font-bold">
                          {idx === 0 ? entry.id : ''}
                        </td>
                        <td className="p-4 align-top text-slate-600 font-bold text-xs">
                          {idx === 0 ? (
                            isEditing ? (
                              <input 
                                type="date" 
                                value={displayEntry.date} 
                                onChange={(e) => setEditDraft({...editDraft!, date: e.target.value})}
                                className="border rounded-lg px-2 py-1 text-xs w-full outline-none focus:ring-2 focus:ring-emerald-500/20"
                              />
                            ) : entry.date
                          ) : ''}
                        </td>
                        <td className={`p-4 font-black text-xs ${line.credit > 0 ? 'pl-12 text-slate-500' : 'text-slate-900'}`}>
                          {isEditing ? (
                            <select
                              value={line.accountId}
                              onChange={(e) => updateDraftLine(line.id, 'accountId', e.target.value)}
                              className="w-full border rounded-lg px-2 py-1 text-xs outline-none"
                            >
                              <option value="">Select Account...</option>
                              {activeAccounts.map(acc => (
                                <option key={acc.id} value={acc.id}>{acc.name}</option>
                              ))}
                            </select>
                          ) : (
                            account?.name || 'Unknown Account'
                          )}
                        </td>
                        <td className="p-4 text-right font-mono font-black text-xs text-emerald-700">
                          {isEditing ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={line.debit || ''} 
                              onChange={(e) => updateDraftLine(line.id, 'debit', parseFloat(e.target.value) || 0)}
                              className="border rounded-lg px-2 py-1 text-xs w-full text-right"
                            />
                          ) : (
                            line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'
                          )}
                        </td>
                        <td className="p-4 text-right font-mono font-black text-xs text-amber-700">
                          {isEditing ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={line.credit || ''} 
                              onChange={(e) => updateDraftLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                              className="border rounded-lg px-2 py-1 text-xs w-full text-right"
                            />
                          ) : (
                            line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'
                          )}
                        </td>
                        <td className="p-4 text-slate-500 italic text-xs truncate max-w-xs">
                          {isEditing ? (
                            <input 
                              type="text" 
                              value={line.description} 
                              onChange={(e) => updateDraftLine(line.id, 'description', e.target.value)}
                              className="border rounded-lg px-2 py-1 text-xs w-full"
                            />
                          ) : (
                            <>
                              {line.description}
                              {idx === 0 && entry.method && (
                                <span className={`not-italic text-[8px] ml-2 px-1.5 py-0.5 rounded font-black uppercase border ${entry.isClosingEntry ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'}`}>
                                  {entry.isClosingEntry ? 'CLOSE' : entry.method}
                                </span>
                              )}
                            </>
                          )}
                        </td>
                        <td className="p-4 text-right">
                          {idx === 0 && (
                            <div className="flex justify-end items-center gap-1">
                              {isEditing ? (
                                <>
                                  <button onClick={handleSave} className="text-emerald-600 font-black text-[9px] uppercase px-2 py-1 bg-emerald-50 rounded hover:bg-emerald-100 transition-colors">Save</button>
                                  <button onClick={cancelEditing} className="text-slate-400 font-black text-[9px] uppercase px-2 py-1">X</button>
                                </>
                              ) : isLocked ? (
                                <span className="text-[9px] font-black text-slate-300 uppercase italic">Locked</span>
                              ) : (
                                <>
                                  <button 
                                    onClick={() => startEditing(entry)}
                                    className="p-1.5 text-slate-400 hover:text-slate-600 opacity-40 hover:opacity-100 transition-all"
                                    title="Edit Transaction"
                                  >
                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                                  </button>
                                  <button 
                                    onClick={() => onDelete(entry.id)}
                                    className="p-1.5 text-red-300 hover:text-red-500 opacity-40 hover:opacity-100 transition-all"
                                    title="Delete Transaction"
                                  >
                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                                  </button>
                                </>
                              )}
                            </div>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default GeneralJournal;

import React, { useState } from 'react';
import { signInWithPopup, signInWithEmailAndPassword, createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { auth, googleProvider } from '../firebase';

const Login: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<React.ReactNode | null>(null);
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');

  const handleGoogleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (err: any) {
      console.error("Auth Error:", err.code, err.message);
      if (err.code === 'auth/unauthorized-domain') {
        setError(
          <div className="text-left space-y-2">
            <p className="font-bold">Domain Not Authorized</p>
            <p className="text-[11px] leading-tight opacity-90">Please authorize this domain in Firebase Console.</p>
          </div>
        );
      } else if (err.code === 'auth/invalid-credential' || err.code === 'auth/user-not-found') {
        setError('The account credentials provided are invalid.');
      } else {
        setError(err.message || 'Failed to sign in with Google.');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      if (isSignUp) {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        if (displayName) {
          await updateProfile(userCredential.user, { displayName });
        }
      } else {
        await signInWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      console.error(err);
      let message = 'An error occurred during authentication.';
      if (err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password' || err.code === 'auth/invalid-credential' || err.code === 'auth/invalid-email') {
        message = 'Invalid email or password.';
      } else if (err.code === 'auth/email-already-in-use') {
        message = 'This email is already registered.';
      } else if (err.code === 'auth/weak-password') {
        message = 'Password should be at least 6 characters.';
      }
      setError(message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-2xl overflow-hidden p-8 md:p-10 space-y-6 text-center border border-slate-800/20">
        <div className="flex flex-col items-center gap-3">
          <div className="bg-emerald-500 p-3 rounded-2xl shadow-xl shadow-emerald-500/20">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path>
            </svg>
          </div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight leading-none uppercase">VISTA SHORE</h1>
        </div>

        <div className="space-y-4">
          {error && <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-xl text-xs font-medium animate-shake">{error}</div>}

          <button onClick={handleGoogleLogin} disabled={loading} className="w-full bg-slate-900 hover:bg-slate-800 text-white font-bold py-3.5 rounded-2xl transition-all flex items-center justify-center gap-3 shadow-lg active:scale-[0.98] disabled:opacity-50">
            {loading && !email ? <span className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full"></span> : (
              <span className="text-sm">Sign in with Google</span>
            )}
          </button>

          <div className="flex items-center gap-4 py-2">
            <div className="h-[1px] bg-slate-100 flex-1"></div>
            <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Or email</span>
            <div className="h-[1px] bg-slate-100 flex-1"></div>
          </div>

          <form onSubmit={handleEmailAuth} className="space-y-3 text-left">
            {isSignUp && (
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Full Name</label>
                <input type="text" value={displayName} onChange={(e) => setDisplayName(e.target.value)} className="w-full bg-slate-50 border border-slate-100 px-4 py-3 rounded-xl text-sm" placeholder="John Doe" required={isSignUp} />
              </div>
            )}
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Email</label>
              <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full bg-slate-50 border border-slate-100 px-4 py-3 rounded-xl text-sm" placeholder="name@company.com" required />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Password</label>
              <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-slate-50 border border-slate-100 px-4 py-3 rounded-xl text-sm" placeholder="••••••••" required />
            </div>

            <button type="submit" disabled={loading} className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-3.5 rounded-2xl shadow-lg active:scale-[0.98] disabled:opacity-50">
              {loading && email ? <span className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full mx-auto"></span> : (
                <span className="text-sm">{isSignUp ? 'Create Account' : 'Sign In'}</span>
              )}
            </button>
          </form>
        </div>

        <div className="pt-6 border-t border-slate-50 text-xs">
          {isSignUp ? 'Already have an account?' : "New here?"}{' '}
          <button onClick={() => setIsSignUp(!isSignUp)} className="text-emerald-600 font-bold hover:underline">
            {isSignUp ? 'Sign In' : 'Sign Up'}
          </button>
        </div>
      </div>
    </div>
  );
};

