import React, { useState, useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification, JournalEntryLine } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  closedPeriods: string[];
  onClosePeriod: (periodKey: string, closingEntry: JournalEntry) => void;
}

const getStandardKey = (dateStr: string) => {
  if (!dateStr) return "INVALID";
  const match = dateStr.match(/([a-zA-Z]+)\s+\d{1,2},\s+(\d{4})/);
  if (match) {
    const month = match[1];
    const year = match[2].slice(-2);
    const formattedMonth = month.charAt(0).toUpperCase() + month.slice(1).toLowerCase().substring(0, 3);
    return `${formattedMonth}${year}`;
  }
  const isoMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    const d = new Date(dateStr);
    const month = d.toLocaleString('en-US', { month: 'short' });
    const year = String(d.getFullYear()).slice(-2);
    return `${month}${year}`;
  }
  return "INVALID";
};

const ClosingManager: React.FC<Props> = ({ transactions, accounts, closedPeriods, onClosePeriod }) => {
  const [selectedPeriod, setSelectedPeriod] = useState<string>('');
  const [equityAllocations, setEquityAllocations] = useState<Record<string, number>>({});

  const availablePeriods = useMemo(() => {
    const periods = new Set<string>();
    transactions.forEach(t => {
      const key = getStandardKey(t.date);
      if (key !== "INVALID" && !closedPeriods.includes(key)) periods.add(key);
    });
    return Array.from(periods).sort();
  }, [transactions, closedPeriods]);

  const periodSummary = useMemo<{ netIncome: number; accountBalances: Record<string, number> } | null>(() => {
    if (!selectedPeriod) return null;
    let netIncome = 0;
    const accountBalances: Record<string, number> = {};

    transactions.forEach(t => {
      if (getStandardKey(t.date) === selectedPeriod && !t.isClosingEntry) {
        t.lines.forEach(l => {
          const acc = accounts.find(a => a.id === l.accountId);
          if (acc) {
            const amount = acc.naturalBalance === NaturalBalance.DEBIT ? (l.debit - l.credit) : (l.credit - l.debit);
            accountBalances[acc.id] = (accountBalances[acc.id] || 0) + amount;
            if (acc.financialStatement === FinancialStatement.INCOME_STATEMENT) {
               if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
                  netIncome += amount;
               } else {
                  netIncome -= amount;
               }
            }
          }
        });
      }
    });

    return { netIncome, accountBalances };
  }, [selectedPeriod, transactions, accounts]);

  const equityAccounts = accounts.filter(a => a.classification === AccountClassification.EQUITY && !a.isArchived);

  const handleClose = () => {
    // 1. Debug Start
    console.log("Attempting to close period:", selectedPeriod);

    if (!selectedPeriod || !periodSummary) return;

    const totalAllocated = (Object.values(equityAllocations) as number[]).reduce((s: number, v: number) => s + v, 0);

    // 2. Validation Log
    console.log(`Net Income: ${periodSummary.netIncome}, Allocated: ${totalAllocated}`);

    if (Math.abs(totalAllocated - periodSummary.netIncome) > 0.01) {
      alert(`Equity allocations ($${totalAllocated.toFixed(2)}) must equal Net Income ($${periodSummary.netIncome.toFixed(2)})!`);
      return;
    }

    // 3. REMOVED BLOCKING CONFIRMATION
    console.log("Validation passed. Generating entry...");

    const closingLines: JournalEntryLine[] = [];

    // Zero out Income Statement accounts
    accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT).forEach(acc => {
      const balance = (periodSummary.accountBalances[acc.id] || 0) as number;
      if (Math.abs(balance) < 0.01) return;

      if (acc.naturalBalance === NaturalBalance.DEBIT) {
        // To zero a debit balance, credit it
        closingLines.push({ id: Math.random().toString(), accountId: acc.id, debit: 0, credit: balance, description: `Closing ${selectedPeriod}` });
      } else {
        // To zero a credit balance, debit it
        closingLines.push({ id: Math.random().toString(), accountId: acc.id, debit: balance, credit: 0, description: `Closing ${selectedPeriod}` });
      }
    });

    // Allocate to Equity
    Object.entries(equityAllocations).forEach(([accId, amount]) => {
      const amt = amount as number;
      if (Math.abs(amt) < 0.01) return;
      const acc = accounts.find(a => a.id === accId);
      if (!acc) return;

      if (acc.naturalBalance === NaturalBalance.CREDIT) {
        if (amt > 0) closingLines.push({ id: Math.random().toString(), accountId: accId, debit: 0, credit: amt, description: `Profit Allocation ${selectedPeriod}` });
        else closingLines.push({ id: Math.random().toString(), accountId: accId, debit: Math.abs(amt), credit: 0, description: `Loss Allocation ${selectedPeriod}` });
      } else {
        if (amt > 0) closingLines.push({ id: Math.random().toString(), accountId: accId, debit: amt, credit: 0, description: `Profit Allocation ${selectedPeriod}` });
        else closingLines.push({ id: Math.random().toString(), accountId: accId, debit: 0, credit: Math.abs(amt), description: `Loss Allocation ${selectedPeriod}` });
      }
    });

    const maxId = transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0;

    // DATE CALCULATION: Set to last day of selectedPeriod (e.g. "Oct25" -> Oct 31, 2025)
    const monthStr = selectedPeriod.substring(0, 3);
    const yearStr = "20" + selectedPeriod.substring(3);
    const monthsArr = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const monthIdx = monthsArr.indexOf(monthStr);

    // new Date(year, monthIdx + 1, 0) gives the last day of monthIdx
    const closingDateObj = new Date(parseInt(yearStr), monthIdx + 1, 0);
    const closingDate = closingDateObj.toISOString().split('T')[0];

    const closingEntry: JournalEntry = {
      id: maxId + 1,
      date: closingDate,
      method: 'CLOSE',
      isClosingEntry: true,
      lines: closingLines
    };

    // 4. Final Execution Log
    console.log("Sending Closing Entry to App:", closingEntry);

    onClosePeriod(selectedPeriod, closingEntry);

    // 5. Reset UI
    setSelectedPeriod('');
    setEquityAllocations({});
  };

  return (
    <div className="space-y-10 max-w-4xl mx-auto">
      <div className="border-b-2 border-slate-900 pb-6">
        <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Close the Books</h2>
        <p className="text-sm font-bold text-slate-400 mt-2 italic uppercase">Zero out performance accounts and lock historical periods.</p>
      </div>

      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Select Period to Close</label>
          <select 
            value={selectedPeriod} 
            onChange={(e) => setSelectedPeriod(e.target.value)}
            className="w-full border rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-emerald-500 font-bold bg-slate-50"
          >
            <option value="">Choose Period...</option>
            {availablePeriods.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>

        {selectedPeriod && periodSummary && (
          <div className="animate-in fade-in slide-in-from-top-4 duration-300 space-y-8">
            <div className="bg-slate-900 text-white p-6 rounded-2xl flex justify-between items-center">
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Net Income for {selectedPeriod}</p>
                <p className="text-3xl font-black font-mono mt-1">${periodSummary.netIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
              </div>
              <div className="text-right">
                <span className={`text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest ${periodSummary.netIncome >= 0 ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
                  {periodSummary.netIncome >= 0 ? 'Profit' : 'Loss'}
                </span>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="text-sm font-black uppercase tracking-widest text-slate-700">Equity Allocation</h3>
              <div className="grid grid-cols-1 gap-4">
                {equityAccounts.map(acc => (
                  <div key={acc.id} className="flex items-center gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <span className="flex-1 font-bold text-slate-700">{acc.name}</span>
                    <input 
                      type="number"
                      step="0.01"
                      placeholder="Amount"
                      value={equityAllocations[acc.id] || ''}
                      onChange={(e) => setEquityAllocations({...equityAllocations, [acc.id]: parseFloat(e.target.value) || 0})}
                      className="w-32 border rounded-lg px-3 py-2 text-right font-mono text-sm"
                    />
                  </div>
                ))}
              </div>
            </div>

            <div className="pt-6 border-t flex justify-between items-center">
              <div className="text-xs font-bold">
                <span className="text-slate-400 uppercase tracking-widest mr-2">Total Allocated:</span>
                <span className={`font-mono ${Math.abs(((Object.values(equityAllocations) as number[]).reduce((s, v) => s + v, 0)) - periodSummary.netIncome) < 0.01 ? 'text-emerald-600' : 'text-red-500'}`}>
                  ${(Object.values(equityAllocations) as number[]).reduce((s, v) => s + v, 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </span>
              </div>
              <button 
                onClick={handleClose}
                className="bg-emerald-600 text-white px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-500 transition-all"
              >
                Execute Closing Entry
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ClosingManager;

import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  companyName: string;
}

const BalanceSheet: React.FC<Props> = ({ transactions = [], accounts = [], companyName }) => {
  const sortedPeriods = useMemo(() => {
    const periods = new Set<string>();
    transactions.forEach(tx => {
      // Use simple string extraction for year-month to avoid timezone issues
      const dateParts = tx.date.split('-');
      if (dateParts.length >= 2) {
        periods.add(`${dateParts[0]}-${dateParts[1]}`);
      }
    });
    return ["Opening", ...Array.from(periods).sort((a, b) => a.localeCompare(b))];
  }, [transactions]);

  /**
   * Calculates the cumulative balance of an account up to the end of a specific period.
   * Uses string-based date comparison to be timezone-independent.
   */
  const getCumulativeBalance = (accountId: string, upToPeriod: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = Number(account.startingBalance) || 0;
    if (upToPeriod === "Opening") return balance;

    // Construct the end-of-month date string (YYYY-MM-DD) for comparison
    const [year, month] = upToPeriod.split('-').map(Number);
    const lastDay = new Date(year, month, 0).getDate();
    const cutoffStr = `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

    transactions.forEach(tx => {
      // String comparison works perfectly for YYYY-MM-DD format
      if (tx.date <= cutoffStr) {
        tx.lines.forEach(l => {
          if (l.accountId === accountId) {
            if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
            else balance += (l.credit - l.debit);
          }
        });
      }
    });
    return balance;
  };

  /**
   * Sums the balances of all Income Statement accounts as of the cutoff date.
   * Closed months will show $0 because the closing entries zero out these accounts.
   */
  const getUnclosedEarningsForSnapshot = (period: string) => {
    if (period === "Opening") return 0;

    const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
    let totalUnclosedEarnings = 0;

    isAccounts.forEach(acc => {
      const balance = getCumulativeBalance(acc.id, period);
      // For the Income Statement accounts:
      // Profit increases with Credit (Revenue) and decreases with Debit (Expenses)
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
        // Revenue/Income accounts: Natural balance is Credit. 
        // A Credit cumulative balance means profit.
        totalUnclosedEarnings += balance;
      } else {
        // Expense/COGS accounts: Natural balance is Debit.
        // A Debit cumulative balance means loss.
        totalUnclosedEarnings -= balance;
      }
    });

    return totalUnclosedEarnings;
  };

  const bsAccounts = accounts.filter(a => 
    a.financialStatement === FinancialStatement.BALANCE_SHEET && 
    !a.name.toLowerCase().includes('retained earnings')
  );

  const calculateClassTotal = (classification: AccountClassification, upToPeriod: string) => {
    return bsAccounts
      .filter(a => a.classification === classification)
      .reduce((sum, a) => {
        const bal = getCumulativeBalance(a.id, upToPeriod);
        // For Liabilities and Equity, we report the Credit balance as positive
        if (classification === AccountClassification.EQUITY || 
            classification === AccountClassification.CURRENT_LIABILITY || 
            classification === AccountClassification.LONG_TERM_LIABILITY) {
          return sum + (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
        }
        return sum + bal;
      }, 0);
  };

  const partnerGroups = useMemo(() => {
    const equityAccounts = bsAccounts.filter(a => a.classification === AccountClassification.EQUITY);
    const groups: Record<string, Account[]> = {};
    const ungrouped: Account[] = [];

    equityAccounts.forEach(acc => {
      const parts = acc.name.split(/ - |,/);
      if (parts.length > 1) {
        const partnerName = parts[0].trim();
        if (!groups[partnerName]) groups[partnerName] = [];
        groups[partnerName].push(acc);
      } else {
        ungrouped.push(acc);
      }
    });
    return { groups, ungrouped };
  }, [bsAccounts]);

  if (sortedPeriods.length <= 1 && transactions.length === 0) {
    return (
      <div className="p-20 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed border-slate-200">
        <p className="text-lg font-bold mb-2 text-slate-700 tracking-tight">Audit Pending</p>
        <p className="text-sm">Record capital contributions or expenses to generate the balance sheet.</p>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-900">{companyName}</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Balance Sheet (Consolidated Period Snapshots)</p>
      </div>

      <div className="overflow-x-auto border rounded-2xl shadow-xl bg-white">
        <table className="w-full border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-900 text-white">
              <th className="p-4 text-left w-64 border-r border-slate-800 text-[10px] font-black uppercase tracking-widest">Account Classification</th>
              {sortedPeriods.map(p => (
                <th key={p} className={`p-4 text-right text-[10px] uppercase font-black tracking-widest border-r border-slate-800 ${p === 'Opening' ? 'bg-slate-800' : ''}`}>
                  {p === 'Opening' ? 'Opening' : new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            <tr className="bg-slate-50"><td colSpan={sortedPeriods.length + 1} className="p-3 font-black text-slate-900 text-[10px] tracking-widest uppercase border-b">1. ASSETS</td></tr>
            {[AccountClassification.CURRENT_ASSET, AccountClassification.LONG_TERM_ASSET].map(cls => (
              <React.Fragment key={cls}>
                <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">{cls}s</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
                {bsAccounts.filter(a => a.classification === cls).map(acc => (
                  <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                    <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                    {sortedPeriods.map(p => (
                      <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 ${p === 'Opening' ? 'text-slate-400 italic' : ''}`}>
                        {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                ))}
              </React.Fragment>
            ))}
            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">TOTAL ASSETS</td>
              {sortedPeriods.map(p => {
                const total = calculateClassTotal(AccountClassification.CURRENT_ASSET, p) + calculateClassTotal(AccountClassification.LONG_TERM_ASSET, p);
                return <td key={p} className="p-4 text-right font-mono text-sm border-r border-slate-700">${total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>

            <tr className="h-10"></tr>

            <tr className="bg-slate-50"><td colSpan={sortedPeriods.length + 1} className="p-3 font-black text-slate-900 text-[10px] tracking-widest uppercase border-b">2. LIABILITIES & EQUITY</td></tr>
            <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Liabilities</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
            {[AccountClassification.CURRENT_LIABILITY, AccountClassification.LONG_TERM_LIABILITY].map(cls => (
              bsAccounts.filter(a => a.classification === cls).map(acc => (
                <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                  <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                  {sortedPeriods.map(p => (
                    <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                      {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>
                  ))}
                </tr>
              ))
            ))}

            <tr className="bg-white border-t border-slate-100"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Partnership Equity</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>

            {(Object.entries(partnerGroups.groups) as [string, Account[]][]).map(([partner, accs]) => (
              <React.Fragment key={partner}>
                {accs.map(acc => (
                  <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                    <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                    {sortedPeriods.map(p => (
                      <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                        {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                ))}
                <tr className="bg-slate-50/50 font-black border-b border-slate-200">
                  <td className="p-2.5 pl-6 text-[10px] uppercase text-slate-900 border-r border-slate-100">Total {partner} Capital</td>
                  {sortedPeriods.map(p => {
                    const groupSum = accs.reduce((sum, a) => {
                      const bal = getCumulativeBalance(a.id, p);
                      return sum + (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
                    }, 0);
                    return <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100 text-blue-700 bg-blue-50/20">${groupSum.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                  })}
                </tr>
              </React.Fragment>
            ))}

            {partnerGroups.ungrouped.map(acc => (
              <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                {sortedPeriods.map(p => (
                  <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                    {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                ))}
              </tr>
            ))}

            <tr className="border-b bg-emerald-50/10">
              <td className="p-2.5 pl-8 text-xs font-black text-emerald-800 italic border-r border-slate-100">Current period earnings</td>
              {sortedPeriods.map(p => {
                const snapshotEarnings = getUnclosedEarningsForSnapshot(p);
                return (
                  <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 font-black ${p === 'Opening' ? 'text-slate-300' : (snapshotEarnings === 0 ? 'text-slate-400' : 'text-emerald-600')}`}>
                    {snapshotEarnings.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                );
              })}
            </tr>

            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">TOTAL LIABILITIES & EQUITY</td>
              {sortedPeriods.map(p => {
                const totalL = calculateClassTotal(AccountClassification.CURRENT_LIABILITY, p) + calculateClassTotal(AccountClassification.LONG_TERM_LIABILITY, p);
                const totalE = calculateClassTotal(AccountClassification.EQUITY, p);
                const snapshotEarnings = getUnclosedEarningsForSnapshot(p);
                return <td key={p} className="p-4 text-right font-mono text-sm border-r border-slate-700">${(totalL + totalE + snapshotEarnings).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>
          </tbody>
        </table>
      </div>
      <p className="mt-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest italic text-center">
        * "Current period earnings" displays $0.00 for periods where a Closing Entry has allocated income to Capital accounts.
      </p>
    </div>
  );
};

