const safeStringify = (obj: any) => {
  const cache = new WeakSet();
  return JSON.stringify(obj, (key, value) => {
    if (typeof value === 'object' && value !== null) {
      if (cache.has(value)) return;
      cache.add(value);
    }
    return value;
  });
};

/**
 * Timezone-independent Period Key generator.
 * Converts "2025-01-31" or "Dec 1, 2025" to "Jan25".
 */
const getStandardKey = (dateStr: string) => {
  if (!dateStr) return "INVALID";

  // Format: "Dec 1, 2025" (Amazon / Human readable)
  const match = dateStr.match(/([a-zA-Z]+)\s+\d{1,2},\s+(\d{4})/);
  if (match) {
    const month = match[1].charAt(0).toUpperCase() + match[1].slice(1).toLowerCase().substring(0, 3);
    const year = match[2].slice(-2);
    return `${month}${year}`;
  }

  // Format: "2025-01-31" (ISO / Input Date)
  const isoMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    const year = isoMatch[1].slice(-2);
    const monthIdx = parseInt(isoMatch[2]) - 1;
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${months[monthIdx]}${year}`;
  }

  return "INVALID";
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([{ name: 'JE', accountId: '' }]);
  const [companyName, setCompanyName] = useState('Vista Shore Products, LLC');
  const [amazonRecords, setAmazonRecords] = useState<AmazonAnalysisRecord[]>([]);
  const [skuData, setSkuData] = useState<SkuDataMap>({});
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  const isUpdatingRef = useRef(false);

  useEffect(() => {
    // Correct modular syntax for onAuthStateChanged
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
        if (parsed.paymentMethods) setPaymentMethods(parsed.paymentMethods);
        if (parsed.companyName) setCompanyName(parsed.companyName);
        if (parsed.amazonRecords) setAmazonRecords(parsed.amazonRecords);
        if (parsed.skuData) setSkuData(parsed.skuData);
      } catch (e) {}
    }

    const userDocRef = doc(db, 'users', user.uid);
    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      if (isUpdatingRef.current) return;
      if (docSnap.metadata.hasPendingWrites) return;

      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data) {
          if (data.accounts) setAccounts(data.accounts);
          if (data.transactions) setTransactions(data.transactions);
          if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
          if (data.paymentMethods) setPaymentMethods(data.paymentMethods);
          if (data.companyName) setCompanyName(data.companyName);
          if (data.amazonRecords) setAmazonRecords(data.amazonRecords);
          if (data.skuData) setSkuData(data.skuData);

          localStorage.setItem(`vista_data_${user.uid}`, safeStringify(data));
        }
      }
    }, (error) => {
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = useCallback(async (
    newAccs: Account[], 
    newTxs: JournalEntry[], 
    newPeriods: string[], 
    newMethods: PaymentMethod[], 
    newName: string,
    newAmazon: AmazonAnalysisRecord[],
    newSku: SkuDataMap,
    lockTime: number = 1500 
  ) => {
    if (!user) return;
    isUpdatingRef.current = true;
    setIsSyncing(true);

    const packet = {
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods,
      paymentMethods: newMethods,
      companyName: newName,
      amazonRecords: newAmazon,
      skuData: newSku
    };

    localStorage.setItem(`vista_data_${user.uid}`, safeStringify(packet));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        ...packet,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      setCloudError("Failed to save to cloud.");
    } finally {
      setTimeout(() => { 
        isUpdatingRef.current = false; 
        setIsSyncing(false);
      }, lockTime);
    }
  }, [user]);

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteTransaction = useCallback((id: number) => {
    const tx = transactions.find(t => t.id === id);
    if (!tx) return;

    const periodKey = getStandardKey(tx.date);

    // If it's a closing entry, allow deletion but also reopen the period
    if (tx.isClosingEntry) {
      if (window.confirm(`This is a CLOSING ENTRY for ${periodKey}. Deleting it will REOPEN the books for this period. Proceed?`)) {
        const updatedTxs = transactions.filter(t => t.id !== id);
        const updatedPeriods = closedPeriods.filter(p => p !== periodKey);
        setTransactions(updatedTxs);
        setClosedPeriods(updatedPeriods);
        saveToFirestore(accounts, updatedTxs, updatedPeriods, paymentMethods, companyName, amazonRecords, skuData);
      }
      return;
    }

    if (closedPeriods.includes(periodKey)) {
      alert(`Cannot delete Transaction #${id}. The period ${periodKey} is closed. You must delete the Closing Entry first to reopen the period.`);
      return;
    }

    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  }, [transactions, accounts, closedPeriods, paymentMethods, companyName, amazonRecords, skuData, saveToFirestore]);

  const onClosePeriod = (periodKey: string, closingEntry: JournalEntry) => {
    if (closedPeriods.includes(periodKey)) {
      alert(`Period ${periodKey} is already closed.`);
      return;
    }
    const newTxs = [...transactions, closingEntry];
    const newPeriods = [...closedPeriods, periodKey];
    setTransactions(newTxs);
    setClosedPeriods(newPeriods);
    saveToFirestore(accounts, newTxs, newPeriods, paymentMethods, companyName, amazonRecords, skuData);
    alert(`Success! The books for ${periodKey} have been closed.`);
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const updateAmazonRecords = (recs: AmazonAnalysisRecord[]) => {
    setAmazonRecords(recs);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, recs, skuData);
  };

  const removeAmazonPeriod = (periodKey: string) => {
    const updated = amazonRecords.filter(r => getStandardKey(r.date) !== periodKey);
    setAmazonRecords(updated);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, updated, skuData);
  };

  const updateSkuData = (data: SkuDataMap) => {
    setSkuData(data);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, data);
  };

  const updateCompanyName = (name: string) => {
    setCompanyName(name);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, name, amazonRecords, skuData);
  };

  const handleImport = (newTxs: JournalEntry[], newAccs: Account[]) => {
    const updatedAccs = [...accounts];
    newAccs.forEach(na => {
      if (!updatedAccs.find(a => a.name.toLowerCase() === na.name.toLowerCase())) {
        updatedAccs.push(na);
      }
    });
    const updatedTxs = [...transactions, ...newTxs];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const handleReset = (full: boolean) => {
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      setAmazonRecords([]);
      setSkuData({});
      saveToFirestore(INITIAL_ACCOUNTS, [], [], paymentMethods, companyName, [], {});
    } else {
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], [], paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const addPaymentMethod = (name: string, accountId: string) => {
    const updated = [...paymentMethods, { name, accountId }];
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const removePaymentMethod = (name: string) => {
    const updated = paymentMethods.filter(m => m.name !== name);
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Amazon Analysis', 'COGS Manager', 'Closing Manager', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}
      {isSyncing && (
        <div className="fixed bottom-6 right-6 z-[999] bg-slate-900 text-white px-5 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4">
          <div className="w-2 h-2 rounded-full animate-ping bg-emerald-500"></div>
          <span className="text-[10px] font-black uppercase tracking-widest">Processing Data Update...</span>
        </div>
      )}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-50 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <div className="flex flex-col">
            <h1 className="text-xl font-bold tracking-tighter text-white uppercase">VISTA SHORE</h1>
          </div>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={() => exportFinancialPackage(transactions, accounts, companyName)}
            className="bg-indigo-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-indigo-500 transition-colors text-white"
          >
            Download Package (.xlsx)
          </button>
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors text-white">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} paymentMethods={paymentMethods} companyName={companyName} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} paymentMethods={paymentMethods} closedPeriods={closedPeriods} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} closedPeriods={closedPeriods} paymentMethods={paymentMethods} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Amazon Analysis' && <AmazonAnalysis skuData={skuData} records={amazonRecords} onUpdateRecords={updateAmazonRecords} onRemovePeriod={removeAmazonPeriod} companyName={companyName} isSyncing={isSyncing} />}
            {activeTab === 'COGS Manager' && <CogsManager skuData={skuData} onUpdateSkuData={updateSkuData} />}
            {activeTab === 'Closing Manager' && <ClosingManager transactions={transactions} accounts={accounts} closedPeriods={closedPeriods} onClosePeriod={onClosePeriod} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={handleImport} onReset={handleReset} paymentMethods={paymentMethods} onAddMethod={addPaymentMethod} onRemoveMethod={removePaymentMethod} companyName={companyName} onUpdateCompanyName={updateCompanyName} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import * as XLSX from 'xlsx';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

/**
 * Helper to get cumulative balance of an account up to a specific YYYY-MM period end.
 */
const getCumulativeBalance = (accountId: string, period: string, transactions: JournalEntry[], accounts: Account[]) => {
  const account = accounts.find(a => a.id === accountId);
  if (!account) return 0;

  let balance = Number(account.startingBalance) || 0;
  const [year, month] = period.split('-').map(Number);
  const lastDay = new Date(year, month, 0).getDate();
  const cutoffStr = `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

  transactions.forEach(tx => {
    if (tx.date <= cutoffStr) {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
          else balance += (l.credit - l.debit);
        }
      });
    }
  });
  return balance;
};

/**
 * Helper to get monthly activity (Net) for Income Statement accounts.
 */
const getMonthlyActivity = (accountId: string, period: string, transactions: JournalEntry[], accounts: Account[]) => {
  const account = accounts.find(a => a.id === accountId);
  if (!account) return 0;

  let activity = 0;
  const [year, month] = period.split('-').map(Number);

  transactions.filter(tx => !tx.isClosingEntry).forEach(tx => {
    const date = new Date(tx.date);
    if (date.getFullYear() === year && (date.getMonth() + 1) === month) {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) activity += (l.debit - l.credit);
          else activity += (l.credit - l.debit);
        }
      });
    }
  });
  return activity;
};

export const exportFinancialPackage = (transactions: JournalEntry[], accounts: Account[], companyName: string) => {
  const wb = XLSX.utils.book_new();
  const periods = Array.from(new Set(transactions.map(t => t.date.slice(0, 7)))).sort();
  const indent = (s: string) => "  " + s;

  // --- 1. INCOME STATEMENT ---
  const isRows: any[] = [
    [`${companyName} - INCOME STATEMENT`],
    [`Exported: ${new Date().toLocaleDateString()}`],
    [],
    ["Account / Line Item", ...periods]
  ];

  const buildISSection = (title: string, classification: AccountClassification) => {
    isRows.push([title.toUpperCase()]);
    const filtered = accounts.filter(a => a.classification === classification);
    filtered.forEach(acc => {
      // Fix: Explicitly type row to allow numbers
      const row: (string | number)[] = [indent(acc.name)];
      periods.forEach(p => row.push(getMonthlyActivity(acc.id, p, transactions, accounts)));
      isRows.push(row);
    });
    // Fix: Explicitly type totalRow to allow numbers
    const totalRow: (string | number)[] = [`TOTAL ${title.toUpperCase()}`];
    periods.forEach(p => {
      const total = filtered.reduce((sum, a) => sum + getMonthlyActivity(a.id, p, transactions, accounts), 0);
      totalRow.push(total);
    });
    isRows.push(totalRow);
    isRows.push([]);
  };

  buildISSection("Revenue", AccountClassification.REVENUE);
  buildISSection("Cost of Goods Sold", AccountClassification.COGS);

  // Gross Profit
  // Fix: Explicitly type gpRow to allow numbers
  const gpRow: (string | number)[] = ["GROSS PROFIT"];
  periods.forEach(p => {
    const rev = accounts.filter(a => a.classification === AccountClassification.REVENUE).reduce((sum, a) => sum + getMonthlyActivity(a.id, p, transactions, accounts), 0);
    const cogs = accounts.filter(a => a.classification === AccountClassification.COGS).reduce((sum, a) => sum + getMonthlyActivity(a.id, p, transactions, accounts), 0);
    gpRow.push(rev - cogs);
  });
  isRows.push(gpRow);
  isRows.push([]);

  buildISSection("Operating Expenses", AccountClassification.OPERATING_EXPENSE);
  buildISSection("Other Income (Expenses)", AccountClassification.OTHER_INCOME_EXPENSE);

  // Fix: Explicitly type netIncRow to allow numbers
  const netIncRow: (string | number)[] = ["NET INCOME"];
  periods.forEach(p => {
    let income = 0;
    accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT).forEach(acc => {
      const act = getMonthlyActivity(acc.id, p, transactions, accounts);
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) income += act;
      else income -= act;
    });
    netIncRow.push(income);
  });
  isRows.push(netIncRow);

  const isSheet = XLSX.utils.aoa_to_sheet(isRows);
  XLSX.utils.book_append_sheet(wb, isSheet, "Income Statement");

  // --- 2. BALANCE SHEET ---
  const bsRows: any[] = [
    [`${companyName} - BALANCE SHEET`],
    [`Exported: ${new Date().toLocaleDateString()}`],
    [],
    ["Account / Line Item", ...periods]
  ];

  const buildBSSection = (title: string, classifications: AccountClassification[]) => {
    bsRows.push([title.toUpperCase()]);
    classifications.forEach(cls => {
      const filtered = accounts.filter(a => a.classification === cls && a.financialStatement === FinancialStatement.BALANCE_SHEET);
      filtered.forEach(acc => {
        // Fix: Explicitly type row to allow numbers
        const row: (string | number)[] = [indent(acc.name)];
        periods.forEach(p => row.push(getCumulativeBalance(acc.id, p, transactions, accounts)));
        bsRows.push(row);
      });
    });
    // Fix: Explicitly type totalRow to allow numbers
    const totalRow: (string | number)[] = [`TOTAL ${title.toUpperCase()}`];
    periods.forEach(p => {
      let total = 0;
      classifications.forEach(cls => {
        accounts.filter(a => a.classification === cls && a.financialStatement === FinancialStatement.BALANCE_SHEET).forEach(a => {
          const bal = getCumulativeBalance(a.id, p, transactions, accounts);
          if (cls === AccountClassification.EQUITY || cls === AccountClassification.CURRENT_LIABILITY || cls === AccountClassification.LONG_TERM_LIABILITY) {
            total += (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
          } else {
            total += bal;
          }
        });
      });
      totalRow.push(total);
    });
    bsRows.push(totalRow);
    bsRows.push([]);
    return totalRow; // Return for secondary calculation
  };

  buildBSSection("Assets", [AccountClassification.CURRENT_ASSET, AccountClassification.LONG_TERM_ASSET]);
  buildBSSection("Liabilities", [AccountClassification.CURRENT_LIABILITY, AccountClassification.LONG_TERM_LIABILITY]);

  bsRows.push(["EQUITY"]);
  const equityAccs = accounts.filter(a => a.classification === AccountClassification.EQUITY);
  equityAccs.forEach(acc => {
    // Fix: Explicitly type row to allow numbers
    const row: (string | number)[] = [indent(acc.name)];
    periods.forEach(p => row.push(getCumulativeBalance(acc.id, p, transactions, accounts)));
    bsRows.push(row);
  });

  // Fix: Explicitly type earningsRow to allow numbers
  const earningsRow: (string | number)[] = [indent("Current Period Earnings")];
  periods.forEach(p => {
    let totalCredits = 0;
    let totalDebits = 0;
    const isIds = new Set(accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT).map(a => a.id));
    const [year, month] = p.split('-').map(Number);
    const cutoffStr = `${year}-${String(month).padStart(2, '0')}-${String(new Date(year, month, 0).getDate()).padStart(2, '0')}`;
    transactions.forEach(tx => {
      if (tx.date <= cutoffStr) {
        tx.lines.forEach(l => {
          if (isIds.has(l.accountId)) {
            totalDebits += l.debit;
            totalCredits += l.credit;
          }
        });
      }
    });
    earningsRow.push(totalCredits - totalDebits);
  });
  bsRows.push(earningsRow);

  // Fix: Explicitly type totalEquityRow to allow numbers
  const totalEquityRow: (string | number)[] = ["TOTAL LIABILITIES & EQUITY"];
  periods.forEach((p, idx) => {
    let lTotal = 0;
    [AccountClassification.CURRENT_LIABILITY, AccountClassification.LONG_TERM_LIABILITY].forEach(cls => {
      accounts.filter(a => a.classification === cls).forEach(a => {
        const bal = getCumulativeBalance(a.id, p, transactions, accounts);
        lTotal += (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
      });
    });
    let eTotal = equityAccs.reduce((sum, a) => {
      const bal = getCumulativeBalance(a.id, p, transactions, accounts);
      return sum + (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
    }, 0);
    const earnings = Number(earningsRow[idx + 1]) || 0;
    totalEquityRow.push(lTotal + eTotal + earnings);
  });
  bsRows.push(totalEquityRow);

  const bsSheet = XLSX.utils.aoa_to_sheet(bsRows);
  XLSX.utils.book_append_sheet(wb, bsSheet, "Balance Sheet");

  // --- 3. CASH FLOW STATEMENT ---
  const cfRows: any[] = [
    [`${companyName} - STATEMENT OF CASH FLOWS`],
    [`Exported: ${new Date().toLocaleDateString()}`],
    [],
    ["Activity Group", ...periods]
  ];

  const cashAccountIds = accounts.filter(a => a.classification === AccountClassification.CURRENT_ASSET && (a.name.toLowerCase().includes('cash') || a.name.toLowerCase().includes('bank'))).map(a => a.id);

  cfRows.push(["OPERATING ACTIVITIES"]);
  // Fix: Explicitly type niRow to allow numbers
  const niRow: (string | number)[] = [indent("Net Income")];
  // Fix: Explicitly type depRow to allow numbers
  const depRow: (string | number)[] = [indent("Depreciation Adjustment")];
  // Fix: Explicitly type wcRow to allow numbers
  const wcRow: (string | number)[] = [indent("Changes in Working Capital")];
  // Fix: Explicitly type opsTotalRow to allow numbers
  const opsTotalRow: (string | number)[] = ["Net Operating Flow"];

  periods.forEach(p => {
    let ni = 0;
    accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT).forEach(acc => {
      const act = getMonthlyActivity(acc.id, p, transactions, accounts);
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) ni += act;
      else ni -= act;
    });
    niRow.push(ni);

    const depExp = accounts.find(a => a.name.toLowerCase().includes('depreciation') && a.financialStatement === FinancialStatement.INCOME_STATEMENT);
    const dep = depExp ? getMonthlyActivity(depExp.id, p, transactions, accounts) : 0;
    depRow.push(dep);

    const assets = accounts.filter(a => a.classification === AccountClassification.CURRENT_ASSET && !cashAccountIds.includes(a.id));
    const liabs = accounts.filter(a => a.classification === AccountClassification.CURRENT_LIABILITY);
    const assetChg = assets.reduce((sum, a) => sum - getMonthlyActivity(a.id, p, transactions, accounts), 0);
    const liabChg = liabs.reduce((sum, a) => sum + getMonthlyActivity(a.id, p, transactions, accounts), 0);
    wcRow.push(assetChg + liabChg);
    opsTotalRow.push(ni + dep + assetChg + liabChg);
  });
  cfRows.push(niRow, depRow, wcRow, opsTotalRow, []);

  cfRows.push(["INVESTING ACTIVITIES"]);
  // Fix: Explicitly type invRow to allow numbers
  const invRow: (string | number)[] = [indent("Asset Purchases / Capex")];
  periods.forEach(p => {
    const ltAssets = accounts.filter(a => a.classification === AccountClassification.LONG_TERM_ASSET);
    invRow.push(ltAssets.reduce((sum, a) => sum + getMonthlyActivity(a.id, p, transactions, accounts), 0));
  });
  cfRows.push(invRow, ["Net Investing Flow", ...invRow.slice(1)], []);

  cfRows.push(["FINANCING ACTIVITIES"]);
  // Fix: Explicitly type contRow to allow numbers
  const contRow: (string | number)[] = [indent("Cash Contributions")];
  // Fix: Explicitly type distRow to allow numbers
  const distRow: (string | number)[] = [indent("Cash Distributions")];
  // Fix: Explicitly type debtRow to allow numbers
  const debtRow: (string | number)[] = [indent("Net Change in Debt")];
  // Fix: Explicitly type finTotalRow to allow numbers
  const finTotalRow: (string | number)[] = ["Net Financing Flow"];

  periods.forEach(p => {
    const [year, month] = p.split('-').map(Number);
    let cont = 0; let dist = 0; let debt = 0;
    const eqIds = accounts.filter(a => a.classification === AccountClassification.EQUITY).map(a => a.id);
    const dIds = accounts.filter(a => a.classification === AccountClassification.LONG_TERM_LIABILITY).map(a => a.id);

    transactions.forEach(tx => {
      if (tx.isClosingEntry) return;
      const d = new Date(tx.date);
      if (d.getFullYear() === year && (d.getMonth() + 1) === month) {
        if (tx.lines.some(l => cashAccountIds.includes(l.accountId))) {
          tx.lines.forEach(l => {
            if (eqIds.includes(l.accountId)) {
              const net = l.credit - l.debit;
              if (net > 0) cont += net; else if (net < 0) dist += Math.abs(net);
            }
            if (dIds.includes(l.accountId)) debt += (l.credit - l.debit);
          });
        }
      }
    });
    contRow.push(cont);
    distRow.push(dist > 0 ? -dist : 0);
    debtRow.push(debt);
    finTotalRow.push(cont - dist + debt);
  });
  cfRows.push(contRow, distRow, debtRow, finTotalRow, []);

  // Fix: Explicitly type changeRow to allow numbers
  const changeRow: (string | number)[] = ["PERIOD CASH CHANGE"];
  // Fix: Explicitly type startRow to allow numbers
  const startRow: (string | number)[] = ["Opening Balance"];
  // Fix: Explicitly type endRow to allow numbers
  const endRow: (string | number)[] = ["CLOSING CASH POSITION"];

  periods.forEach((p, idx) => {
    const change = Number(opsTotalRow[idx + 1]) + Number(invRow[idx + 1]) + Number(finTotalRow[idx + 1]);
    changeRow.push(change);

    let startBal = 0;
    if (idx === 0) {
      startBal = accounts.filter(a => cashAccountIds.includes(a.id)).reduce((sum, a) => sum + (Number(a.startingBalance) || 0), 0);
      const [y, m] = p.split('-').map(Number);
      const cutoff = new Date(y, m - 1, 1);
      transactions.forEach(tx => {
        if (new Date(tx.date) < cutoff) {
          tx.lines.forEach(l => { if (cashAccountIds.includes(l.accountId)) startBal += (l.debit - l.credit); });
        }
      });
    } else {
      startBal = Number(endRow[idx]);
    }
    startRow.push(startBal);
    endRow.push(startBal + change);
  });
  cfRows.push(changeRow, startRow, endRow);

  const cfSheet = XLSX.utils.aoa_to_sheet(cfRows);
  XLSX.utils.book_append_sheet(wb, cfSheet, "Cash Flow");

  XLSX.writeFile(wb, `${companyName.replace(/\s+/g, '_')}_Financials_${new Date().toISOString().slice(0, 10)}.xlsx`);
};

import * as XLSX from 'xlsx';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement, AmazonAnalysisRecord, SkuDataMap, AmazonCategory } from '../types';

const getStandardKey = (dateStr: string) => {
  if (!dateStr) return "INVALID";
  const match = dateStr.match(/([a-zA-Z]+)\s+\d{1,2},\s+(\d{4})/);
  if (match) {
    const month = match[1];
    const year = match[2].slice(-2);
    const formattedMonth = month.charAt(0).toUpperCase() + month.slice(1).toLowerCase().substring(0, 3);
    return `${formattedMonth}${year}`;
  }
  return "INVALID";
};

/**
 * Helper to get cumulative balance of an account up to a specific YYYY-MM period end.
 */
const getCumulativeBalance = (accountId: string, period: string, transactions: JournalEntry[], accounts: Account[]) => {
  const account = accounts.find(a => a.id === accountId);
  if (!account) return 0;

  let balance = Number(account.startingBalance) || 0;
  const [year, month] = period.split('-').map(Number);
  const lastDay = new Date(year, month, 0).getDate();
  const cutoffStr = `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

  transactions.forEach(tx => {
    if (tx.date <= cutoffStr) {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
          else balance += (l.credit - l.debit);
        }
      });
    }
  });
  return balance;
};

/**
 * Helper to get monthly activity (Net) for Income Statement accounts.
 */
const getMonthlyActivity = (accountId: string, period: string, transactions: JournalEntry[], accounts: Account[]) => {
  const account = accounts.find(a => a.id === accountId);
  if (!account) return 0;

  let activity = 0;
  const [year, month] = period.split('-').map(Number);

  transactions.filter(tx => !tx.isClosingEntry).forEach(tx => {
    const date = new Date(tx.date);
    if (date.getFullYear() === year && (date.getMonth() + 1) === month) {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) activity += (l.debit - l.credit);
          else activity += (l.credit - l.debit);
        }
      });
    }
  });
  return activity;
};

export const exportFinancialPackage = (
  transactions: JournalEntry[], 
  accounts: Account[], 
  companyName: string,
  amazonRecords: AmazonAnalysisRecord[] = [],
  skuData: SkuDataMap = {}
) => {
  const wb = XLSX.utils.book_new();
  const periods = Array.from(new Set(transactions.map(t => t.date.slice(0, 7)))).sort();
  const indent = (s: string) => "  " + s;

  // --- 1. INCOME STATEMENT ---
  const isRows: any[] = [
    [`${companyName} - INCOME STATEMENT`],
    [`Exported: ${new Date().toLocaleDateString()}`],
    [],
    ["Account / Line Item", ...periods]
  ];

  const buildISSection = (title: string, classification: AccountClassification) => {
    isRows.push([title.toUpperCase()]);
    const filtered = accounts.filter(a => a.classification === classification);
    filtered.forEach(acc => {
      const row: (string | number)[] = [indent(acc.name)];
      periods.forEach(p => row.push(getMonthlyActivity(acc.id, p, transactions, accounts)));
      isRows.push(row);
    });
    const totalRow: (string | number)[] = [`TOTAL ${title.toUpperCase()}`];
    periods.forEach(p => {
      const total = filtered.reduce((sum, a) => sum + getMonthlyActivity(a.id, p, transactions, accounts), 0);
      totalRow.push(total);
    });
    isRows.push(totalRow);
    isRows.push([]);
  };

  buildISSection("Revenue", AccountClassification.REVENUE);
  buildISSection("Cost of Goods Sold", AccountClassification.COGS);

  const gpRow: (string | number)[] = ["GROSS PROFIT"];
  periods.forEach(p => {
    const rev = accounts.filter(a => a.classification === AccountClassification.REVENUE).reduce((sum, a) => sum + getMonthlyActivity(a.id, p, transactions, accounts), 0);
    const cogs = accounts.filter(a => a.classification === AccountClassification.COGS).reduce((sum, a) => sum + getMonthlyActivity(a.id, p, transactions, accounts), 0);
    gpRow.push(rev - cogs);
  });
  isRows.push(gpRow);
  isRows.push([]);

  buildISSection("Operating Expenses", AccountClassification.OPERATING_EXPENSE);
  buildISSection("Other Income (Expenses)", AccountClassification.OTHER_INCOME_EXPENSE);

  const netIncRow: (string | number)[] = ["NET INCOME"];
  periods.forEach(p => {
    let income = 0;
    accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT).forEach(acc => {
      const act = getMonthlyActivity(acc.id, p, transactions, accounts);
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) income += act;
      else income -= act;
    });
    netIncRow.push(income);
  });
  isRows.push(netIncRow);

  const isSheet = XLSX.utils.aoa_to_sheet(isRows);
  XLSX.utils.book_append_sheet(wb, isSheet, "Income Statement");

  // --- 2. BALANCE SHEET ---
  const bsRows: any[] = [
    [`${companyName} - BALANCE SHEET`],
    [`Exported: ${new Date().toLocaleDateString()}`],
    [],
    ["Account / Line Item", ...periods]
  ];

  const buildBSSection = (title: string, classifications: AccountClassification[]) => {
    bsRows.push([title.toUpperCase()]);
    classifications.forEach(cls => {
      const filtered = accounts.filter(a => a.classification === cls && a.financialStatement === FinancialStatement.BALANCE_SHEET);
      filtered.forEach(acc => {
        const row: (string | number)[] = [indent(acc.name)];
        periods.forEach(p => row.push(getCumulativeBalance(acc.id, p, transactions, accounts)));
        bsRows.push(row);
      });
    });
    const totalRow: (string | number)[] = [`TOTAL ${title.toUpperCase()}`];
    periods.forEach(p => {
      let total = 0;
      classifications.forEach(cls => {
        accounts.filter(a => a.classification === cls && a.financialStatement === FinancialStatement.BALANCE_SHEET).forEach(a => {
          const bal = getCumulativeBalance(a.id, p, transactions, accounts);
          if (cls === AccountClassification.EQUITY || cls === AccountClassification.CURRENT_LIABILITY || cls === AccountClassification.LONG_TERM_LIABILITY) {
            total += (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
          } else {
            total += bal;
          }
        });
      });
      totalRow.push(total);
    });
    bsRows.push(totalRow);
    bsRows.push([]);
    return totalRow;
  };

  buildBSSection("Assets", [AccountClassification.CURRENT_ASSET, AccountClassification.LONG_TERM_ASSET]);
  buildBSSection("Liabilities", [AccountClassification.CURRENT_LIABILITY, AccountClassification.LONG_TERM_LIABILITY]);

  bsRows.push(["EQUITY"]);
  const equityAccs = accounts.filter(a => a.classification === AccountClassification.EQUITY);
  equityAccs.forEach(acc => {
    const row: (string | number)[] = [indent(acc.name)];
    periods.forEach(p => row.push(getCumulativeBalance(acc.id, p, transactions, accounts)));
    bsRows.push(row);
  });

  const earningsRow: (string | number)[] = [indent("Current Period Earnings")];
  periods.forEach(p => {
    let totalCredits = 0;
    let totalDebits = 0;
    const isIds = new Set(accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT).map(a => a.id));
    const [year, month] = p.split('-').map(Number);
    const cutoffStr = `${year}-${String(month).padStart(2, '0')}-${String(new Date(year, month, 0).getDate()).padStart(2, '0')}`;
    transactions.forEach(tx => {
      if (tx.date <= cutoffStr) {
        tx.lines.forEach(l => {
          if (isIds.has(l.accountId)) {
            totalDebits += l.debit;
            totalCredits += l.credit;
          }
        });
      }
    });
    earningsRow.push(totalCredits - totalDebits);
  });
  bsRows.push(earningsRow);

  const totalEquityRow: (string | number)[] = ["TOTAL LIABILITIES & EQUITY"];
  periods.forEach((p, idx) => {
    let lTotal = 0;
    [AccountClassification.CURRENT_LIABILITY, AccountClassification.LONG_TERM_LIABILITY].forEach(cls => {
      accounts.filter(a => a.classification === cls).forEach(a => {
        const bal = getCumulativeBalance(a.id, p, transactions, accounts);
        lTotal += (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
      });
    });
    let eTotal = equityAccs.reduce((sum, a) => {
      const bal = getCumulativeBalance(a.id, p, transactions, accounts);
      return sum + (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
    }, 0);
    const earnings = Number(earningsRow[idx + 1]) || 0;
    totalEquityRow.push(lTotal + eTotal + earnings);
  });
  bsRows.push(totalEquityRow);

  const bsSheet = XLSX.utils.aoa_to_sheet(bsRows);
  XLSX.utils.book_append_sheet(wb, bsSheet, "Balance Sheet");

  // --- 3. CASH FLOW STATEMENT ---
  const cfRows: any[] = [
    [`${companyName} - STATEMENT OF CASH FLOWS`],
    [`Exported: ${new Date().toLocaleDateString()}`],
    [],
    ["Activity Group", ...periods]
  ];

  const cashAccountIds = accounts.filter(a => a.classification === AccountClassification.CURRENT_ASSET && (a.name.toLowerCase().includes('cash') || a.name.toLowerCase().includes('bank'))).map(a => a.id);

  cfRows.push(["OPERATING ACTIVITIES"]);
  const niRow: (string | number)[] = [indent("Net Income")];
  const depRow: (string | number)[] = [indent("Depreciation Adjustment")];
  const wcRow: (string | number)[] = [indent("Changes in Working Capital")];
  const opsTotalRow: (string | number)[] = ["Net Operating Flow"];

  periods.forEach(p => {
    let ni = 0;
    accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT).forEach(acc => {
      const act = getMonthlyActivity(acc.id, p, transactions, accounts);
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) ni += act;
      else ni -= act;
    });
    niRow.push(ni);

    const depExp = accounts.find(a => a.name.toLowerCase().includes('depreciation') && a.financialStatement === FinancialStatement.INCOME_STATEMENT);
    const dep = depExp ? getMonthlyActivity(depExp.id, p, transactions, accounts) : 0;
    depRow.push(dep);

    const assets = accounts.filter(a => a.classification === AccountClassification.CURRENT_ASSET && !cashAccountIds.includes(a.id));
    const liabs = accounts.filter(a => a.classification === AccountClassification.CURRENT_LIABILITY);
    const assetChg = assets.reduce((sum, a) => sum - getMonthlyActivity(a.id, p, transactions, accounts), 0);
    const liabChg = liabs.reduce((sum, a) => sum + getMonthlyActivity(a.id, p, transactions, accounts), 0);
    wcRow.push(assetChg + liabChg);
    opsTotalRow.push(ni + dep + assetChg + liabChg);
  });
  cfRows.push(niRow, depRow, wcRow, opsTotalRow, []);

  cfRows.push(["INVESTING ACTIVITIES"]);
  const invRow: (string | number)[] = [indent("Asset Purchases / Capex")];
  periods.forEach(p => {
    const ltAssets = accounts.filter(a => a.classification === AccountClassification.LONG_TERM_ASSET);
    invRow.push(ltAssets.reduce((sum, a) => sum - getMonthlyActivity(a.id, p, transactions, accounts), 0));
  });
  cfRows.push(invRow, ["Net Investing Flow", ...invRow.slice(1)], []);

  cfRows.push(["FINANCING ACTIVITIES"]);
  const contRow: (string | number)[] = [indent("Cash Contributions")];
  const distRow: (string | number)[] = [indent("Cash Distributions")];
  const debtRow: (string | number)[] = [indent("Net Change in Debt")];
  const finTotalRow: (string | number)[] = ["Net Financing Flow"];

  periods.forEach(p => {
    const [year, month] = p.split('-').map(Number);
    let cont = 0; let dist = 0; let debt = 0;
    const eqIds = accounts.filter(a => a.classification === AccountClassification.EQUITY).map(a => a.id);
    const dIds = accounts.filter(a => a.classification === AccountClassification.LONG_TERM_LIABILITY).map(a => a.id);

    transactions.forEach(tx => {
      if (tx.isClosingEntry) return;
      const d = new Date(tx.date);
      if (d.getFullYear() === year && (d.getMonth() + 1) === month) {
        if (tx.lines.some(l => cashAccountIds.includes(l.accountId))) {
          tx.lines.forEach(l => {
            if (eqIds.includes(l.accountId)) {
              const net = l.credit - l.debit;
              if (net > 0) cont += net; else if (net < 0) dist += Math.abs(net);
            }
            if (dIds.includes(l.accountId)) debt += (l.credit - l.debit);
          });
        }
      }
    });
    contRow.push(cont);
    distRow.push(dist > 0 ? -dist : 0);
    debtRow.push(debt);
    finTotalRow.push(cont - dist + debt);
  });
  cfRows.push(contRow, distRow, debtRow, finTotalRow, []);

  const changeRow: (string | number)[] = ["PERIOD CASH CHANGE"];
  const startRow: (string | number)[] = ["Opening Balance"];
  const endRow: (string | number)[] = ["CLOSING CASH POSITION"];

  periods.forEach((p, idx) => {
    const change = Number(opsTotalRow[idx + 1]) + Number(invRow[idx + 1]) + Number(finTotalRow[idx + 1]);
    changeRow.push(change);

    let startBal = 0;
    if (idx === 0) {
      startBal = accounts.filter(a => cashAccountIds.includes(a.id)).reduce((sum, a) => sum + (Number(a.startingBalance) || 0), 0);
      const [y, m] = p.split('-').map(Number);
      const cutoff = new Date(y, m - 1, 1);
      transactions.forEach(tx => {
        if (new Date(tx.date) < cutoff) {
          tx.lines.forEach(l => { if (cashAccountIds.includes(l.accountId)) startBal += (l.debit - l.credit); });
        }
      });
    } else {
      startBal = Number(endRow[idx]);
    }
    startRow.push(startBal);
    endRow.push(startBal + change);
  });
  cfRows.push(changeRow, startRow, endRow);

  const cfSheet = XLSX.utils.aoa_to_sheet(cfRows);
  XLSX.utils.book_append_sheet(wb, cfSheet, "Cash Flow");

  // --- 4. AMAZON ANALYSIS DATA ---
  if (amazonRecords.length > 0) {
    const amzPeriodSet = new Set<string>();
    const amzSkuSet = new Set<string>();
    const amzAmountMap: any = {};
    const amzCogsMap: Record<string, any> = {};

    amazonRecords.forEach(r => {
      const pk = getStandardKey(r.date);
      if (pk === "INVALID") return;
      amzPeriodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') amzSkuSet.add(r.sku);

      if (!amzAmountMap[pk]) amzAmountMap[pk] = {};
      if (!amzAmountMap[pk][r.category]) amzAmountMap[pk][r.category] = { _total: 0 };
      if (!amzAmountMap[pk][r.category][r.sku]) amzAmountMap[pk][r.category][r.sku] = {};
      if (!amzAmountMap[pk][r.category][r.sku][r.type]) amzAmountMap[pk][r.category][r.sku][r.type] = 0;

      amzAmountMap[pk][r.category][r.sku][r.type] += r.amount;
      amzAmountMap[pk][r.category]._total += r.amount;

      if (!amzCogsMap[pk]) amzCogsMap[pk] = { orderCogs: 0, refundCogs: 0, adjustmentCogs: 0 };
      const normalizedSku = r.sku.trim().toUpperCase();
      const unitCost = skuData[normalizedSku]?.cost || 0;

      if (r.type === 'Order') amzCogsMap[pk].orderCogs += (r.quantity * unitCost);
      else if (r.type === 'Refund') amzCogsMap[pk].refundCogs += (r.quantity * unitCost);
      else if (r.type === 'Adjustment' || r.category === 'FBA reimbursement') amzCogsMap[pk].adjustmentCogs += (r.quantity * unitCost);
    });

    const amzPeriodsSorted = Array.from(amzPeriodSet).sort((a, b) => {
      const monthsMap: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
      const parse = (s: string) => new Date(2000 + parseInt(s.slice(3)), monthsMap[s.slice(0, 3)]).getTime();
      return parse(a) - parse(b);
    });

    const getAmzAmt = (period: string, cat: string, sku?: string) => {
      const p = amzAmountMap[period];
      if (!p || !p[cat]) return 0;
      if (!sku) return p[cat]._total;
      return Object.values(p[cat][sku] || {}).reduce((s: any, v: any) => s + v, 0);
    };

    // SHEET 4.1: AMAZON REVENUE
    const amzRevRows: any[] = [
      [`${companyName} - AMAZON PRODUCT SALES`],
      ["Product / SKU", ...amzPeriodsSorted]
    ];
    Array.from(amzSkuSet).sort().forEach(sku => {
      const row: (string | number)[] = [skuData[sku]?.name || sku];
      amzPeriodsSorted.forEach(p => row.push(getAmzAmt(p, 'Revenue', sku)));
      amzRevRows.push(row);
    });
    const amzSheetRev = XLSX.utils.aoa_to_sheet(amzRevRows);
    XLSX.utils.book_append_sheet(wb, amzSheetRev, "Amazon Revenue");

    // SHEET 4.2: AMAZON FEES
    const FEE_CATEGORIES = [
      'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
      'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
      'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees'
    ];
    const amzFeeRows: any[] = [
      [`${companyName} - AMAZON FEE BREAKDOWN`],
      ["Category", ...amzPeriodsSorted]
    ];
    FEE_CATEGORIES.forEach(fee => {
      const row: (string | number)[] = [fee];
      amzPeriodsSorted.forEach(p => {
        const val = getAmzAmt(p, fee);
        row.push(fee === 'FBA reimbursement' && val > 0 ? -val : Math.abs(val));
      });
      amzFeeRows.push(row);
    });
    const amzSheetFees = XLSX.utils.aoa_to_sheet(amzFeeRows);
    XLSX.utils.book_append_sheet(wb, amzSheetFees, "Amazon Fees");

    // SHEET 4.3: AMAZON PROFITABILITY
    const amzProfRows: any[] = [
      [`${companyName} - AMAZON RECONCILIATION & COGS`],
      ["Metric", ...amzPeriodsSorted]
    ];
    const metrics = [
      { name: "Total Revenue (Net)", calc: (p: string) => getAmzAmt(p, 'Revenue') },
      { name: "Reported Transfers", calc: (p: string) => Math.abs(getAmzAmt(p, 'Transfer')) },
      { name: "Est. Order COGS", calc: (p: string) => amzCogsMap[p]?.orderCogs || 0 },
      { name: "Adjustment COGS", calc: (p: string) => amzCogsMap[p]?.adjustmentCogs || 0 },
      { name: "Gross Profit (Amazon)", calc: (p: string) => {
          const trans = Math.abs(getAmzAmt(p, 'Transfer'));
          const cogs = (amzCogsMap[p]?.orderCogs || 0) + (amzCogsMap[p]?.adjustmentCogs || 0) - (amzCogsMap[p]?.refundCogs || 0);
          return trans - cogs;
      }}
    ];
    metrics.forEach(m => {
      const row: (string | number)[] = [m.name];
      amzPeriodsSorted.forEach(p => row.push(m.calc(p)));
      amzProfRows.push(row);
    });
    const amzSheetProf = XLSX.utils.aoa_to_sheet(amzProfRows);
    XLSX.utils.book_append_sheet(wb, amzSheetProf, "Amazon Profitability");
  }

  XLSX.writeFile(wb, `${companyName.replace(/\s+/g, '_')}_Financials_${new Date().toISOString().slice(0, 10)}.xlsx`);
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
